local _, addonTable = ...

local book = {
    [10022] = { [1] = "Цей доказ правоти призначений для підтвердження того, що {ім'я:н} {стать:вбив:вбила} Марґол Люту, лихо Випаленої ущелини.\n\nМузей Залізогарту визнає це досягнення та дякує {стать:власнику:власниці} за щедрий внесок.\n\n-Головний куратор Торій Камнеглад" },
    [10789] = { [1] = "Інженерні дисципліни\n\nМожна довго сперечатися, яка раса першою додумалась до інженерної справи в Азероті, але в сучасному світі найбільшого успіху досягли гноми та гобліни. Їхня відданість інженерній справі не лише сприяла фантастичним винаходам в епоху магічних відкриттів, але і породила інтенсивну конкуренцію між расами. Ніде це не проявляється так яскраво, як на шляхах розвитку їхньої науки.", [2] = "Інженерія гномів\n\nГноми досягли успіху в конструюванні предметів, призначених для маніпулювання та контролю над навколишнім світом. Хоч вони зазвичай розробляють вибухівку та зброю, інженерна справа гномів в основному зосереджена на предметах, які в буквальному сенсі намагаються зробити життя простішим та доступнішим. Це дисципліна теоретичних можливостей, що стають реальністю завдяки досягненням гномів. Але, на жаль, деякі можливості все ж не вийде реалізувати повністю.", [3] = "Інженерія гоблінів\n\nЯк раса, що зберігає нейтралітет майже в кожному конфлікті, гобліни зробили багато, щоб перетворити науку на прибуткову справу. Вони застосовують інженерну справу на практиці, про що свідчать їхні просунуті розробки вибухових речовин, вогнепальної зброї та машин. Гобліни-інженери не дуже цікавляться теорією, їхні винаходи зазвичай не мають проблем з тим, що вони не працюють, а радше працюють занадто добре. Це точно не для слабкодухих.", [4] = "Вивчення дисципліни\n\nГноми та гобліни настільки добре захищають свої розробки один від одного, що отримати доступ до обох напрямків цієї науки одночасно практично неможливо. Кожна раса, незалежно від політичних поглядів, надає знання цих дисциплін лише для тих, хто погоджується відмовитися від вивчення дисципліни іншої раси. Наприклад, якщо учень вирішив вивчати інженерну справу гномів, то він ніколи не отримає знань від гоблінів.", [5] = "Незворотність вибору\n\nУ попередньому розділі було висвітлено важливий момент щодо двох інженерних дисциплін, який необхідно засвоїти в інтересах освіти. Рішення займатися однією з двох дисциплін означає, що знання протилежної дисципліни будуть недоступні для вивчення. Хоч такий вибір може лякати інженера-початківця, досвідчений інженер розуміє, що гноми та гобліни надто добре охороняють свої секрети, тож краще мати хоч якісь знання, ніж не мати ніяких.", [6] = "Цитати\n\n\"Хочеш дізнатися про інженерну справу гоблінів? Спробуй поговорити про це з одним з їхніх найкращих і найрозумніших інженерів — здається, його звуть \"Наббі Товстопалець\". Хочеш дізнатись, чому його так назвали? Це і є гоблінська інженерія.\"\n— Рінґо Трагедікс, гном-інженер\n\n\"Думай про нас, гоблінів, що хочеш, але ось, що я тобі скажу: У НАС Є ВИБУХІВКА!\"\n— Язз Нітросполох, гоблін-бомбардувальник.", [7] = "Більше цитат!\n\n\"Знаєш відчуття, коли ти закінчуєш робити пристрій та вперше вмикаєш його, щоб відчути його силу і радість, коли він оживає? Гноми цього не знають.\"\n- Нікс Вертопружень, майстер гоблінської інженерії Пристробляху\n\n\"Інженерна справа — це коли ти береш фантазію і робиш щось ще більш фантастичне!\"\n— Ровіс МакШтовхогуп, гном-винахідник" },
    [10832] = { [1] = "Виклик звіра:\n\nЩоб викликати скверношукача, ви маєте використати сферу Скверни.\n\nПримітки:\n\nВикликаний скверношукач може перебувати в цьому світі лише тридцять хвилин.\n\nВикликаний скверношукач допоможе вам лише у пошуку відкладень азшариту.\n\nВикликаний скверношукач НЕ БУДЕ робити наступне: виконувати трюки, атакувати, допомагати, танцювати, знищувати арканічних істот.\n\nБудь ласка, перегорніть сторінку...", [2] = "Контроль над звіром:\n\nСкверношукачі реагують тільки на звіриний рик. Щоб змусити вашого скверношукача шукати відкладення азшариту, потрібно сильно загарчати на нього! Наведіть на скверношукача та гаркніть (/roar).\n\nКоли він знайде відкладення, то побіжить до них, не зважаючи на істот, які будуть на його шляху. Хоч вам і не потрібно захищати скверношукача, але вам варто триматися поруч, щоб не втратити його.", [3] = "Відпустити звіра:\n\nЧерез тридцять хвилин звір повернеться до своєї домівки в Підсвіття.\n\nПримітка:\n\nПід час того, як звір буде слідувати до чогось, він МОЖЕ зірватися зі скелі або впасти з гори. Не оплакуйте втрату скверношукача, просто викличте іншого замість нього." },
    [10839] = { [1] = "Тому, кого це стосується:\n\nЯкщо ти читаєш цю записку, значить ти перебуваєш в одному з двох місць:\n\n(1) На південному півострові Азшари.\n\n(2) В череві скельного велетня.\n\nОбидва місця однаково небажані.\n\nСлід зазначити, що я колись був у першому місці, а на момент написання цього листа, знаходжуся в другому.", [2] = "В череві велетня з'являється багато часу на роздуми\n\nПоки моє тіло кристалізується, я дійшов висновку, що, мабуть, у цьому світі достатньо героїв. Якщо я якось виберуся з цієї халепи, то скручу примарну шию цього орка!\n\n— Віндан Шей" },
    [10840] = { [1] = "Про що я думав?\n\nМожливо, краще було б запитати: про що я думаю, пишучи записку, сидячи в череві велетня?\n\nОбидва питання хороші, і на жодне з них у мене немає відповіді...\n\nСлід визнати, що моя місія не несла добрі наміри. Я прийшов у пошуках азшариту, унікального кристала з південної Азшари. Ой, яким же багатим я б був!\n\nХа! І подивіться тепер на мене...", [2] = "Якщо якась розумна істота знайде цю записку, нехай запитає себе: \"Якого біса я панькаюсь з цими жахливими десятиметровими велетнями?\"\n\n- Мук" },
    [11125] = { [1] = "Брате Нілсе,\n\nМій виноград врятовано! {Ім'я:н}, {стать:той, хто приніс:та, що принесла} тобі цього листа, не {стать:злякався:злякалася} мого наповненого злодіями виноградника і {стать:зібрав:зібрала} врожай, який я не змогла. Хоч Непокірні й досі вештаються вздовж річки, майже весь мій урожай був врятовано.\n\nТож сміливо можеш заставляти полички виноградом у своїй крамниці.\n\nНехай Світло захистить нас,\n— Міллі Осворт" },
    [11368] = { [1] = "Соломон,\n\nНосію цього указу надається офіційний статус {стать:заступника:заступниці} Штормовію. Ви можете скористатися {стать:його:її} допомогою для пошуку доказів причетності Крила чорних драконів до діянь орків Чорнокаменю. Якщо такі докази будуть знайдені, {стать:заступник:заступниця} має повернути їх мені в Штормовій і тоді я віддам наказ про виділення необхідної кількості військових сил для допомоги Приозер'ю.\n\nЗ повагою,\n\n\n\nверховний лорд Болвар Фордраґон" },
    [11482] = { [1] = "ПОСІБНИК З ВИКОРИСТАННЯ КРИШТАЛЕВОГО ПІЛОНА\n\n\"Посібник зі збору та використання кристалів сили з кратера Ун'Ґоро\"\n\nРозділ 1: Північний пілон\n\nРозділ 2: Східний пілон\n\nРозділ 3: Західний пілон", [10] = "ДІАГРАМА ЗАХІДНОГО ПІЛОНА", [2] = "Розділ 1: ПІВНІЧНИЙ ПІЛОН\n\nПівнічний\nпілон приймає\nжовті, червоні\nта зелені\nкристали.\n\n\n\n\nПілон використовує енергію жовтих кристалів, як основне джерело живлення.", [3] = "Комбінації кристалів північного пілона\n\nІснує два можливих ефекти: перший — спричиняє шкоду, а другий скасовує її.\n\nКРИСТАЛІЧНИЙ ЗАРЯД: потрібні червоні та жовті кристали.\nЦе призведе до великого вибуху.\n\nКРИСТАЛІЧНЕ ВІДНОВЛЕННЯ: потрібні жовті та зелені кристали.\nЦе забезпечить вам цілющу ауру.", [4] = "ДІАГРАМА ПІВНІЧНОГО ПІЛОНА", [5] = "Розділ 2: СХІДНИЙ ПІЛОН\n\n\nСхідний\nпілон приймає\nсині, жовті\nта зелені\nкристали.\n\n\n\n\nПілон використовує енергію синіх кристалів, як основне джерело живлення.", [6] = "Комбінації кристалів східного пілона\n\nІснує два можливих ефекти: один надає ефект підвищення духу, а інший створює щит, який завдає шкоди ворогам.\n\nКРИСТАЛІЧНА СИЛА: потрібні сині та зелені кристали.\nЦе збільшує ваш дух.\n\nКРИСТАЛІЧНЕ ВІСТРЯ: потрібні сині та жовті кристали.\nЦе створить щит, який завдаватиме шкоди нападникам.", [7] = "ДІАГРАМА СХІДНОГО ПІЛОНА", [8] = "Розділ 3: ЗАХІДНИЙ ПІЛОН\n\n\nЗахідний\nпілон приймає\nчервоні, зелені\nта сині\nкристали.\n\n\n\n\nПілон використовує енергію червоних кристалів, як основне джерело живлення.", [9] = "Комбінації кристалів західного пілона\n\nІснує два можливих ефекти: один збільшує ваш захист від шкоди, а інший послаблює захист ворога.\n\nКРИСТАЛІЧНИЙ ЗАХИСТ: потрібні червоні та зелені кристали.\nЦе збільшить вашу броню.\n\nКРИСТАЛІЧНЕ ПОСЛАБЛЕННЯ: потрібні сині та червоні кристали.\nЦе зменшить броню обраної цілі." },
    [11727] = { [1] = "Вітаю вас, шукачі пригод!\n\nЯ, Крінкл Файносталь, шукаю тих, хто готовий наразити себе на небезпеку, щоб виконати кілька моїх найважчих завдань. Зважаючи на кількість моїх обов'язків та обсяг роботи, яку я взяв на себе, я гарантую, що кожен, хто зможе зібрати предмети з цього переліку і принести їх мені неушкодженими, отримає щедру винагороду.\n\nПерелік міститься на наступних сторінках...", [2] = "Міцні кришталеві лапи —\n\nКришталеві павуки Випаленої ущелини зроблені з неймовірного матеріалу, схожого на кристал. Їхні лапи, якщо їх не пошкодити, стануть чудовим провідником у деяких інженерних витворах моїх колег.\n\nМені знадобиться кілька таких лап для експериментів. Павуки можуть мати до восьми таких лап, тому це не повинно бути проблемою для {стать:витривалого воїна:витривалої воїтельки} чи {стать:досвідченого мага:досвідченої магині}.", [3] = "Затриманий пакунок —\n\nЯ найняв декого, кого вважав надійним пілотом, щоб привезти мені пакунок з Терамору. Але, як виявилось, я помилявся. Хоч пілот і вижив, та він кинув і свій дирижабль, і весь мій вантаж, щоб врятувати власну шкуру.\n\nЩо ж, мені потрібно повернути цей пакунок. Бізіль сказав, що він розбився на заході від бухти в Бруднолипкій трясовині. Він почав падати відразу після того, як перетнув пагорби вздовж берегу.\n\nХм... Він так і не розказав мені, що стало причиною аварії...", [4] = "Збалансований фламберг Файносталя —\n\nНарешті, я хочу повернути один з моїх найкращих ковальських витворів. Цей фламберг — неймовірна зброя, і я подарував його тому, кого я вважав вельми шляхетним та великим воїном. Коротко кажучи, його побив мурлок, на ім'я... Джаркай? Якось так.\n\nЦе сталося, коли він проходив по узбережжю болота Скорбот і вирішив вбити цю істоту. Йому це не вдалося, і він, очевидно, втік, але перед тим залишив зброю мурлоку.", [5] = "Знайди ці речі та принеси їх в Пристроблях разом з цією книгою і я винагороджу тебе." },
    [11732] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення малого магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий" },
    [11733] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення малого магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий" },
    [11734] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення малого магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий" },
    [11736] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення малого магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий" },
    [11737] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення малого магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий" },
    [11886] = { [1] = "Термінове повідомлення для спостерігача скель Довгорогого\n\nВеликий загін кентаврів із табору І'ток напав на один із наших караванів з припасами. Всі члени каравану загинули, а всі припаси втрачено. Це був зухвалий, безпрецедентний напад кентаврів, і я боюся, що далеко не останній." },
    [1208] = { [1] = "Томмі-Джо,\n\nз кожною годиною моє серце в'яне через розлуку з тобою. О, якби ж тільки наші родичі могли відсторонитися від дурної помсти за скоєні злодіяння один перед одним, то зрозуміли б, що єдиний справжній злочин — це ненависть. Ненависть пожирає душі, і я боюся, що в ці похмурі часи ненависть не обмежиться лише нашими родинами.\n\nЯкби вони тільки могли це зрозуміти, то і ми могли б нарешті бути разом. Я так чекаю на цей день, і заради цього дня я живу.\n\nТвоя кохана,\nМейбелл" },
    [12438] = { [1] = "Привіт, Фелнок!\n\nМої дослідження в Палаючих степах просуваються чудово. І я дуже завдячую {ім'я:д} за всю {стать:його:її} допомогу! Ось що мені потрібно для продовження:\n\nБампер-бітцель зі сталевою котушкою\nЛьодоверт на 17\n12 фунтів качиного пір'я\nБанка твого клею\n\nДуже дякую, Фелнок, і коли ми побачимося знову, нагадай, щоб я не підкладала вугілля у твої черевики!\n\n-Тінкі" },
    [1252] = { [1] = "Вітаю, Вільяме,\n\nМинуло багато років відколи ми бачились, але я сподіваюся, що у вас з братом все добре, і що ваша аптека й досі процвітає.\n\nЯ маю до тебе прохання, Вільяме. Коротко кажучи, мій онук Томмі-Джо втратив голову від кохання до Мейбелл Маклур. І хоча вони обожнюють один одного... наші сім'ї… ворогують вже багато років.", [2] = "Я побоююсь, що війна між Кам'янопільськими та Маклурами вб'є квітучий роман Томмі-Джо та Мейбелл. А в такі часи, коли над нами нависають похмурі новини та чутки про війну, юність та кохання треба плекати особливо турботливо.\n\nОтже, прохання: прошу, використай свої навички та приготуй зілля чи еліксир, щоб допомогти цим молодим закоханим у їхніх пошуках одне одного.\n\nДякую, Вільяме. І, будь ласка, коли в тебе з'явиться вільний час від роботи, завітай до мене. Згадаємо славні минулі часи.\n\n— Мілдред" },
    [12562] = { [1] = "Змійталак,\n\nЯ отримав прямий наказ від твого володаря, Нефаріана, покарати тебе так, як вважатиму за потрібне, якщо хтось із чужинців проникне до цитаделі.\n\nНе забувай, хто тут командує, ящірко.\n\nСин Чорнорука: володар клинка і битви. Єдиний істинний воєводжь.\n\n-Ренд" },
    [12635] = { [1] = "Тром-ка, {клас:к}. Мене не цікавлять твої подвиги — це справи минулого. Коли ти востаннє {стать:вбивав:вбивала} людину? Певне, що давно. Ти слабшаєш, втрачаєш хватку без діла.\n\nМені тут потрібна ще одна пара рук, а тобі, що б там про тебе не казали, потрібні мої тренування. Як усвідомиш це — приходь до мене, я буду під навісом біля Лігва.\n\n-Франґ, тренер воїнів" },
    [12730] = { [1] = "Ох, я проклятий! Колись я був великим огром-магом з клану Кам'яного Шпиля, та я кинув виклик Уроку Згубореву, а він вкрав мою магію і прокляв мене. Тепер я повинен ходити залами Ордемара у вигляді цього жалюгідного створіння!\n\nДопоможи мені! Зустрінься з Уроком і поверни мою магію! Це буде нелегко, бо Урок залишається в тіні й може бути викликаний лише через велике випробування.\n\nЦим випробуванням буде смерть його вірного помічника, верховного повелителя Омокка.\n\nЧитай далі, і побачиш.", [2] = "Верховний повелитель Омокк править кланом Кам'яного Шпиля, але робить він це за допомогою магії Урока. Урок зачарував Омокка заклинанням, яке може вбити будь-якого огра, що кине йому виклик. Він використовував це закляття багато разів і зберігає черепи своїх жертв у купі, в місці сили над палатою Омокка.\n\nСаме туди ти маєш піти, щоб зустрітися з Уроком.", [3] = "Знайди грубий спис в таборі Рубаного Щита. Вони часто складають їх біля своїх наметів поруч з входом у володіння Кам'яного Шпиля.\n\nКоли знайдеш спис, прямуй до верховного повелителя Омокка. Убий його і настроми його голову на спис.\n\nТоді ти маєш приготуватися до справжнього випробування.", [4] = "Вирушай до місця сили над володіннями Кам'яного Шпиля, за тунелями Жевріючої Павутини. У цьому місці зібрані черепи ворогів і суперників Урока. Саме сюди ти маєш встромити спис з головою Омокка!\n\nКоли голова буде на місці, Урок обов'язково прийде... але спочатку він пошле своїх поплічників. Вбий їх, і з часом з'явиться сам Урок.\n\nУбий Урока і поверни мою магію. Повернувши свої сили, я винагороджу тебе.", [5] = "Щасти тобі. А ось підказка, яка може допомогти у випробуваннях проти поплічників Урока:\n\nЗаклинання, яке Омокк використовує, щоб вбивати огрів, може продовжувати діяти й після смерті Омокка. Під час битви з поплічниками Урока використовуй силу, що знаходиться в голові Омокка — якщо пощастить, Омокк знищить поплічників Урока!\n\nЯка іронія." },
    [12765] = { [1] = "Аґашаме,\n\nНаші плани мають залишатися в таємниці за будь-яку ціну! Це буде катастрофа, якщо інші племена тауренів дізнаються про нашу приналежність.\n\nПідписано,\n\nПровісник Ільм" },
    [12766] = { [1] = "Аґашаме,\n\nПрацюючи разом, ми будемо могутнішими за всі племена тауренів разом узяті! Проте ми вимагаємо вашої повної покірності. Пам'ятай, ви отримаєте винагороду лише після втілення наших планів!\n\nПідписано,\n\nПровісник Рекс\nВісник Рекс" },
    [12768] = { [1] = "Аґашаме,\n\nНаші агенти з Лордерона незабаром зустрінуться з вашими представниками. Ми повідомимо вам, щойно знайдемо відповідне місце для зустрічі.\n\nПідписано,\n\nПровісник Ґрак" },
    [1283] = { [1] = "Арґусе,\n\nЯк ти знаєш, я по вуха завалений замовленнями від армії. Не можу скаржитися на роботу, але вона виснажує всі мої запаси заліза.\n\nМені не вистачає заліза навіть на підкови. Я знаю, що у тебе завжди є великий запас — тож я хотів би позичити 50 пар, поки не отримаю наступну партію заліза.\n\nЩиро вдячний,\n-Вернер" },
    [1284] = { [1] = "До ящика прикріплена записка. У ній сказано:\n\n\"Вернере — сумно чути, що в Багрянокряжжі такі проблеми. Ось підкови, які ти просив. Будь ласка, відправ мені 100 срібняків за першої нагоди\".\n\n\"Або, якщо хочеш, можеш заплатити мені підчеревною лускою дитинчат чорного дракона (я чув, що в Багрянокряжових горах їх багато водиться). Оскільки ми друзі... 4 лусочок буде достатньо. Дякую --Арґус\"." },
    [12900] = { [1] = "Літопис Дарроушира\n\nСелище Дарроушир, назване на честь озера Дарроумер, розташоване на схід від цього озера, на південному кордоні Лордерона. Відомий своїми скромними, але працьовитими мешканцями, Дарроушир залишався непоміченим в історії Лордерона до Другої війни.\n\nПід час цієї війни з'явилися герої. Про яких згодом забули.", [2] = "Битва при Дарроуширі\n\nБитва при Дарроуширі відбулася в середині Другої війни, коли Скара лютувала в Лордероні. Хоч Дарроушир був відрізаний від основних сил Альянсу, але він мав власний загін воїнів, підрозділ паладинів Сріблястої Десниці та відважне місцеве ополчення на чолі з капітаном Джозефом Редпатом.", [3] = "Перші напади Скари на Дарроушир були незначними. Атаки невеликих груп скелетів і мерців, що блукали околицями селища, з легкістю відбивались його захисниками.\n\nАле Скару не зупинила завзятість захисників і невдовзі після селище зазнало нових атак. Відбірні гулі, слуги повелителя гулів Горґуса, спустилися з пагорбів і вступили в бій з захисниками Дарроушира.", [4] = "Захисники ослабли, але їм на допомогу прийшли паладини Сріблястої Десниці. Їхній лідер, Дейвіл Крокфорд, був родом з Дарроушира. Почувши про напад, він привів до селища своїх побратимів, і разом із захисниками вони зупинили слуг Горґуса.\n\nКоли Горґус вийшов на поле бою, Дейвіл виступив проти нього. Вони довго билися і врешті-решт Дейвіл переміг, але отримав смертельну рану і помер незабаром після перемоги над повелителем гулів.", [5] = "Битва тривала, і капітан Редпат хоробро вів своє ополчення. І битва могла б завершитися перемогою, якби не магія лицаря смерті Мардука Чорного.\n\nУ розпал битви Мардук наблизився до Редпата і за допомогою чорної магії вирвав його дух, перетворивши хороброго капітана в злу тінь.", [6] = "Скверна капітана Редпата поширилась серед інших захисників Дарроушира, які після цього зрадили своїх союзників і вбили їх. Потім вони напали на Дарроушир і вбили всіх, хто ховався у своїх домівках.\n\nРештки армії Скари, разом із чорним духом капітана Редпата, залишили спустошене селище і вдерлися до Лордерону, несучи з собою біль і смерть Другої війни." },
    [1293] = { [1] = "Мілорде,\n\nВійна наближається. Зла доля стоїть на порозі нашого дому.\n\nЯк війт містечка Приозер'я, мій обов'язок — повідомити про нещодавні військові дії, що відбулися у найсхіднішій колонії Його Величності.\n\nНа цих сторінках ви знайдете звіт про стан справ Приозер'я, розташованого в Багрянокряжових горах.", [2] = "Втрата фортеці Кам'яної Варти стала для нас серйозним ударом. У попередніх звітах я детально розповідав вам про союз між орками з клану Чорнокаменю та чаклуном, відомим як Морґант. Орки клану Чорнокаменю билися з жахливою жорстокістю, безсумнівно, підживлювані злою магією Морґанта. Багато найвідважніших воїнів Його Величності віддали свої життя, намагаючись захистити фортецю, але, зрештою, поразка була неминуча.", [3] = "Дивно, але Морґант повстав проти орків невдовзі після їхньої жалюгідної перемоги. Чорнокнижник побудував таємничу вежу на північному сході та використав свої сили, щоб зібрати невелику армію Тінeшкурих гнолів, які втілюють його злі задуми. Як орки, так і люди стали жертвами жорстоких моцаків, що служать чорнокнижнику. Щодо того, чому Морґант зрадив Ґат'Ільзоґґа, воєводу клану Чорнокаменю, наразі можна лише здогадуватися.", [4] = "На жаль, цих смердючих орків, здається, більше цікавить за винищення підданих Його Величності. Два тижні тому клан Чорнокаменю влаштував безжальну різанину в Приозер'ї. Того жахливого дня загинуло багато хоробрих воїнів. Сили орків наступали з такою швидкістю і люттю, що міст через Безхвильне озеро було зруйновано. Наші запаси виснажені. Нам навіть не вистачає бинтів, щоб перев'язати рани полеглих.", [5] = "Зараз я прошу Його Величність підтримати добрих людей Приозер'я в цей скрутний час. Нам потрібні нові солдати для захисту земель, а також нові бойові знаряддя замість втрачених на полі бою. Також закінчуються наші запаси їжі та будівельних матеріалів. Будь ласка, мілорде, допоможіть нам зберегти останній бастіон людей на шляху жахливих орків. Ворог не має потрапити до Королівства Штормовій.", [6] = "Я боюся, що в котлі скверни, на які перетворилися Північні землі, назріває ще більш могутнє і жахливе зло. Королівству Штормовій вкрай необхідно вжити заходів, щоб ми не стали згадкою для живих або рабами для ворога.\n\nПідпис,\n\nВійт Соломон\nМістечко Приозер'я\nКоролівство Штормовій" },
    [1294] = { [1] = "Шановний війт Соломон:\n\nЯ оплакую разом з вами загиблих. Я особисто потурбуюся про те, щоб король був поінформований про ситуацію, і дуже сподіваюся, що зможу послати підкріплення до Приозер'я. Його Величність останнім часом небагатослівний і поводиться досить дивно. Я ділюся з вами цим по секрету.\n\nДо зустрічі,\n\nГенерал Марк Джонатан\nКоролівство Штормовій" },
    [13158] = { [1] = "Вороги... з усіх сторін.\n\nЦе видно по їх очах. Деревопузі — це зло. Вороги.\n\nМушу захистити плем'я. Мушу захистити Зимокрайових. Мушу вигнати чужинців з нашої землі.", [2] = "Сніг, сліпучий...\n\nМушу захистити плем'я. Зробити їх сильними. Бути сильним.\n\nЯ не знаю...", [3] = "Огневиця.\n\nПринесіть ще. Більше вогняної води.\n\nВогняна вода зробить Зимокрайових сильними. Переможемо наших ворогів.\n\nУ Зимокрайових немає союзників. Зимокрайові сильні. Мають велику силу.", [4] = "Більше. Треба більше...\n\nЗимокрайові... не... слабкі..." },
    [13202] = { [1] = "Літопис Дарроушира\n\nСелище Дарроушир, назване на честь озера Дарроумер, розташоване на схід від цього озера, на південному кордоні Лордерона. Відомий своїми скромними, але працьовитими мешканцями, Дарроушир залишався непоміченим в історії Лордерона до Другої війни.\n\nПід час цієї війни з'явилися герої. Про яких згодом забули.", [10] = "Доля Джозефа Редпата\n\nДжозеф Редпат загинув під час битви при Дарроуширі. Його покалічена душа прийняла форму істоти, яка принесла велике зло Лордерону.\n\nУ Посусі Ґаррона, що на схід від Андорала, спотвореного Редпата остаточно перемогли війська Альянсу. Його щит все ще лежить біля комори на чумній фермі, а поплічники Скари все ще тягнуться до пам'ятки про його зло.", [11] = "Доля Карліна Редпата\n\nКарлін, брат капітана Джозефа Редпата, був важко поранений під час битви при Дарроуширі, але йому вдалося вижити.\n\nЧерез кілька днів після битви Сріблястий Світанок знайшов Карліна, який блукав, знесилений від спраги та лихоманки, поблизу перехрестя Коріна. Вони обробили його рани та привели його до Каплиці Надії Світла.\n\nВдячний Карлін приєднався до лав Сріблястого Світанку і тепер бореться зі Скарою, прагнучи помститися тим, хто зруйнував його дім і вбив його брата.", [2] = "Битва при Дарроуширі\n\nБитва при Дарроуширі відбулася в середині Другої війни, коли Скара лютувала в Лордероні. Хоч Дарроушир був відрізаний від основних сил Альянсу, але він мав власний загін воїнів, підрозділ паладинів Сріблястої Десниці та відважне місцеве ополчення на чолі з капітаном Джозефом Редпатом.", [3] = "Перші напади Скари на Дарроушир були незначними. Невеликі групи скелетів і мерців, що блукали околицями селища, з легкістю розбивались його захисниками.\n\nАле Скара відчула завзятість захисників і невдовзі після селище зазнало нових атак. Відбірні гулі, слуги повелителя гулів Горґуса, спустилися з пагорбів і вступили в бій з захисниками Дарроушира.", [4] = "Захисники ослабли, але їм на допомогу прийшли паладини Сріблястої Десниці. Їхній лідер, Дейвіл Крокфорд, був родом з Дарроушира. Почувши про напад, він привів до селища своїх побратимів, і разом із захисниками вони зупинили слуг Горґуса.\n\nКоли Горґус вийшов на поле бою, Дейвіл виступив проти нього. Вони довго билися і врешті-решт Дейвіл переміг, але отримав смертельну рану і помер незабаром після перемоги над повелителем гулів.", [5] = "Битва тривала, і капітан Редпат хоробро вів своє ополчення. І битва могла б завершитися перемогою, якби не магія лицаря смерті Мардука Чорного.\n\nУ розпал битви Мардук наблизився до Редпата і за допомогою чорної магії вирвав його дух, перетворивши хороброго капітана в злу тінь.", [6] = "Скверна капітана Редпата поширилась серед інших захисників Дарроушира, які після цього зрадили своїх союзників і вбили їх. Потім вони напали на Дарроушир і вбили всіх, хто ховався у своїх домівках.\n\nРештки армії Скари, разом із чорним духом капітана Редпата, залишили спустошене селище і вдерлися до Лордерону, несучи з собою біль і смерть Другої війни.", [7] = "Доля Горґуса-Спустошника\n\nГорґус-Спустошник загинув у битві при Дарроуширі. Але зло, яке він ніс з собою, не було повністю знищено. Війська Скари, що перемогли в цій битві, забрали його череп з поля битви, щоб наводити жах на все живе.\n\nЗа кілька днів загін Скари, що володів головою, був розбитий паладинами Сріблястої Десниці. Голову Горґуса кинули в озеро Чорнолісся.", [8] = "Доля Мардука Чорного\n\nМардук пережив Другу війну, сіючи смерть і страждання своїм брудним рунним мечем. Хоч Мардук все ще живий, його меч було втрачено у битві при перехресті Коріна. Капітан дворфів розтрощив меч своїм зачарованим щитом, змусивши Мардука втекти з поля бою, що і принесло перемогу Альянсу.\n\nМеч Мардука встромився в землю й осквернив її, проївши ущелину в землі, тепер відому як Чумний Шрам.", [9] = "Доля Дейвіла Сяйносвіта\n\nДейвіл Сяйносвіт загинув у битві при Дарроуширі, але його хоробрість надихала Альянс протягом усієї війни.\n\nЙого манускрипт паладина був знайдений військами Багряного Походу. Тепер він зберігається в ратуші Вогнедолу, де з неї черпають силу Девіла послідовники Багряного Походу." },
    [1327] = { [1] = "Міцнокриве -\n\nЯке нахабство посилати абсолютно {стать:незнайомого мандрівника:незнайому мандрівницю} обговорювати банду Непокірних. Одного разу ти врятував мені життя, а тепер піддаєш його великій небезпеці.\n\nАле я твій боржник. Братство Непокірних більше, ніж ти думаєш. Кожна копальня від Західного краю до Ельвиннського лісу під їхнім контролем. Кобольдів і гнолів залучають до брудної роботи. Їхні гобліни створюють металевих монстрів для розміщення на полях Західного краю, щоб полювати та залякувати місцевих жителів.", [2] = "Вони побудували величезну підземну мережу. Більшу, ніж ти думаєш, Міцнокрив. Від Грабіжної Бухти аж до фортеці Штормовію. Ти можеш бути хоробрим паладином, але ти дурень, якщо думаєш, що зможеш їх зупинити. Вони працюють над зброєю масового знищення. Зрештою, якщо Каменярі щось і знають, то це будівництво. Ти ж не думав, що справа в гарбузових фермах і виноградниках, чи не так? Я відплатив борг. Тепер дай мені спокій!\n\n--В" },
    [13507] = { [1] = "Натако, в Тисячі Шипів усе гаразд. Кентаври іноді докучають, нападаючи на нас, але це не можна назвати реальною загрозою. Проте, здається, є новини про те, що вони вирішили об'єднати свої клани.\n\nМи завжди замислювались, яку загрозу становитиме така безжальна раса, як кентаври, якщо вони об'єднаються... Я намагаюся не думати про це, ти ж знаєш... їхня ненависть вічна... навіть одне до одного.\n\n— Спостерігач скель Довгорогий" },
    [1353] = { [1] = "Лорде Міцнокрив--\n\nНа чолі з Едвіном Ван-Кліфом гільдія Каменярів складалася з найвправніших будівельників серед чоловіків. Каменярі допомогли відбудувати місто Штормовій, зруйноване орками під час Першої війни. Ван-Кліф і його торговці були неперевершеними будівельниками, і їхня робота та майстерність були очевидними в будівлях собору Світла та самої фортеці Штормовію.", [2] = "Однак вельможі Штормовію набрали величезних боргів, розширивши військову діяльність королівства від Ельвинну до Тернистої долини. Величезні борги підірвали економіку королівства та позбавили Ван-Кліфа та його каменярів обіцяної винагороди. Витративши роки на відбудову славетного міста, каменярі залишилися розореними й забутими корумпованими чиновниками міста.", [3] = "Оскільки я особисто знав Едвіна Ван-Кліфа все своє життя, можу сказати, що протистояти йому як ворогу — досить складне завдання. Розумієте, він був моїм другом дитинства, і я особисто навчив його майстерності тіней, думаючи, що колись він працюватиме разом зі мною. Якщо Ван-Кліф очолює Братство Непокірних, нехай Світло помилує наші душі.\n\nМайстер Матіас Гич\nГільдія вбивць Штормовію" },
    [1358] = { [1] = "Хороша робота, друзяко! Тепер чапай на схід. На схід через кручі, на схід до дороги. Шукай на узбіччі дороги рештки старого димоходу. Там знайдеш стару бочку, в якій буде наступна підказка." },
    [1361] = { [1] = "А тепер поверни мармизу на північ від сієї бочки. Прямо, як ворон летить, чимчикуй, доки не натрапиш на порожній глечик поруч із самотнім вітряком на прибережних бескидах. Якщо ретельно потермосиш той глечик — може, знайдеш те, що шукаєш." },
    [1362] = { [1] = "Якщо вже тобі вдалося знайти мо' старий глечик з-під віскі, значить, ти близько до скарбу! Йди від пляшки на захід і спустися до берега. Як доберешся до води — не зупиняйся! Пливи на захід, доки не знайдеш острів, де є мо' скриня зі скарбом!" },
    [1381] = { [1] = "Чорнокіготь--\n\nМоре чекає на нас. Нам потрібні ваші запаси з півночі. Несіть все: кожну рейку, кожне відро. Нам потрібен метал. Вантаж має прийти з ГБ, але сильно запізнюється. Зробіть все можливе, Чорнокіготь. Цього разу висилайте свої запаси прямо в «сарай». Часу обмаль.\n\n--Ван-Кліф" },
    [1407] = { [1] = "Лорде Міцнокрив --\n\nМістечко Приозер'я смиренно просить допомоги вашого ополчення. Поки я пишу це, ми знаходимося в облозі орків Чорнокаменю та тінешкурих гнолів Морґанта. Я б не надсилав це прохання, якби ми не знаходились в надзвичайно важкій ситуації. Ми чекаємо допомоги від Штормовія, але поки вона не прибула я благаю вас про допомогу. Якщо ми не встоїмо, все людство опиниться в небезпеці.\n\nВійт Соломон" },
    [1408] = { [1] = "Ваша честь--\n\nВесь Західний край оплакує вашу втрату, але у нас йде власна війна. Фермерів пограбували злодії та механічні големи. Штормовій відкликав свої війська, залишивши людей беззахисними. Після відходу військ Штормовію я зібрав Народне ополчення, щоб врятувати те, що залишилося від цієї землі. Відвести ополчення на Багрянокряжжя означало б приректи Західний край на загибель.\n\nВибачте,\nҐріан Міцнокрив." },
    [1409] = { [1] = "Лорде Чорнобривий --\n\nМістечко Приозер'я смиренно просить допомоги у Нічної варти. Ми знаходимося в облозі орків Чорнокаменю та тінешкурих гнолів Морґанта. Я б не надсилав це прохання, якби ми не знаходились в надзвичайно важкій ситуації. Ми чекаємо допомоги від Штормовія, але поки вона не прибула я благаю вас про допомогу. Якщо ми не встоїмо, все людство опиниться в небезпеці.\n\nВійт Соломон" },
    [1410] = { [1] = "Ваша честь—\n\nЗ жалем на душі повідомляю, що Нічна варта не може покинути свій пост у Темнодолі. Напевно, вам не сказали, що Штормовій більше не надає військової підтримки в цьому регіоні. Нічна варта була сформована і підготовлена людьми лісу виключно, щоб захищати Темноділ за відсутності підтримки Штормовою. Без варти місто впаде. Бажаю удачі в боротьбі.\n\n— Лорд Елло Чорнобривий" },
    [15790] = { [1] = "УуУуУуУ УУуУУуу УУУуУуу УУуУууУ УУуУУуУ УУууууУ Уууууу УууУУУУ УУуУУУу УУуУУуу УУуУууУ УУуУУУу УУууУуУ Уууууу УууУУУу УУууууУ УУУуууу УУууууУ Уууууу УуУуУУу УУууууУ УУуУУуу УУуУУуу УУууУуУ УУУУууУ Уууууу УууУуУУ УУуУУУу УУуУууУ УУууУУУ УУуУууу УУУуУуу УУУууУУ Уууууу УУуУУУУ УУууУУу Уууууу УууууУУ УУуУууу УУууууУ УУуУУУУ УУУууУУ" },
    [15847] = { [1] = "Дата вступу: Невідома\n\nІм'я: Натанос Марріс, людина-слідопит з Лордерона.\n\nВступ:\n\nЯ взяла до відома незгоду Кель'таса щодо мого рішення прийняти Натаноса Марріса до ордену. Слід також зазначити, що Натанос, хоч і людина, але є одним з найобдарованіших слідопитів, яких я коли-небудь мала задоволення тренувати.\n\n(продовження)", [2] = "Тисячоліттями ми ховалися від чужинців. Я буду першою з нас, хто визнає, що ми помилялися в минулому. Не можна було відкривати людям магію. Я не заперечую цього, але й не хочу судити нас за помилки попередників. Спільне існування квел'дорай та інших народів цього світу може принести багато користі. Ми маємо вчитися терпимості.\n\n(продовження)", [3] = "Саме з цими словами я відмовляю Келю в його проханні щодо Натаноса Марріса. Він виявиться неоціненним союзником. Запам'ятайте мої слова.\n\nПідпис,\n\nСильвана Вітрогін.\nГенерал слідопитів Срібномісяця" },
    [15998] = { [1] = "Озріку,\n\nНижче наведено список броні, яка нам потрібна:\n\n10 кольчужних сорочок\n20 шоломів\n30 латок для броні\n15 пар кольчужних чоботів\n\nМи, як завжди, в боргу перед тобою. І якщо Західний край колись звільниться від злодіїв, які не дають йому спокою, відчуття провини в моєму серці зменшиться, якщо я зможу запросити тебе до мого родинного дому на смачний обід, приготований з дарів нашої родючої землі.\n\n-Льюїс\nКвартирмейстер, Сторожовий пагорб" },
    [16189] = { [1] = "Ґріш —\n\nТвоє прохання про відпустку прийнято. Я відправляю воїна з запасу, щоб він зайняв твій пост, поки ти відпочиватимеш зі своєю сім'єю. За тиждень чекаю доповідь про повернення!\n\n— Маґґран Землев'яз" },
    [16209] = { [1] = "За наказом верховного карателя Гадрека, нижче перераховані предмети, необхідні для підтримки запасів Крипти:\n\n12 довгих мечів\n9 кинджалів\n8 круглих щитів\n15 сокир\n1000 стріл\n\nПостачання запасів з цього списку слід вважати особистим розпорядженням Темної Леді, і відповідальні за це перебуватимуть під Її наглядом, так само як і всі, хто чинитиме опір або іншим чином перешкоджатиме Її бажанням." },
    [16263] = { [1] = "Нессо,\n\nРадий був отримати від тебе листа.\n\nКолекція кісток і луски, яку ти мені надіслала, була неймовірною. Я ніколи не бачив риби такого розміру за межами материка. Рибалки Рут'терана, мабуть, виловлюють тонни риби щодня!\n\nЯ заздрю їхнім уловам, але й сам трохи стурбований. Чи може наше нове Світове Дерево змусити рибу вирости до таких розмірів? Якщо так, то які ще ефекти воно може мати?\n\nЦе варто обміркувати,\n— Лейрд" },
    [16307] = { [1] = "Дорогий Зарґ,\n\nСтейки, які ти надіслав, чудові. Добре мармуровані, товсто нарізані й залиті кнурячим жиром. Вони саме такі як я люблю. Пізніше, коли я їстиму їх, буду згадувати тебе, догризаючи останні шматочки кісток і хрящів. Я заплющу очі й уявлятиму, як ти рубаєш і ріжеш це м'ясо своїми сильними, вкритими шрамами руками...\n\nХах! Це нагадало мені про той нещасний випадок, коли ти втратив палець... О, Зарґ! Згадуючи той день, я регочу, як маленька дівчинка.\n\nТи такий милий, коли стікаєш кров'ю!\n\n-Гришка" },
    [16310] = { [1] = "Нижче наведено список учнів, які отримали Платинову зірку в школі Гірництва та Геодезії Брока, що дає їм право на відзнаку — почесну кирку шахтаря:\n\nМелія Каменетрус\nБардін Залізоплет\nУмі Вольтон\nРумі Вольтон\nВорел Сталешпиль" },
    [1637] = { [1] = "Літери в цьому листі ніби мерехтять і танцюють по його поверхні. Неможливо зрозуміти суть, яку вони несуть..." },
    [1656] = { [1] = "Вітаю вас, Елло Чорнобрив, мер Темноділа. Боюся, у мене є новини для вашого міста. Серйозні новини.\n\nБачите, я творець. Я обдурив пред'явника цієї записки, щоб {стать:він допоміг:вона допомогла} мені у моєму останньому, найжахливішому творінні — монстра з плоті, кісток і покрученого металу! Поки ви читаєте ці рядки, він перебуває поруч з моїм скромним житлом, скрегоче зубами та чекає мого слова, щоб піти вбивати й трощити все на своєму шляху.\n\nІ незабаром ви відчуєте це на собі.\n\n-Бальзамувальник" },
    [16785] = { [1] = "Всі три сторінки цього документа порожні." },
    [17355] = { [1] = "Лайо:\n\nМи отримали щедру допомогу від {стать:цього доброго мандрівника:цієї доброї мандрівниці}. Я відправив {стать:його:її} до вас у Силітус. Будь ласка, подбайте про те, щоб такий цінний ресурс не пропав даремно у ваших зусиллях розкрити наявні там таємниці. Коло з нетерпінням чекає новин про ваші успіхи.\n\nНехай Кенарій наглядає за вами...\nРабін" },
    [17735] = { [1] = "Свято Зимової Покрови\n\nЗакінчення року серед багатьох народів Азерота вважається часом змін. Дворфи та таурени особливо люблять святкувати настання Зимової Покрови — вкривання землі снігом, що провіщає час оновлення. І хоча легенди, складені різними расами Азерота, не надто відрізняються, способи, якими вони вшановують ці легенди, настільки ж різноманітні, як і самі раси.", [2] = "Легенда про Дідуся Зиму\n\nКажуть, що назва \"Зимова Покрова\" походить від надприродної істоти, яку в багатьох культурах називають Дідусем Зимою. Вважається, що коли під кінець року він ходить по землі, сама зима є його плащем. За ним йде сніг, і тому кажуть, що Дідусь Зима вкриває землю своїм зимовим покривалом. І час, коли земля вкрита снігом, дає їй час для відродження та оновлення.", [3] = "Дворфи\n\nНевпинно досліджуючи своє власне походження, дворфи воліють святкувати сезон, вихваляючи самого Дідуся Зиму. Вони вважають його уособленням одних з найдавніших мешканців Азероту — титанів. Вони стверджують, що тією чи іншою мірою пов'язані з цією містичною істотою, і вважають свій засніжений дім Дун-Морог головним доказом прихильності Дідуся Зими.", [4] = "Таурени\n\nТаурени зі своїм шаманським розумінням зими та інтересом до справ друїдів, добре вписуються в легенду про Зимовий Покров. Проте, вони майже повністю зосереджуються на легенді про відновлення, залишаючи поклоніння легенді тим народам, що, на їх думку, не так глибоко пізнали природу речей. Багато тауренів вважають, що саме під час цього свята їм належить дякувати за благословення їхньої нової домівки, Мулґора.", [5] = "Святкування\n\nЗвичай влаштовувати в цю пору року бенкети сягає своїм корінням у глиб самої легенди. Коли Дідусь Зима йшов Азеротом, вкриваючи його снігами, тих, хто вітав його появу, він обсипав дарами. Таким чином, традиція бенкетувати під час Зимового Покрову об'єднувала громади, оскільки вони ділилися всім, що мали. Зазвичай оновлення та переродження землі вітали веселощами та святкуванням протягом цілого дня.", [6] = "Сучасний погляд на свято\n\nІнші культури згодом теж почали визнавати свято Зимової Покрови як час великого святкування, хоча й не в тих традиціях, в основі яких лежать легенди. Сьогодні цьому святу в різних куточках світу відповідає безліч звичаїв, які часто ставлять собі за мету лише власне святкування та обмін подарунками. Іноді навіть використовується образ Дідуся Мороза, але більше як покровитель комерційних звершень, а не могутній титан." },
    [17781] = { [1] = "Далеко в долині Списів розташований священний храм Мародон. Скоро ти зрозумієш, чому я попросив не кентавра допомогти мені в моїй скруті.\n\nТам, одразу за дверима, куди можуть заходити лише духи та наші найсвященніші жерці та жриці, є кентавр, на ім'я Безіменний Пророк. Він вищий за всіх у духовних справах і старший за багатьох старійшин.", [2] = "Пророк дуже могутній і спілкується з духами наших предків. Але він дурень! Він навіть не здогадується про справжню силу, якою володіє. Він носить амулет Духів, у якому й міститься більша частина його сили.\n\nЯ дізнався, що амулет могутній, але він неповний.", [3] = "В амулеті не вистачає п'яти самоцвітів. І якщо їх знайти та вставити на місце, його сила набагато перевищить силу його нинішньої форми. Я дізнався, де знаходяться ці п'ять самоцвітів, але мені потрібні твої уміння, щоб допомогти зібрати їх. Вбити Безіменного Пророка — це, звісно, найтяжчий гріх, як і крадіжка з його тіла, але про те, що я попрошу далі, всякому кентавру заборонено навіть думати.", [4] = "У печерах Мародону блукають духи наших перших ханів. Перші діти наших Матері та Батька і наші найбільші лідери — це Ґелк, Колк, Маґра, Мародос і Венґ. Кожен з цих духів зберігає один зі зниклих самоцвітів.", [5] = "Використовуй силу амулета Духів, щоб змусити їх проявитися і забери у них самоцвіти! Після цього встав самоцвіти в амулет Духів і поверни його мені. Коли я отримаю амулет Єднання, я буду достатньо сильним, щоб змінити життя племен, і ми нарешті зможемо стати такими, якими хотіли нас бачити наші предки!" },
    [18229] = { [1] = "... і саме там ви знайдете легендарний меч верховного повелителя Багряного Походу, Спопелитель.\n\nВражає, що можна знайти на звичайній риболовлі, чи не так?" },
    [18332] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий", [2] = "<Ваше тіло пронизує пекучий біль, коли ви дивитесь на ці сторінки.>" },
    [18333] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий", [2] = "<Ви не можете зрозуміти нічого з того, що написано на цих сторінках.>" },
    [18334] = { [1] = "<Сторінки вкриті стародавніми ельфійськими рунами.>\n\nНа сторінках цієї книги зібрані спогади про події, які відбувалися під час збору та приготування реагентів, необхідних для створення магічного каменю.\n\nНехай наші вороги ніколи не отримають доступу до цих манускриптів.\n\nНехай я доживу до того часу, коли бліде світло місяця знову осяє Квел'Талас.\n\nНехай я помру на милість Кель'таса.\n\nНехай я вбиватиму на славу Іллідана.\n\n— Майстер Тельмій Снохочий", [2] = "<Чорнила крутяться і переміщаються по сторінці. Вам здається, ніби книга знущається з вас.>" },
    [18646] = { [1] = "Коли ви вдивляєтеся в Око, перед вами постає картина великої битви.\n\nЗдається, цей жахливий конфлікт відбувається десь у Лордероні.\n\nВи ледве можете розгледіти самотню жіночу постать, що стоїть серед тисячі трупів, відбиваючись від полчищ Скари. І полчища ці незліченні.\n\nЗ її рук вириваються промені світла, що сотнями розсікають невмерлих.", [2] = "Схоже, що все було марно. За мить жрицю поглинув натовп мертвих селян... Загиблі повстали." },
    [18664] = { [1] = "ТРАКТАТ ПРО ВІЙСЬКОВІ ЗВАННЯ\n\n\n\nНижче наведено\nвійськові звання\nАльянсу,\nвключно з\nінформацію, яка\nстосується рас\nОрди. Всі\nзвання представлені у двох\nрозділах: офіцери та рядовий склад, при чому\nзвання кожного з них перераховані в порядку спадання від вищого до нижчого.\nНехай живе Альянс!", [2] = "ОФІЦЕРСЬКІ ЗВАННЯ АЛЬЯНСУ\n\nЧастина 1\n\nГоловнокомандувач\n\n\n\nФельдмаршал\n\n\n\nМаршал\n\n\n\nКомандир\n\n\n\nЛейтенант-командир", [3] = "ОФІЦЕРСЬКІ ЗВАННЯ АЛЬЯНСУ\n\nЧастина 2\n\nЛицар-чемпіон\n\n\n\nЛицар-капітан\n\n\n\nЛицар-лейтенант\n\n\n\nЛицар", [4] = "РЯДОВІ ЗВАННЯ АЛЬЯНСУ\n\n\nСержант-майор\n\n\n\nМайстер-сержант\n\n\n\nСержант\n\n\n\nКапрал\n\n\n\nРядовий", [5] = "ОФІЦЕРСЬКІ ЗВАННЯ ОРДИ\n\nЧастина 1\n\nВерховний воєвода\n\n\n\nВоєвода\n\n\n\nГенерал\n\n\n\nГенерал-лейтенант\n\n\n\nЧемпіон", [6] = "ОФІЦЕРСЬКІ ЗВАННЯ ОРДИ\n\nЧастина 2\n\nЦентуріон\n\n\n\nЛегіонер\n\n\n\nКривавий вартовий\n\n\n\nКам'яний вартовий", [7] = "РЯДОВІ ЗВАННЯ ОРДИ\n\n\nГоловний сержант\n\n\n\nСтарший сержант\n\n\n\nСержант\n\n\n\nБугай\n\n\n\nРозвідник" },
    [18675] = { [1] = "ВІЙСЬКОВІ ЗВАННЯ ОРДИ І АЛЬЯНСУ\n\n\n\nТром'ка! У цій\nкнизі ти знайдеш\nдетальний перелік\nвійськових звань\nОрди та\nжалюгідного Альянсу.\nСпочатку в переліку йде\nОрда, потім Альянс,\nі для обох перелічені офіцерські та рядові звання. Як і\nгодиться, найсильніші перераховані вгорі, а слабші —\nпід ними.", [2] = "ОФІЦЕРСЬКІ ЗВАННЯ ОРДИ\n\nЧастина 1\n\nВерховний воєвода\n\n\n\nВоєвода\n\n\n\nГенерал\n\n\n\nГенерал-лейтенант\n\n\n\nЧемпіон", [3] = "ОФІЦЕРСЬКІ ЗВАННЯ ОРДИ\n\nЧастина 2\n\nЦентуріон\n\n\n\nЛегіонер\n\n\n\nКривавий вартовий\n\n\n\nКам'яний вартовий", [4] = "РЯДОВІ ЗВАННЯ ОРДИ\n\n\nГоловний сержант\n\n\n\nСтарший сержант\n\n\n\nСержант\n\n\n\nБугай\n\n\n\nРозвідник", [5] = "ОФІЦЕРСЬКІ ЗВАННЯ АЛЬЯНСУ\n\nЧастина 1\n\nГоловнокомандувач\n\n\n\nФельдмаршал\n\n\n\nМаршал\n\n\n\nКомандир\n\n\n\nЛейтенант-командир", [6] = "ОФІЦЕРСЬКІ ЗВАННЯ АЛЬЯНСУ\n\nЧастина 2\n\nЛицар-чемпіон\n\n\n\nЛицар-капітан\n\n\n\nЛицар-лейтенант\n\n\n\nЛицар", [7] = "РЯДОВІ ЗВАННЯ АЛЬЯНСУ\n\n\nСержант-майор\n\n\n\nМайстер-сержант\n\n\n\nСержант\n\n\n\nКапрал\n\n\n\nРядовий" },
    [18708] = { [1] = "Симона Спокусниця:\n\nТи застанеш Симону за оскверненням кратера Ун'Ґоро. Не дай себе обдурити її маскуванням. Наближайся до неї з обережністю і виклич її на бій.", [2] = "Клінфран Схиблений:\n\nКлінфран блукає Палаючим степом. Наближайся до нього з обережністю і змусь його показати своє справжнє обличчя.", [3] = "Соленор Душогуб:\n\nУ посушливих землях Силітусу нишпорить лиходій, Соленор Душогуб. Він диявольськи хитрий і дуже небезпечний. Підберися до нього і змусь його перетворитися.", [4] = "Арторій Губитель:\n\nАрторій псує та нищить все, до чого торкається у Зимоключі. Знайди його і вбий.", [5] = "Зауваж, {клас:к}, з цими демонами треба битись на їхніх умовах. Якщо вони відчують, що не можуть тебе здолати — вони втечуть.\n\nБИЙСЯ З НИМИ НАОДИНЦІ." },
    [18818] = { [1] = "Щоб прив'язати дух жахожеребця, потрібно зробити три речі:\n\nСтворити коло великого виклику.\n\nВсередині кола відкрити портал в Зорот і витягнути через нього жахожеребця.\n\nЗдолати жахожеребця та підкорити його дух.\n\nНа наступних сторінках буде детально описано, як виконати кожен з цих кроків. Це буде нелегко, але ти {стать:довів:довела}, що маєш здібності. Якщо ти зосередишся і вправно виконуватимеш вказівки, я впевнений, жахожеребець буде твоїм.\n\nЧитай далі,\n— Мор'зул Кровопивця", [2] = "Знаряддя для ритуалу\n\nПерш ніж почати виконувати завдання, в тебе мають бути наступні магічні предмети:\n\nБанка з Дж'іві\nЧорний магнетит\nЗоротські письмена\n\nМій прислужник Ґорзікі добуде їх для тебе за певну плату. Не розпочинай ритуал поки не матимеш усіх цих предметів. Кожен з них дуже важливий.\n\nНа наступних сторінках я опишу, як використовувати кожен предмет.", [3] = "Коло великого виклику\n\nКоло великого виклику має бути створене в місці сильної магії. Таке місце є глибоко в руїнах Ельдре'Таласа, також відомого як Грізний Молот. В Ельдре'Таласі ув'язнена істота великої сили, Безсмер'тер, і саме на підніжжі його в'язниці ти маєш виконати ритуал створення кола.\n\nПроберись до в'язниці й випусти Дж'іві з банки.", [4] = "Дзвін, колесо і свічка\n\nКоли ти випустиш Дж'іві, він розмістить дзвін, колесо і свічку, після чого з'явиться коло. Так почнеться ритуал. Тобі потрібно бути {стать:пильним:пильною}, ці предмети тримають в собі величезну енергію і можуть вийти з ладу в будь-яку секунду. Якщо це станеться, тобі потрібно перезапустити їх за допомогою чорного магнетиту, перш ніж весь ваш ритуал зійде нанівець.\n\nЯкщо всі три предмети вийшли з ладу і ти не {стать:встиг:встигла} їх перезавантажити, то ритуал закінчиться і тобі потрібно почати його спочатку.", [5] = "Крім великої енергії в собі, дзвін, колесо і свічка мають власні унікальні властивості.\n\nКоли дзвенить дзвін Детмури, він наділяє чорнокнижників, що знаходяться у колі, силою та енергією.\n\nКоли обертається колесо Чорного Походу, воно захищає тих, хто знаходиться в колі, від шкоди.\n\nКоли горить свічка Судного дня, вона вражає ворогів, які входять у коло, магічною енергією.\n\nЧерез всі ці властивості дуже важливо, щоб всі предмети працювали під час ритуалу.", [6] = "Слід зазначити, що якщо вони вийдуть з ладу дзвін, колесо або свічка, чорний магнетит вимагає уламки душ для перезапуску предметів. Кожного разу, коли ти перезавантажуєш ритуальний предмет за допомогою каменю, один з твоїх уламків душі буде втрачатися, тому перед початком ритуалу переконайся, що маєш запас.", [7] = "Завершення ритуалу\n\nТи можеш відстежувати прогрес виконання ритуалу за магічними рунами на колі. Коли з'явиться дев'ять рун, ритуал буде завершено і ти побачиш, як заряджене коло втрачає енергію.\n\nПісля цього ти можеш використати зоротські письмена, щоб відкрити портал в Зорот і вивести через нього жахожеребця.\n\nВбий жахожеребця і визволи його дух. Здолай дух і тоді його буде поневолено, а ти дізнаєшся таємницю його виклику." },
    [19483] = { [1] = "Очищення цибулини\nДетальний посібник з битви з Бурешпилем\n-Автор: Дрек'Тар\n\nНа цих сторінках ти знайдеш знання про тактику і політику бою. Навчений солдат — це солдат, який спирається на накопичений досвід. Нехай ця книга послужить тобі довідником у битві за Альтерацьку долину.", [2] = "Розділ 1 - Лінія фронту\n\nАтакувати армію Бурешпиля — все одно що чистити цибулю. Щоб дістатися до серцевини, потрібно почати з видалення зовнішніх шарів.\n\nПередова лінія, що складається здебільшого з горян Бурешпиля та стражниць Альянсу, пов'язана з бункером капітана. Саме капітан Балінда Кам'яне Вогнище підсилює ці підрозділи та забезпечує підкріплення, коли лінії перебувають в облозі. Вбий капітана — і передові загони посиплються.", [3] = "Розділ 2 - Вежі-близнюки\n\nНе припустись помилки: Ванндар Бурешпиль — хитрий ворог і, звичайно, не дурень. Після прориву лінії фронту необхідно знищити об'єкти другої лінії оборони. Саме вежі-близнюки, Кригокрила та Кам'яного Вогнища, керують гвардійцями Бурешпиля за межами Дун-Балдара і патрулями Бурешпиля.", [4] = "Стережись, солдате, обидві ці вежі добре укріплені й перебувають під контролем одного з елітних командирів Ванндара. Якщо твої війська прорвуть укріплення, переконайся, що командир який був всередині... усунутий. Це теж важливий крок до перемоги над Бурешпилем.", [5] = "Розділ 3 - Чотири командири\n\nТретій шар цибулі Бурешпиля складається з чотирьох командирів. У цьому відношенні Ванндар перейняв нашу тактику оборони Морозних Вовків. Він, звісно, вважає інакше... Але я відійшов від суті.\n\nЧотири командири керують гвардійцями Бурешпиля, які запекло охороняють Дун-Балдар. Усунь їх всіх, і гвардійці Бурешпиля відступлять.\n\nТоді залишиться лише один шар.", [6] = "Розділ 4 - Бункери Дун-Балдара\n\nЯк ти, безсумнівно, можеш помітити, захисні шари Бурешпиля, вишикувані так, щоб не дати масованому удару знести одразу всю армію. Відразу відповім на твої запитання. Так, саме так організована і наша оборона, і ні, міняти її розташування я не стану. Вони перейняли все в нас, з чого нам щось змінювати?", [7] = "На чому я зупинився? Так от, бункери Дун-Балдара (які знаходяться в Дун-Балдарі) контролюють захисники Бурешпиля — найбільш довірені та елітні охоронні підрозділи Ванндара. Зруйнуй ці дві вежі, і підкріплення, відправлене на допомогу Ванндару, припинить своє існування.", [8] = "Епілог\n\nПісля того, як ти зробиш все це, залишиться середина цибулини: солодка серцевина. Ванндар Бурешпиль залишиться беззахисним і самотнім. Закони та звичаї війни вимагають, щоб ми попросили його здатися, перш ніж виконувати будь-які страти. Обов'язково нагадай йому, що він може здатись... а потім вбий його." },
    [19484] = { [1] = "Артишок Морозного Вовка: Оповіді про славу Бурешпиля\n-Автор: Ванндар Бурешпиль\n\nЩо таке Морозні Вовки? Відповідь проста: Морозні Вовки — це дикуни, які намагаються зупинити наш суверенний імперіалістичний імператив.\n\nПодібно до артишоку, Морозні Вовки колючі, мають шари захисту, і подібно до артишоку, щойно зовнішній шар зчищається, відкривається серцевина, готова до вживання з часниковою підливою.\n\nДуже смачна штука!", [2] = "Розділ 1 - Лінія фронту\n\nПередова лінія оборони Морозних Вовків складається з воїнів Морозних Вовків. Воїни відправляються на передову з фортеці капітана Ґальванґар: гарнізону Крижаної Крові. Найефективніший спосіб зняти цей рівень оборони — знищити гарнізон Крижаної Крові.\n\nВізьміть в облогу фортецю та знищте капітана Ґальванґара. Як тільки це буде зроблено, лінія фронту посиплеться.", [3] = "Розділ 2 - Крижана Кров і Оглядова вежа\n\nЯк тільки перший шар буде знищено, відкриється другий шар \"артишоку\". Знищення веж Морозних Вовків, що стоять біля лінії фронту, залишить їх без легіонерів і патрулів, які роєм кишать на задньому фланзі.\n\nВежі добре укріплені, в кожній з них знаходиться один з елітних командирів Дрек'Тара. Їх треба вбити. Це прискорить крах оборони Морозних Вовків.", [4] = "Розділ 3 - Чотири командири\n\nЯкщо ви слідували мудрості цього посібника, то на цей час двоє з командирів Дрек'Тара мертві. Молодець, солдате! Їх рішучість вже слабшає. Тепер ви повинні розбити останні ланки командування, вбивши двох командирів, що залишилися.\n\nКоли всі четверо командирів будуть вбиті, легіонери Морозних Вовків, що охороняють форт Морозних Вовків, залишаться без командування і розбіжаться. Можна брати голими руками!", [5] = "Розділ 4 - Східна та західна вежі Морозних Вовків\n\nТепер між вами та перемогою стоїть лише одна перепона, найнадійніші та наймогутніші вартові Дрек'Тара: вартові Морозних Вовків.\n\nВартові Морозних Вовків висилаються із взводів, що перебувають у резерві біля східної та західної веж Морозних Вовків. Зруйнуйте ці вежі та подивіться, як решта вартових з ганьбою втече.", [6] = "Епілог\n\n\"Тушкуйте серцевину артишоку з часниковим маслом і майонезом. Доповніть страву витриманим, хмільним елем\".\n\nТепер Дрек'Тар стоїть сам, з двома шавками по боках. Захопіть притулок Морозних Вовків, щоб отримати перевагу в битві та знищте Дрек'Тара. Коли генерал впаде, ця земля нарешті повернеться до свого законного власника: Бурешпиля." },
    [1971] = { [1] = "Це документ на земельну ділянку в Західному краю. Він надає права власності на визначену територію, а також на всі вироблені предмети та будь-які споруди, побудовані в її межах, зазначеним нижче особам.\n\nДокумент підписаний:\n\nТеодор Хмуробров\nВерна Хмуробров", [2] = "[Слова нижче були швидко нашкрябані на звороті документа]\n\nМи притисли Хмуроброва й тепер маємо його акт на землю. Подумав, що це може стати в пригоді, якщо потрібна буде власна ділянка. Хмуроброви не створять нам проблем. Востаннє я їх бачив на шляху з Західного краю, де вони застрягли зі зламаним возом." },
    [19978] = { [1] = "Риболовний турнір в Тернистій долині! Захід проходитиме в неділю — з 14:00 до 16:00.\n\nЛовіть рибу в будь-якій точці на узбережжі Тернистої долини (окрім Грабіжної Бухти) і шукайте косяки смачнориби, які з'являтимуться вздовж узбережжя! Якщо ваш поплавок попаде в косяк, ви ловитимете особливу рибу замість звичайних різновидів, яких повно в Тернистій долині. Той, хто першим зловить сорок смачнориб, зможе віддати їх майстру риболовлі Жерлиці в Грабіжній Бухті та отримати приз!\n\nНавіть якщо ви не будете першим, хто зловить сорок смачнориб, ви все одно зможете обміняти їх на гроші, а за деяких особливих риб, ви отримаєте спеціальні призи!" },
    [20009] = { [1] = "Його ім'я принесло Світло в темряву Азероту.\n\nЙого доблесть зруйнувала стіни відчаю.\n\nСрібляста Десниця не могла зробити нічого кращого,\n\nніж подарувати світу лицаря, який віддав би своє життя.", [2] = "Він не прагнув слави,\n\nі не хотів він панувати над власним народом.\n\nНатомість він вирішив битися за Лордерон,\n\nщоб його народу більше не довелося воювати.", [3] = "Трагічна історія цього святого лицаря\n\nніколи не закінчиться його нечестивою смертю.\n\nМи шануємо його і дякуємо йому!\n\nНехай Утер спочиває зі славою та світлом!" },
    [20010] = { [1] = "Ім'я його не помре.\nЖертва його завжди\nвказуватиме нам шлях.\n\nЛанцюги, що колись душили\nперешкоджаючи подиху честі,\nбільше не зв'язують нас.", [2] = "Чи чуєш його крик?\nКлич бойовий за Орду:\nПеремога або смерть!\n\nМи повинні пам'ятати\nйого силу перед лицем смерті.\nМрію його, що стала реальністю.", [3] = "Небезпека скрізь!\nВороги прагнуть нас знову\nзакувати в ланцюги.\n\nКоли ми боремось, думаймо про того,\nхто зробив те, що повинен був зробити.\nПеклокрик, назавжди!" },
    [2004] = { [1] = "ДЕНЬ ПЕРШИЙ\n\nСьогодні ми з учнем прибули до Морозної долини. Подорож печерою пройшла здебільшого без пригод. Ми стали табором на достатній відстані від печери, де, як нам сказали, мешкають тролі.\n\nДЕНЬ ДРУГИЙ\n\nКляте вовче виття не давало мені спати всю ніч.\n\nЗа кілька днів у мене буде новий одяг із вовчої шкури.\n\nХлопець сьогодні зв'язався з трогом, влаштував бійку та", [2] = "зумів узяти гору над потворним звіром, але тепер він лікує неприємний поріз на руці. Схоже, тепер мені доведеться займатися побутовими справами деякий час.\n\nДЕНЬ ТРЕТІЙ\n\nХолодно. Близько полудня випав невеликий сніг.\n\nДЕНЬ ЧЕТВЕРТИЙ\n\nХлопець сьогодні повністю одужав та був у гарному настрої, тож ми вперше вирішили глянути на тих тролів. Я б сказав, що це Морозогриві, судячи з відмітин на їхній шкірі та різноманітних дрібничок, які вони носять на своєму тілі.", [3] = "ДЕНЬ П'ЯТИЙ\n\nДоручив хлопцеві наглядати за табором, а сам підкрався до печери й оглянув її. Кількість тролів непокоїть. Можливо, доведеться викликати горян, щоб очистити печеру від цього нашестя тролів.\n\nЯ розумію, що останнім часом не згадував про трогів. Вони з'являються на території в більшій кількості, але вони настільки примітивні, що особливої загрози не становлять. Правда це чи ні — час покаже.", [4] = "І вже майже тиждень жодної краплі елю.\n\nДЕНЬ ШОСТИЙ\n\nЗнову холодно. Падає сніг. Тролі. Без елю.\n\nДЕНЬ СЬОМИЙ\n\nСніг унизу такий білий,\nНебо вгорі таке синє,\nВить будуть вовки вночі,\nНі сну, ні бражки мені.\n\nДЕНЬ ВОСЬМИЙ\n\nТролі, можливо, не така велика проблема, як ми спочатку думали. Їх є певна", [5] = "кількість, але вони погано озброєні чи організовані. Варто показати їм силу і цього має бути більш ніж достатньо для протидії загрозі, яку вони становлять." },
    [2005] = { [1] = "Місяць над долиною сяє,\nНа джунглі відбивається блиск.\nТут горді воїни зійшлися на поклик,\nЗахищати свою Націю і святі землі.\n\nМісяць над долиною сяє,\nВисоко над криками битви.\nДе проливається кров,\nВорогів і побратимів.", [2] = "І коли наші брати йдуть\nУ світи потойбічний,\nДуша-дух твердіє,\nУ глибинах долини.\n\nІ коли наші брати йдуть\nДо Храму Гірського,\nМи захистимо їх вічний дух,\nУ святому кристалі синьому.\n\nІ коли наші брати йдуть\nМісяць над долиною сяє." },
    [2006] = { [1] = "Казка про Ґрі'лека Мандрівника\n\n[...Початок запису на скрижалі затертий і подряпаний. Але закінчення все ще можна прочитати...]\n\nҐрі'лек продирався крізь джунглі. Очі його палали, а в грудях гуркотіло, бо великий гнів був у ньому.\n\nУ люті він заревів до неба і підняв руку. Він підняв свою ліву руку, що стала сильною і міцною від полювання без свого близнюка.\n\nБо права рука Ґрі'лека була безповоротно втрачена.", [2] = "І він блукав, і він шукав. А рука його так і лишилася втраченою для нього. І він проклинав і ревів, ідучи.\n\nАле Ґрі'лек давно вже перестав слухати духів, і вони розгнівалися і не хотіли слухати його прокльони.\n\nПриречений був Ґрі'лек. Приречений блукати без руки." },
    [2007] = { [1] = "Нептулон повстав з океану величезною водяною вежею і наслав на приречений І'лалай величезних кракенів. Настільки величезні були вони, що з їх мацаків звисав ліс водоростей, і левіафани пропливали крізь них.\n\nНайвеличезніший з краккенів підняв кінцівки та вдарив ними по морю, здійнявши хвилі. І хвилі ці шалено понеслися до І'лалая.", [2] = "Краккени заревли, і їхні голоси прогриміли, як океанський шторм:\n\n\"Ми йдемо.\"\n\nМін'лот, стоячи непохитно, закликав свою магію. Хвилі, послані на І'лалай, розійшлися в боки, оминули місто і затопили джунглі за ним. Тоді Мін'лот наказав своїм помічникам вимовити заклинання, що сковували, і десятки голосів злилися в пісню.\n\nАле один голос лунав голосніше за інші.", [3] = "Мін'лот заревів, його магія увібрала силу заклять його помічників, і він спрямував її на краккенів, що наближалися.\n\nМоря розступилися, і закляття Мін'лота помчало до слуг Нептулона. Блискавка розірвала небо, і закляття вдарило в них, і впала тисяча блискавок, закипіла вода і дно вкрилось кратерами.\n\nМін'лот тріумфально вигукнув, знаючи, що його закляття вб'є великих звірів.", [4] = "Але краккени старі, дуже старі. Вони пам'ятають, як земля вперше народилася з моря.\n\nВони пам'ятають, коли правили старі, а потім прийшли титани та скинули їх. Вони пам'ятають, коли магія була новою.\n\nВони старі та зберігають багато таємниць. І хоча закляття Мін'лота було сильним, воно, як і троль, було смертним.\n\nІ тому воно зазнало невдачі.", [5] = "Воно не скувало краккенів, але розлютило їх. Ніколи ще смертний не завдавав їм болю, а закляття троля було болючим.\n\nІ ось вони скинули з себе пута Мін'лота і заревли від люті.\n\nПочувся гуркіт, коли з глибин здійнялися великі хвилі й помчали до берега. Коли вони досягли І'лалая, то накрили місто тінню.\n\nАле перед тим, як зруйнувати його, краккени на мить завмерли.", [6] = "Тролі-знахарі затремтіли та закричали до свого володаря. Мін'лот дивився на гори, що піднялися з моря, приречений і зухвалий. Він повернувся до своїх адептів і прошепотів свої останні слова, які тролі закарбували в камені. Тоді Мін'лот зіткнувся з краккенами, що насувалися на нього.\n\nВін насупився і кинув у них свій посох. Це було його останнє діяння.\n\nТоді краккени спрямували свою лють на Мін'лота, і океан впав на І'лалай.\n\nІ його не стало.", [7] = "І тоді води впали на джунглі, змиваючи все, що зустрічалося на їхньому шляху. Тролі та звірі кричали, коли вода розбивала і топила їх.\n\nБагато Ґурубаші гадали, за що океан впав на них, але вони померли, так нічого й не дізналися.\n\nІ нарешті, коли води досягли гір, вони зупинилися. Заспокоєні, вони відступили за береги та залишили по собі слід смерті.\n\nВоди відступили, але І'лалай вони затопили назавжди.", [8] = "А вождь Вар'ґазул, що перебував у безпеці за горами в Зул'Ґурубі, спустився в джунглі й побачив, що вони очистилися від його народу.\n\nІ він впав у відчай, бо його мрії про завоювання були зруйновані.\n\nА Мін'лота-Змія так і не знайшли." },
    [2008] = { [1] = "Місяцем і вогнем,\nКістками й плоттю,\nВирізьблене кров'ю,\nНа камені слово.\n\nПокиньте це місце,\nЧи прийміть загибель,\nСмерть невпинно сторожить\nІмператора обитель." },
    [20405] = { [1] = "День 1\nНаше паломництво закінчилося. Ми нарешті прибули до Силітуса, де маємо встановити зв'язок. Ми приїхали сюди з багатьох місць, щоб спільно здійснити велику справу.\n\nУ повітрі відчувається величезне хвилювання. Завтра ми повністю присвятимо себе будівництву того, що дозволить встановити зв'язок з НИМИ.\n\nЗавтра ми збудуємо вітровий камінь!", [2] = "День 2\nМи довго сперечалися про те, де потрібно будувати вітровий камінь. Навіть наймудріші з нас не можуть з упевненістю визначити, де саме знаходиться місце, згадане в старому пророцтві.\n\nЯ на стороні північної групи й час, безсумнівно, доведе нашу правоту. Аргумент про те, що ніби-то енергетичні лінії в цьому місці перетинаються під поганим кутом, є нерозумним і наївним.\n\nВже зараз ми з поспіхом збираємо необхідні будівельні матеріали.", [3] = "День 15\nНаша самовідданість принесла свої плоди. Ми — перший табір, який закінчив будівництво вітрового каменя. Якби інші дурні залишилися з нами, ми б виконали завдання менш ніж за тиждень!\n\nЗавтра ми почнемо ритуали, пов'язані з викликом самого барона Казума. Він прагне першим випробувати систему, а ми не змогли йому заперечувати, бо він дуже розлютиться.\n\nГадаю, він буде дуже задоволений нами." },
    [20415] = { [1] = "Майже тисяча років минула після Війни Мінливих Пісків. Саме під час цієї війни, в самому серці пустелі Силітус, велика трагедія і ще більший тягар звалився на Фендрала Оленерога. Вважається, що саме події, описані в цій книзі, зрештою відвернули верховного друїда від добра.", [10] = "Дракони зустрілись в небі високо над Силітусом: у тисячах метрів над фортецею Ан'Кіраж.\n\nТам був Анахронос, дитя Ноздорму, Аспекту Часу.\n\nЗі Смарагдового Сну прийшла Мерітра, дитя Ізери, Аспекту Природи.\n\nКелестраз, дитя Алекстрази, Аспекту Життя, представляв Крило червоних драконів.\n\nАриґос, дитя Маліґоса, Аспекту Магії, представляв Крило синіх драконів.", [11] = "Дракони дивилися, як нескінченний потік силітидів та кіражів вивергався з Ан'Кіражу. Їм стало зрозуміло, що ніяка сила не зможе покласти край цій війні. Зсередини головного храму на них чекали десятки тисяч воїнів кіражів. З кожною секундою вилуплювалося все бійців, готових до виходу у світ.", [12] = "Ариґос першим помітив дивні випромінювання. Монолітний храм у південній частині Ан'Кіража випромінював ледь помітну магію, не схожу ні на що, що вони відчували з боку кіражів. Як союзники не намагалися, нікому не вдалося проникнути до храму та знайти джерело цієї енергії. Оточити себе таким непробивним захистом могло лише щось, що володіє величезною силою. Можливо, це було щось, що керує комахами. Щось, що управляє навіть кіражами.", [13] = "Дракони знали, що вони повинні діяти швидко, щоб світ не зазнав ще однієї жахливої катастрофи. Після ретельних роздумів було вирішено, що найкраще буде зупинити ворожі армії на цьому джерелі енергії або поблизу нього.", [14] = "Було створено великий бар'єр, що спирається на сутність нічних ельфів і крил драконів. Магічний бар'єр, який міг би утримати силітидів та їхніх володарів у стінах Ан'Кіражу і запобігти майбутнім вторгненням. Ан'Кіраж став в'язницею для них.", [2] = "Древня розумна комахоподібна раса, відома як кіражі, колись боролася за панування над більшою частиною Калімдору. Саме пихатий, імперіалістичний Оленеріг та його армія нічних ельфів зіткнулися з кіражами в битві.", [3] = "Батько і син відчайдушно боролися, щоб стримати нестримний рій комахоподібних створінь у Силітусі. З фортеці Ан'Кіраж нескінченний потік силітидів продовжував поповнювати ряди сил кіражів. Весь Силітус був в облозі.", [4] = "Молодшому Оленерогу, Валстанну, було наказано захищати аванпост нічних ельфів у селищі Південний Вітер, про що Оленеріг згодом пошкодував. На жаль, Валстанн загинув того дня, коли селище Південний Вітер впало під натиском військ Ан'Кіража.", [5] = "З важким серцем, охоплений жагою помсти Фендрал Оленеріг посилив натиск. Поразка в Силітусі призвела б до великих втрат для нічних ельфів і, цілком можливо, для всього світу.\n\nБитва кипіла місяцями. Весь Силітус був захоплений кіражами. Оленерога і його армію відкинули до Танаріса. З розгромленою армією та незліченною кількістю невинних жертв, самовпевненість, що рухала Фендралом, була повністю знищена.", [6] = "Його гордість була повністю розчавлена. Оленеріг вдруге за своє життя відчув тремтіння внизу живота, яке міг викликати лише страх. Саме в Танарісі Оленеріг звернувся до Анахроноса, нащадка Ноздорму, і благав про допомогу Бронзового крила.", [7] = "Спочатку Анахронос відмовлявся втягувати Бронзове крило у справи нижчих рас. Лише коли кіражі зухвало напали на Печери Часу, Анахронос погодився об'єднати сили з нічними ельфами.", [8] = "Незабаром Анахронос зрозумів, що навіть могутні бронзові дракони не в змозі зупинити натиск кіражів. Місце кожних п'ятдесяти комах, знищених його диханням, займала сотня нових. Коли лави нічних ельфів похитнулися, а загроза відступу на північ, до диких земель Фераласу, насувалася все ближче, Анахронос вирішив, що діти Аспектів мають про це знати.", [9] = "Спочатку він покликав крило драконів Ізери. Мерітра зі Сну відповіла на його поклик, і звістка докотилася до драконів Алекстрази та Маліґоса." },
    [20541] = { [1] = "Для негайного розповсюдження серед усіх членів Сутінкового Молота.\n\nПошуки зрадника Ортелла просуваються достатньо швидко. Наші розвідники дізналися, що він знаходиться в печерах на заході.\n\nЗрада Ортелла не буде пробачена, а його втеча становить велику загрозу для безпеки нашої організації.\n\nБудь-хто, хто приховує інформацію про місцеперебування Ортелла, буде належним чином покараний.\n\n— Сутінковий лорд Еверун" },
    [20545] = { [1] = "Для негайного розповсюдження серед усіх членів Сутінкового Молота.\n\nВраховуючи поточний стан справ в Силітусі, будь-яке розповсюдження текстів \"Правовірного\" повинно відбуватися у супроводі не менше, ніж чотирьох озброєних членів Сутінкового Молота.\n\nБудь-які члени організації, які порушать цей наказ, будуть суворо покарані.\n\n— Сутінковий лорд Д'Сак" },
    [20552] = { [1] = "Для негайного розповсюдження серед усіх членів Сутінкового Молота.\n\nНаступна інформація описує використання вітрових каменів для спілкування з нашими майстрами з Ради Безодні.\n\nБудь-яке неналежне використання вітрових каменів буде покарано найжорстокішим чином.\n\n— Сутінковий хранитель Гавунт", [2] = "Храмовники Безодні\n\nТобі, як новачку, дозволяється встановлювати контакт з храмовниками Безодні для проведення звичайних ритуалів. Не забувай завжди одягати відповідне вбрання при використанні вітрових каменів, щоб уникнути активації наших захисних заклинань.\n\nУ разі виникнення надзвичайної ситуації за відсутності розпорядників, ти маєш право викликати храмовників Безодні.\n\nДля отримання детальної інформації про ритуали виклику прочитай минулий випуск \"Правовірного\".", [3] = "Герцоги Безодні\n\nЛише прислужники, які володіють медальйоном служіння, мають право встановлювати контакт з герцогами Безодні. Медальйонами можуть користуватися лише ті, кому вони були видані.\n\nЧлени Сутінкового Молота, які будуть підозрюватись в несанкціонованому зв'язку з герцогами Безодні або несанкціонованому використанні медальйонів, будуть покарані мною особисто.", [4] = "Вища Рада Лордів Безодні\n\nТільки сутінкові лорди мають право зв'язуватися з принцом Шпареноксом, верховним маршалом Вихраксісом, бароном Казумом або лордом Скволом.\n\nЗа жодних обставин членам Сутінкового Молота нижчого рангу не дозволяється встановлювати зв'язок з Вищою Радою. Будь-які чужинці, викриті у неналежному використанні вітрового каменя, будуть перетворені на попіл на місці." },
    [20676] = { [1] = "Справи культу, том 92\n\nЗ радістю на серці вітаю вас, мої брати та сестри, бо справи нашого культу не можуть просуватися краще. Ми — легіон, і наші цілі стають все ближчими до втілення.\n\nНовачків в наших рядах стає все більше. Вони прославляють наших лордів на Темнобережжі, вони з радістю схиляють голови у Випаленій ущелині, вони обіймають слугу наших господарів, Аку'май, в Чорноводних глибинах. Воістину, мої брати та сестри, скоро наша віра рознесеться по всьому Азероту!" },
    [20677] = { [1] = "Справи культу, том 127\n\nЦе воістину щасливий день! Нас випробовували в Силітусі, і ми пройшли це випробування!\n\nЗвістка про знищення нашого північного табору може вразити серця невірних, але цю бійню не слід сприймати як трагедію. Ні!", [2] = "Пролиття нашої крові одним із членів Вищої Ради Безодні — це благословення! Ми повинні заздрити нашим полеглим товаришам, бо їхні душі тепер перебувають у череві найправеднішого звіра!\n\nХвала Старим Богам! Слава їхнім слугам! Слава Сутінковому Молоту!" },
    [20678] = { [1] = "Справи культу, том 233\n\nНам знову випала рідкісна можливість, мої брати та сестри! Кенарійське Коло, мерзенний культ любителів природи, засилає проти нас своїх агентів. Вони, мабуть, хочуть перешкодити нам добувати червоні камені поваби. Ми не можемо цього допустити!\n\nЧервоні камені мають важливе значення для наших нових союзників. Ми не повинні дозволити прислужникам Кенарійського Кола завадити нам. Стійте твердо, мої вірні друзі. Стійте непохитно!" },
    [20679] = { [1] = "Як ми знаємо, що вони нас люблять?\n\nДехто може здивуватися, як Старі Боги та їхні прислужники можуть нас любити. Хіба вони не вбивають нас? Хіба вони не завдають всім болю і страждань? Як можуть істоти, настільки схильні до злоби, мати любов у своєму серці?\n\nНа це питання є проста відповідь. Настільки проста, що її не потрібно навіть вимовляти.", [2] = "Віра. Віра — це джерело радості нашої служби. Віра зігріє нас у найхолодніші ночі в Силітусі. Віра збереже нас у милості наших господарів, коли настануть Останні дні.\n\nВіра врятує нас." },
    [2113] = { [1] = "Майстер Карвін,\n\n{стать:Посланець:Посланниця} цієї записки {стать:проявив себе гідним:проявила себе гідною} Світла, {стать:здатним:здатною} боротися з невмерлими та демонами, що заполонили кордони Смерколісся, та бажає приєднатися до родини Карвінів на їхньому шляху до Світла.\n\nТому я пропоную вам доручити {стать:цьому поборнику:цій поборниці} Світла подальші обов'язки — можливо, пошук мешканців міста, яких підозрюють в допомозі ворогам Світла.\n\nЗ повагою,\nКалор" },
    [21130] = { [1] = "Любий щоденнику,\n\nСьогодні мій заклятий ворог, Нараін Тихомрій, спробував обдурити мене, пославши своїх приятелів на страту. На ЙОГО страту. Ти можеш в це повірити?\n\nЯ пройшов через стільки труднощів, розробляючи цей диявольський план, щоб виманити його з тієї проклятої халупи, а він витворяє таке? Та це неважливо... Я занадто злий, щоб продовжувати писати. Повернусь пізніше.", [2] = "Любий щоденнику,\n\nЯ в гніві виліз зі своєї схованки після мого останнього запису. Який же я був злий. Я хочу переробити уніформу моїх прислужників, щоб вона краще демонструвала мій гнів. Мені стало трохи краще, але все одно чогось не вистачає. Я скоро повернуся...", [3] = "Любий щоденнику,\n\nГаразд, я вже в порядку. Я бив одного зі своїх прислужників, поки він не розплакався, як мале дівчисько.\n\nХм... Тепер мені якось ніяково. Зачекай хвилинку! Чорт забирай, я ЗЛИЙ геній! Злий, розумієш? Як же я розчарований в собі. Зараз повернуся.", [4] = "Любий щоденнику,\n\nЯ обійняв його і сказав, щоб він продовжував працювати. Мені вже краще. Нехай це залишиться між нами, щоденнику.\n\nНа чому я зупинився? А, так, НАРАІН! АААА!!! Ненавиджу його. Саме він вихвалявся на кожному іспиті, коли ми вчилися у Гномреґанському інституті штукарства.\n\nМене вигнали? Як на мене, то Гномреґан отримав по заслугах!\n\nЦе все на сьогодні. Солодких снів, щоденнику!", [5] = "Любий щоденнику,\n\nМабуть, я старію. Я зовсім забув, що розповідав тобі про Нараіна та його обман. У всякому разі, я так розлютився, коли побачив замість Нараіна приманку, замасковану під нього, що наказав номеру два знищити цього дурня!\n\nЯ сів у свій літак і почав шматувати його дорогоцінну, дурнувату, тупу книжку мовою драконів. Що за показуха? Хто зараз читає мову драконів? Як же я його ненавиджу!", [6] = "Любий щоденнику,\n\nВибач, я заснув. Тож я літав злий, виривав та викидав розділи цієї дурнуватої книжки. Я побачив під собою в ущелині Темного шепоту демона і вирішив зробити з першого розділу магічний паперовий торнадо і розірвати його тіло на мільйон шматочків! Я зміг розслабитись. Магія + папір = веселощі.\n\nЦе зробило мене дуже щасливим, тож я вирішив полетіти в Східні Королівства. Моєю першою зупинкою було Палаюче Ядро. Нараін завжди говорив про це місце! \"Коли я був у Палаючому Ядрі, Раґнарос те, Раґнарос се...\"", [7] = "А знаєш що? Якщо йому там так подобається, може, він спробує зібрати свою книгу докупи, пішовши до Палаючого Ядра і відновивши розділ з купи попелу! Ха!\n\nПоки я пролітав тут, я подумав, що деякі з тих невільних техніків в лабораторії старого Віктора Нефарія могли б скористатися цими драконячими штуками. Бум!", [8] = "Це ставало непоганою забавою. Мені справді хотілося розірвати цю кляту книгу!\n\nДалі діло пішло легше.\n\nОдин розділ я викинув в Підмістя — дім смердючих напівзогнилих мерців і, можливо, найкращого чилі, який я коли-небудь куштував. В Штормовій, столицю сиру — ще один. Щоденнику, ти коли-небудь клав сир зі Штормовою на чилі з Підмістя? АГОВ? Це має насторожити.", [9] = "На той момент я вже втомився, тож розвернув літак і полетів додому, але перед цим, зроблю ще дві зупинки. Я пролетів над лордом Каззаком та його демонами в Проклятому Рубці (він ненавидить, коли я так роблю) і скинув ще один вантаж в димохід Оніксії.\n\nЯ втомився. Йду спати." },
    [21314] = { [1] = "Від імені Пасовищ Димного Лісу ще раз дякую за твою допомогу. Ми не впевнені, в кого саме зараз Метцен, тому потрібно перевірити обидві банди!\n\nЧас — це гроші, і зараз нам його дуже не вистачає. Рятувальну опрерацію потрібно проводити швидко, оскільки недооцінювати жорстокість цих бандитів не варто.\n\nВ будь-якому випадку, наступні дві сторінки — це отримані нами вимоги про викуп. Щасти тобі...", [2] = "Якщо хочете повернути оленя живим, то покваптесь з викупом. Пірати Південних морів не люблять затримок оплати, а ми знаємо, наскільки звір цінний для ВАШОГО розбою.\n\nПринесіть 1000 золотих до входу в бухту Загубленого Вітрила, що в Танарісі. Якщо хтось спробує врятувати оленя, то Метцену доведеться навчитись плавати під кілем.\n\nЯррр...\n\nПірати Південних морів", [3] = "Вашому дорогоцінному улюбленцю не дуже подобається нещадна спека Випаленої ущелини... Ви вчините мудро, якщо швидко виконаєте наші вимоги.\n\nВи принесете нам 5 зоряних рубінів і 700 золотих і покладете все це в один пакунок без жодних позначок. Залиште пакунок біля воріт до Каменярського тунелю, у вас є тиждень.\n\nЯкщо не виконаєте вимоги, Метцен стане головною стравою на традиційному бенкеті дворфів Темного Заліза на честь свята Зимового Покрову.\n\nМммм... оленина...", [4] = "Швидше вітру він літає на санчатах дивних,\n\nІ зі свистом підганяє оленів чарівних:\n\n\"Вйо, Мерсер! Чілтон! Джордан і Гудмен!\n\nГайда, Неґл! Пардо! Каплан і Метцен!\n\nМчіть ви хутко над домами,\n\nДимарями і дахами.\"" },
    [2154] = { [1] = "Морган Ладімор був великим і благородним лицарем, який захищав невинних, бідних і стражденних. Протягом багатьох років він старанно працював у віддалених районах Азерота, допомагаючи пригнобленим і приносячи правосуддя їхнім гнобителям.\n\nВлітку свого вісімнадцятого року він одружився з молодою дівчиною, на ім'я Ліз. Вони дуже кохали одне одного, і з часом у них народилося троє дітей — син і дві доньки.\n\nМоргану було тридцять два роки, коли почалася війна в", [2] = "Лордероні. Морган служив під командуванням легендарного паладина Утера Світлоносця, де боровся з орками та невмерлими. Залишивши дружину та дітей в рідній домівці, Морган вирушив на війну.\n\nМинали роки, війна затягувалася, і Морган став свідком багатьох жахливих подій, включно з розформуванням паладинів Сріблястої Десниці, загибеллю Утера і поширенням чуми. Єдине, що утримувало його від божевілля — це впевненість у тому, що", [3] = "одного дня він повернеться до дружини та дітей.\n\nЗгодом Морган повернувся на батьківщину, але не ту, якою він її пам'ятав. Колись зелений ліс був заражений і кишів невмерлими та іншими темними силами. Скрізь стояли зруйновані будинки та ферми, а кладовище на Воронячому пагорбі тепер займало величезну частину місцевості. Шокований і спантеличений Морган врешті-решт прийшов до свого будинку, де побачив самі руїни. Не знаючи, що сталося з його домівкою, він", [4] = "пішов до селища в пошуку відповідей і дружини з дітьми.\n\nМорган розпитував про свою родину, але не знайшов жодної відповіді. Жрець з Темнодолу, як тепер називається селище, сказав, що він може пошукати надгробний камінь на цвинтарі Воронячого пагорба. Морган відмовлявся вірити, що його сім'я загинула, і продовжував обшукувати кожну ферму і будинок в Смерколіссі, але безрезультатно.\n\nМорган поїхав з Темнодолу до сусіднього Приозер'я, сподіваючись, що його сім'я втекла. Дорогою", [5] = "туди він вирішив, всупереч своєму здоровому глузду, зайти на цвинтар Воронячого пагорба. Морган годинами блукав серед могил. Він впізнавав імена багатьох знайомих йому людей і все більше впадав у відчай. І раптом він побачив їх: маленьку, недоглянуту ділянку з трьома маленькими надгробками. Жах охопив його, коли він наблизився. Морган змахнув пил з найбільшого надгробка, щоб прочитати ім'я. На камені були вирізьблені літери, які він", [6] = "найбільше боявся побачити:\n\nЛіз Ладімор\nКохана дружина і мати\n\nПобоювання Моргана втілилися в життя, горе і печаль охопили його, і він, ридаючи, впав на коліна. Годинами він дивився на ту єдину могилу, просячи в холодного каменю прощення. Потім, через кілька годин, щось у ньому зламалося, і він почав кидатися на нього. Він витягнув свій меч і з криками почав сипати удари на могильні плити. Засліплений своєю люттю, він продовжував трощити все на своєму шляху, чим привернув увагу", [7] = "трьох наглядачів кладовища. Коли вони спробували його заспокоїти, він переніс свій гнів на них і, звинувативши їх у всіх своїх нещастях, убив усіх трьох.\n\nПізніше, коли лють вщухла і Морган прийшов до тями, він побачив свій закривавлений меч, встромлений у груди одного зі наглядачів. Доведений до розпачу, він витягнув свій кинджал і встромив його собі в серце.\n\nТіло Моргана Ладімора і тіла трьох його жертв було знайдено", [8] = "наступного дня. Його швидко поховали, без церемоній, у нашвидкуруч викопаній могилі на околиці кладовища. Через те, що Морган убив невинних, що повністю суперечило його переконанням, а також через горе, яке він відчував через те, що не зміг врятувати свою сім'ю, Морган не отримав спокій в смерті, і жив далі, як один з неупокоєних мерців.\n\nЧерез кілька днів його могила була виявлена порожньою, а тіло так і не було знайдено. Істота, на яку перетворився Морган, блукає", [9] = "Смерколіссям, охоплений горем через втрату дружини та дітей і ненавистю до себе. Мор'Ладім, як він тепер себе називає, поневіряється Смерколіссям і з помсти вбиває все живе." },
    [2161] = { [1] = "Жах останніх кількох тижнів стає нестерпним, але я відчуваю, що, записуючи те, що я бачив, я зможу якось заспокоїтися. Тож я роблю це, бо це єдина розрада, яку я можу собі дозволити в ці похмурі дні.", [2] = "Все почалося зі знахідки проклятої коси в Погубі Роланда. До цього жахіття цих земель здавалися такими ж смішними, як жахіття мешканців Північнокрайової долини.\n\nАле відтоді, як я побачив держак коси, що стирчав з купи уламків у шахті та, на свою дурну голову, витягнув його, Погуба Роланда стала місцем жахливих смертей!", [3] = "Після того, як я витягнув косу, вони накинулися на нас звідусіль, виповзаючи з найменших щілин під нашими ногами та падаючи на нас згори. Половина наших людей полягла в ті перші панічні хвилини. Решта, в тому числі і я, намагалися втекти. Коли я біг, я бачив, як багатьох моїх побратимів хапали зубами та розривали кігтями, чув несамовиті крики, які потім обривалися або затихали.", [4] = "Я можу лише здогадуватися, чому я вижив тієї ночі. Я завжди був обережним, завжди швидко приходив до себе після ударів і відскакував від пасток. Саме тому я маю таке прізвисько. Тож, можливо, саме моя обережність і врятувала мене...\n\nА може, це була коса, яку я витягнув з-під завалів. Це не може бути сама коса, бо я загубив її під час тієї божевільної втечі. Але якщо це я привів воргенів до Смерколісся, то, можливо, вони зжалились наді мною. Будь вони прокляті.", [5] = "Після втечі з Погуби Роланда я сховався в якійсь стодолі, що належала чоловікові, на ім'я Свен. Я провів там кілька днів, і мене охопив такий жах, що я жодного разу не показався Свену або його сім'ї. Судячи з того, що я спостерігав зі своєї схованки, я зрозумів, що ці фермери були цілком пристойними людьми. Якби я вийшов звідти, гадаю, вони б мене прийняли, але мені завжди було важко комусь довіряти. Та стало ще важче після того жаху, який я пережив в шахті.\n\nТож я продовжив ховатися.", [6] = "<Решта книги порожня.>" },
    [2188] = { [1] = "Ґрелін,\n\nВ мене мало часу й купа важливих справ, і я сподіваюся, що твоє розслідування тролів не буде однією з них. Тому я дозволяю тобі діяти від мого імені в боротьбі з тролями у будь-який спосіб, який ти вважаєш за потрібний. Особливо, якщо ти зможеш знайти доцільне рішення.\n\n\nМаґні Бронзобородий" },
    [2223] = { [1] = "Нижче наведено процес та графік збору золота Непокірними з шахт Ельвинна до нашого штабу в Західному краї.\n\nГрафік збору:\n\nНеділя: 12:30\nСереда: 12:30\n\nУ зазначені дні золото, видобуте на шахтах Ельвинна, буде збиратися на гарбузовому наділі Бреквеллів. Агента, відповідального за ці збори, \"Збирача\", можна впізнати за перснем з гравіюванням, який я вручив йому особисто.", [2] = "Представник зі штабу Непокірних зв'яжеться зі Збирачем, після чого він передасть зібране золото.\n\nПереконайтеся, що цей процес відбудеться без помилок і з максимальною обережністю. Збирач безпосередньо відповідає за передачу золота, але зрештою кожен член Братства Непокірних має добросовісно і дисципліновано виконувати свої обов'язки.", [3] = "Пам'ятайте, браття, колись були гордими ремісниками. І ми будемо виконувати наші сьогоднішні обов'язки з тією ж сумлінністю, з якою ми завжди підходили до роботи.\n\n— ЕВК" },
    [22344] = { [1] = "ЖАРОВНЯ ВИКЛИКУ: ПОСІБНИК КОРИСТУВАЧА\nДе знайти місця з привидами\n\nВСТУП\n\nНа цих сторінках відзначені місця, де перебувають занепалі духи тих, хто причетний до інциденту з амулетом лорда Вальталака. Хоч ти вже {стать:врятував:врятувала} моїх колишніх товаришів, але я припускаю, що відгомони того огидного зла, яке колись спотворило їхні душі, все ще не залишили місця, де живуть привиди. Такою була могутня сила духу лорда Вальталака.\n\nКрім того, жаровня може бути використана для виклику лорда Вальталака, але, як і раніше, слід дотримуватися крайньої обережності.", [10] = "КОРМОК, продовження...\n\nПізніше, під час наших подорожей, Кормок почав вивчати некроматичний бік магії. На жаль, моторошній голові дуже подобалось викликати мертвих духів, вона отримувала від цього збочене задоволення, особливо від виклику духів з острова Позбавлення та контролю над ними.\n\nПісля того, як наша компанія розпалася, Кормок вступив до Некроситету, щоб продовжити здобувати \"освіту\". Примарні душогуби з легкістю проникли в школу та вбили його прямо на очах у його нового вчителя, Раса Кригошепта.\n\nТому кімната Раса Кригошепта — ще одне з місць з привидами, де можна використовувати жаровню.", [11] = "ЛОРД ВАЛЬТАЛАК\nБлагородний драконід і колишній генерал Чорноскельного шпиля\n\nДо генерала Драккісата був лорд Вальталак, могутній драконід-чорнокнижник. Керівництво шпилем часто переходить з рук в руки, і, на жаль для нас, ми зіграли й свою роль в останній зміні влади.\n\nОдин гоблін контрабандист з Грабіжної Бухти, Ґремнік Хуткостриб, доручив нам викрасти книгу заклинань Вальталака. Невідомо, чи хотів він її вивчити, чи продати (чи й те, й інше), та це й неважливо. Важливо те, що ми проникли на верхівку Чорноскельного шпиля і вбили лорда Вальталака у власному лігві. Ось тоді й почалися справжні веселощі.", [12] = "ЛОРД ВАЛЬТАЛАК, продовження...\n\nМи не мали жодного уявлення, наскільки могутнім чарівником був Вальталак та як він міг маніпулювати душами, інакше ми, мабуть, ніколи б не взялися за цю роботу. Але ми таки взялися і це виявилося нашою останньою роботою.\n\nВбивши лорда Вальталака і забравши його книгу заклинань, Кормок, мабуть, відчув щось в амулеті лорда. Він наполягав на тому, щоб забрати його як свою частку здобичі, що швидко переросло в палку суперечку і ми мало було не побились за цю річ. Тоді ми ще не знали, що в амулеті насправді містилася частина духу Вальталака. Та, на превеликий жаль, ми дізнались про це занадто пізно.", [13] = "ЛОРД ВАЛЬТАЛАК, продовження...\n\nРозбивши амулет на шматки, ми втекли від посталого духа Вальталака та його армії примарних убивць. А галас, який ми підняли, коли боролись за амулет, розбудив кількох захисників шпиля, що були там!\n\nМайже всі ми вибралися з Чорної скелі, думаючи, що все закінчилося. Але навіть з потойбіччя Вальталак посилав на нас своїх воїнів, де б ми не ховалися. Незадовго після цієї місії Примарний Клинок розпався і ми стали легкою здобиччю.\n\nЯк ти {стать:міг:могла} зрозуміти, це робить лігво лорда Вальталака, яке зараз є кімнатою Звіра у Чорноскельному шпилі, останнім з місць з привидами.", [2] = "ВСТУП, продовження...\n\nСама жаровня функціонує так само як і жаровня поклику. Просто розмісти її в будь-якому з п'яти місць з привидами та вона викличе духів померлих.\n\nДо речі, думаю, тобі буде цікаво дізнатися, що стяг виклику можна також використовувати на арені в Чорноскельних надрах. Коли будеш там, не забудь провчити Телдрена та його поплічників за мене, щойно з'явиться така можливість.\n\nЧитай далі, якщо хочеш дізнатися більше.", [3] = "ІЗАЛІЄН\nНічна ельфа-жриця Місяця\n\n\nКоли Ізалієн покинула своїх товаришів, вона вирішила відправитись в Грізний Молот, занепале місто предків нічних ельфів, колись відоме як Ельдре'Талас. До сьогоднішнього дня там збереглася велика бібліотека знань, святилище, яке невелика група нічних ельфів змогла вберегти. Вона хотіла знайти відповіді як щодо своєї спадщини, так і, можливо, щодо уламків амулета. Варто зазначити, що вона також була хорошим другом Фалріна Деревотворця.", [4] = "ІЗАЛІЄН, продовження...\n\nНа жаль, коли вона разом зі своїм гіпогрифом Емпіреєм заходили до міста, на них напав Альззін-Диковертень та його прислужники. Там вона навіки полягла. Можливо, це й на краще, що Ізалієн так і не розкрила таємниці тих злих чарів, які лорд Вальталак наклав, щоб утримати частину своєї сутності в амулеті.\n\nКімната просто неба, де мешкає Альззін, є одним з таких місць з привидами.", [5] = "МОР СИВЕ КОПИТО\nТаурен-друїд і перший з полеглих\n\nМор Сіре Копито завжди був вірним і надійним товаришем Примарного Клинка. На жаль, він першим потрапив до рук злих прислужників лорда Вальталака.\n\nКоли ми втікали від Вальталака, нас переслідувала його армія справжніх примарних душогубів та ловців. Втеча з Чорноскельного шпиля була, м'яко кажучи, справжнім кошмаром. На жаль, дорогою Мор якимось чином втратив рівновагу та впав, хоча я підозрюю, що його штовхнули. У будь-якому випадку, він впав на нижній рівень шпиля.", [6] = "МОР СИВЕ КОПИТО, продовження...\n\nПізніше ми дізналися, що Мор насправді вижив після падіння. Але, на жаль, для мого доброго друга це був лише початок, він потрапив у полон до тролів Тазз'Алора. Незадовго після того, як його катував воєначальник Вун, група вбивць Вальталака нарешті позбавила його від страждань.\n\nЯкщо ти хочеш викликати дух Мора Сивого Копита, то кімната воєначальника Вуна є місцем з привидами.", [7] = "ЯРІЄН І СОТОС\nРідні брат з сестрою та члени Багряного Походу\n\nЯрієн і Сотос були двома найбільш нестерпними людьми, яких я знав. Проте воїнами вони були винятковими, якщо їм добре платили. Гадаю, саме тому Антіон, лідер Примарного Клинка, їх так цінив.\n\nЗрештою, Ярієн і Сотос захопилися вченням Багряного Походу. Вони завжди демонстрували завзяття у боротьбі зі Скарою, яку ми зустрічали під час наших подорожей, і ми підозрювали, що їхня сім'я мала зв'язки з цією організацією.", [8] = "ЯРІЄН І СОТОС, продовження...\n\nЗгодом вони почали проходити випробування, які є обов'язковими для тих, хто прагне приєднатися до Багряного Походу. Найбільше вони хотіли, щоб їх прийняли в ряди лицарів, але, очевидно, що це вимагало пройти набагато складніші випробування. Пізніше з'ясувалося, що Сотос насправді провалив свій останній іспит. Але Ярієн цього не могла допустити та наполягла на тому, щоб він приєднався до лав лицарів разом з нею. Наскільки нам відомо, верховний лицар Датроган вбив їх обох прямо посеред своїх покоїв.\n\nТому, ще одним місцем з привидами є Багряний трон всередині Багряного бастіону, що в Стратгольмі.", [9] = "КОРМОК\nДвоголовий огр-некромант\n\nЩо можна сказати про Кормока? Він був двоголовим огром-заклинателем, і раніше навіть був не таким вже й поганим. Ми його зустріли коли він був полоненим на одному об'єкті в Палаючому степі, де ми працювали, там ми його і прийняли до себе. Він виявився дуже корисним помічником, коли допоміг нам вилізти з дуже скрутного становища, в яке ми там потрапили, і став одним з найкращих магів нашої компанії.\n\nНас здивувало то, що обидві його голови поводилися абсолютно по різному. Одна завжди була веселою, навіть можна сказати трохи дурнуватою, а інша — хитрою, задумливою і з мертвим поглядом. Насправді було трохи моторошно." },
    [22595] = { [1] = "Заклик до всіх, хто здатен тримати зброю:\n\nСкара повернулася, і ми повинні відкласти всі наші сварки та протистояти цій загрозі. Сріблястий Світанок радий бачити кожного, хто бажає взятися за зброю та боротися проти загрози Скари.\n\nТі, хто готові стати на захист наших земель, повинні зібратися в Каплиці Надії Світла у Східних Зачумлених землях. Разом ми переможемо.\n\nАрхіваріус\nСріблястий Світанок" },
    [22930] = { [1] = "Моя Емілі,\n\nКілька днів тому ми отаборилися у цьому забутому Світлом місці, виконуючи наказ короля та повертаючись додому. Попри ці похмурі пейзажі, я відчував легкість на серці, бо знав, що після холодного походу до берега та довгої, виснажливої подорожі, я знайду розраду у твоїх обіймах.\n\nСьогодні ми дійшли до берега, але виявили, що від наших кораблів залишилися лише обвуглені уламки. Ми не можемо повернутися, і у нас немає іншого вибору, окрім як йти вглиб цієї жахливої пустелі.\n\nЯ пішов на край світу, щоб захистити тебе, Емілі... А тепер... Я всім своїм серцем хочу бути в Лордероні з тобою.\n\nЩоранку я думаю тільки про тебе. Спогади про тебе зігрівають мою душу в цій крижаній пустелі, кохана, і ніхто не зможе забрати їх в мене.\n\nМаксвелл" },
    [22932] = { [1] = "Рубен,\n\nЯ пишу цього листа, знаючи, що ти можеш ніколи не отримати його. Я просто не можу скласти руки та слухати постійний гуркіт в стінах Вогнедолу. Невмерлі підступають до нашого села і не збираються відступати, а нам доручили захищати мешканців і чекати підкріплення.\n\nВ останньому бою мені зламали ногу, тож я тепер абсолютно безпорадний, сиджу з мечем напоготові й чекаю, коли наша оборона впаде. Навколо тільки стогони й смерть... це жахливо.\n\nТут, на передовій, разом з нами воює принц Артас. Якби не він, нам би вже давно прийшов кінець. Його любов до цієї землі та її народу вселяє надію. Я радий, що б'юся під його командуванням і буду вірним йому до кінця своїх днів.\n\nБої стають все запеклішими, зі зламаною ногою чи ні, я не можу тут сидіти. Нам потрібен кожен, хто може тримати в руках меч. Сподіваюся, ці рядки ти читатимеш у кращі часи.\n\nТвій друг,\nЛеґрем" },
    [22944] = { [1] = "Геліано,\n\nШкода вас розчаровувати, але я, Варґус, все ще живий. Мені набридло тинятися по селах в цих безглуздих обладунках.\n\nТепер нам наказали вирушити до Андоралу за зерном чи ще якоюсь дурницею. Яке мені має бути діло до зерна в Андоралі? Вся ця служба в армії просто безглузда.\n\nБудьте певні, тітонько Геліано, я повернуся за вашою спадщиною. Навіть якщо мене тяжко поранять і я залишуся помирати з голоду, моя злість не дасть мені здатися.\n\nВарґус" },
    [22945] = { [1] = "Люба Амелія,\n\nСьогодні ввечері я бачив речі, які будуть переслідувати мене вічно.\n\nСтратгольм охоплений полум'ям... і ми за це несемо відповідальність.\n\nСьогодні ввечері наш принц повів нас вулицями міста. Він наказав нам вдиратися в домівки городян і... вбивати їх уві сні. Принц Артас стверджував, ці вони були заражені чумою і їх потрібно вбити, поки вони не вбили нас.\n\nЦе була різанина. Сотні жителів тихо вмирали від мечів тих, хто присягнувся їх захищати. Я більше не міг цього терпіти. Я втік.\n\nМоже, я і дезертир, але я не міг чинити такі звірства. У кожній жертві я не міг не бачити твого обличчя чи обличчя наших дітей на жертвах. Якщо протистояти цьому означає бути зрадником, то так тому і бути.\n\nЯ сподіваюся, що з часом знайду дорогу до вас, але дороги небезпечні. Передай дітям, що я люблю їх.\n\nДжеймс" },
    [22946] = { [1] = "Самло,\n\nПринц Артас веде нас усе далі й далі на північ, і мені стає все важче на серці. Колись він яскраво сяяв Світлом, але тепер я відчуваю, як його поглинає темрява. Його завзяття затьмарене якимось кошмаром у його душі, якого я не можу збагнути...\n\nНезабаром ми висадимось у замерзлій пустці. Хоча багато солдатів страждають від холоду та битв з місцевими звірами, Артас каже, що те, що він шукає в кризі, змінить хід битви. Але його слова мене не втішили, бо після того, як він їх сказав... на його обличчі з'явилася похмура посмішка, від якої у мене на душі стало ще холодніше.\n\nМолися за нас, Самло, і молись за наш світ,\n\nТорґал" },
    [22948] = { [1] = "Дорога Памело,\n\nЗавтра ми дійдемо до Андорала і, я боюся, що це буде мій останній лист до тебе, кохана. Невмерлі не знають втоми, а ми — всього лиш люди. Нам їх не перемогти. Та не хвилюйся, хоч ми й, скоріше за все, загинемо, але наша надія залишається з нами. Світло переможе!\n\nІ я втішаюся, знаючи, що, коли ця темна нечисть прорве нашу оборону та трощитиме нас, я не буду з жахом думати про смерть. Я буду думати про тебе, моя люба, і моя душа знайде спокій.\n\nКрістоф" },
    [23008] = { [1] = "Привіт, {ім'я:к}. Мені вдалося знайти трохи інформації з тієї записки.\n\nНа жаль, про Джеймса знайшлося небагато. Однак, знайшлося трохи інформації про сім'ю Амелії.\n\nНі вона, ні її діти не пережили війну, але вижив її брат, чоловік, на ім'я Александер Кальдер. Ти можеш знайти його в Закинутій Печері, що в Залізогарті, де він вивчає небезпечну магію Палаючого Легіону.\n\nУ неї також була двоюрідна сестра, з якою вона була близька, жінка, нині відома як Дезе Снігобій, яка сприяє битві за низину Араті в Орґріммарі.\n\nТобі варто відвідати когось з них. Думаю, що їм буде цікаво почути про Амелію." },
    [23010] = { [1] = "Вітаю, {ім'я:к}. Гадаю, тебе можуть зацікавити результати мого дослідження.\n\nВиявляється, і у Рубена, і у Леґрема залишилися, так би мовити, рідні. Навіть якщо вони вже знають про долю загиблого солдата, думаю, варто відвідати когось з них.\n\nКолишню дружину Рубена, Джоанну Білозал, можна знайти у військовому кварталі Підмістя, де вона проводить більшу частину свого часу. Я не знаю, як вона сприйме новину.\n\nЩо ж до Леґрема, то його тітка стала опікункою сиротинця у Штормовії, і це чудова посада.\n\nЯким би не був твій життєвий шлях, я бажаю тобі всього найкращого у твоїх починаннях." },
    [23011] = { [1] = "{ім'я:к}, я сподіваюся, що цей лист знайде тебе у доброму здоров'ї. Мені довелося попітніти, щоб з'ясувати хоч щось про авторів записки, яку тобі вдалось знайти.\n\nБатько Самли очолює відречених і тролів, які здійснюють паломництво до Громового Бескиду шляхами своєї віри. Його звати Майлз Велш, і ти знайдеш його разом з іншими невмерлими у Джерелах Видіння.\n\nУ Торгала живою залишилася сестра, Елісса Дюма. Наскільки мені вдалося з'ясувати, вона проводить час в храмі Місяця, що в Дарнасі.\n\nЯ закликаю тебе відвідати всіх, кого зможеш, {ім'я:к}. Можливо, інакше вони ніколи не дізнаються про долю Торгала чи Самли." },
    [23012] = { [1] = "Архіваріус передав лист, який тобі вдалось знайти, {ім'я:к}, і я хочу повідомити тобі новини.\n\nОстаннього вцілілого члена сім'ї згаданого Варґуса вдалося відстежити в пустелі Силітусу, де він мешкає в Кенарійській цитаделі. Його звати Ґарон Гатчінс.\n\nТобі варто поговорити з ним під час наступного візиту туди. Можливо, йому буде цікаво почути те, що ми дізналися." },
    [23013] = { [1] = "Вітаю. Мені нарешті вдалося знайти час, щоб вивчити послання, яке ти {стать:знайшов:знайшла} у Скари. Це було нелегко, і ось результати моєї праці — інформація про живого родича загиблого.\n\nСестра Максвелла, на ім'я Заріна Вітрозгин, тримає невеличку зброярську майстерню в Грабіжній Бухті. Я не знаю, наскільки вона була близька з братом, але тобі варто зазирнути до неї, як будеш там проїздом. Зараз така інформація з'ясовується дуже рідко, тож ти можеш зробити добру справу." },
    [23016] = { [1] = "Мені, нарешті, вдалося знайти деякі відомості про солдата, з яким ти {стать:бився:билася}. Його родовід зберігся дуже погано, тому мені довелося постаратися.\n\nЧи повіриш ти, що доглядач Ален з Каплиці Надії Світла насправді є сином Крістофа? Можливо, йому стане легше, коли він почує, що сталося з його батьком. Тож якщо знову опинишся на службі у Сріблястого Світанку в Зачумлених землях, будь ласка, поговори з ним. Зроби добру справу." },
    [2560] = { [1] = "Мій щоденник\n\nЖах останніх кількох тижнів стає нестерпним. Чому, пишучи слова в цій книзі, я якимось чином рятуюсь від божевілля? Можливо, через те, що я ніби сповідуюся у своїх гріхах перед мовчазним співрозмовником, або звільняю свій розум від важких мук і переношу їх на папір.\n\nЯ почав вести щоденник до цього, але він залишився там, куди я не можу повернутися. Тому я почну писати спочатку. Але цього разу я писатиму тільки правду.", [10] = "Мої руки тремтять, коли я згадую ту ніч, коли Свен був далеко, а його сім'я була приречена зустріти чорних вершників наодинці. Знову жаль мучить моє серце, я був там і міг би виступити проти тих лиходіїв з перевалу Мертвого Вітру. Але цей жаль нічого не значить. Це те саме, що мучить кожного, хто пережив трагедію. Я знаю, що якби я вийшов зі своєї схованки, мене б теж убили, моє тіло розірвали б на шматки, які розлетілися б так далеко, що мене б не впізнали.", [11] = "Але, хоч я знаю, що нічого не міг зробити, щоб зупинити це жахливе вбивство, один справжній жаль все ж таки залишається — я привів чорних вершників на ферму Свена. Моя знахідка не лише випустила воргенів на Смерколісся, а й привернула увагу вершників з перевалу Мертвого Вітру.\n\nЯ знаю це, бо перед тим, як почати різанину, вони поставили одне запитання дружині Свена, яка притискала до себе дітей, втішаючи їх, як могла, хоч і знала, що смерть близько.", [12] = "\"Коса Елуни\", — вигукнув один з вершників голосом, одночасно різким і пронизливим, як скрегіт сокири по каменю. І останнє слово — Елуна — він скрикнув, ніби заглушаючи звук.\n\nЖах охопив мене, коли я почув цей голос, як від його жахливого звучання, так і тому, що... я знав, про яку косу говорив вершник. Це була та сама проклята річ, яку я витягнув зі скель Погуби Роланда кілька днів тому. Це те, що шукали чорні вершники!\n\nІ це те, що вбило родину Свена.", [13] = "Я так і не дізнався імені дружини Свена, бо чоловік і діти називали її лише \"люба\", \"кохана\" і \"мамо\". Але я хотів би його дізнатись. Я — єдиний живий спогад про її вчинок того дня і, хоча вона була простою дружиною фермера, я ніколи не бачив, щоб чоловік чи жінка діяли з такою хоробрістю.\n\nЗвичайно, вона не знала про косу, але коли дізналася, що вершники шукають, в її голові миттєво сформувався план.\n\nІ він був сміливий і розумний. Якби ж то він спрацював.", [14] = "\"Коса?\" — запитала вона спокійним голосом. \"Звісно, знаю. Хто б тут не знав?\" Вона подивилася на вершників твердим поглядом і я міг би заприсягтися, що повірив їй, якби не знав правди. Вона ніяк не могла знати про косу.\n\nЇї хитрість спрацювала. Той вершник, який щойно поставив запитання, злегка нахилив голову до неї та крикнув: \"Де?\"\n\n\"Я відведу вас. Усіх вас\", — сказала вона і я побачив, як в її очах промайнула маленька надія.", [15] = "\"Але дорога далека і мої діти будуть нас затримувати. Ми мусимо їх залишити\".\n\nЇї трюк був простим, але саме простий трюк мав найбільше шансів на успіх. Якби він спрацював, то вона відвела б вершників якомога далі від ферми. Вона б загубилася, але її діти були б у безпеці. І це могло спрацювати, якби вершники повірили в її благородну брехню.\n\nХоч я ніколи не був послідовником Світла, я палко молився за дружину Свена, коли вона стояла навпроти тих жахливих вершників.\n\n\"Будь ласка\", — молився я. — \"Хоч би вони повірили\".", [16] = "Вони стояли, завмерши, а вона спокійно дивилась їм в очі. Тоді один з вершників підняв голову, ніби почувши далекий поклик. Він витягнув зі свого вбрання невеличкий самоцвіт і зазирнув у нього. Потім він жестом показав на дружину Свена. Світло поповзло від вершника до жінки, перетворившись на страшну білу руку. Вона дивилася на світло, не відриваючись, але за маскою спокою я бачив невпевненість. Коли рука досягла її тіла, вона обхопила пальцями її голову.\n\nІ стиснула її.", [17] = "Дружина Свена стояла непорушно, як дошка, а очі її широко розплющилися. І хоча її губи розкрились, щоб крикнути, жоден звук не вирвався назовні. Через кілька хвилин цих тортур рука відпустила її, кинувши на коліна. Вершник, який тримав самоцвіт, випростався у сідлі та з каменю пролунав гучний голос.\n\n\"Ця жінка бреше\", — сказав він голосом, який залишив шрам у моїх снах. \"Вона не бачила косу\".", [18] = "Після цього плечі вершника злегка опустилися, наче з нього вирвався дух. І тоді старим, пронизливим голосом, яким він говорив раніше, пролунали останні слова:\n\n\"Володар сказав своє слово. Вбити їх\".", [19] = "Я не можу описати, що сталося далі. У мене в голові все ясно, але навіть моя нещасна душа не може викласти на папері події тих кількох наступних жахливих хвилин.\n\nЯ можу лише написати, що сім'ю Свена вбили. І незабаром після цього Свен повернувся додому та побачив цю жахливу криваву картину. На його лиці було таке горе, що я боявся вийти до нього. І так боявся, що він мене знайде, що вибіг зі своєї схованки в стодолі. Я не знаю, де зараз Свен, але молюся, щоб він колись знайшов спокій.", [2] = "Все почалося зі знахідки проклятої коси в шахті, яку називають Погубою Роланда. Так, це був лише початок. Раніше Братство Непокірних було задоволене нашими успіхами в Смерколіссі. До того, як я знайшов косу, жахіття цього місця здавалися такими ж смішними, як жахіття мешканців Північнокрайової долини.\n\nАле відтоді, як я побачив держак коси, що стирчав з купи уламків у шахті та, на свою дурну голову, витягнув його, Погуба Роланда стала місцем жахливих смертей!", [20] = "Наступні кілька тижнів я провів, переїжджаючи з місця на місце, ніде не затримуючись через страх перед вершниками. Зараз я, як завжди, ховаюся у покинутому місті — Воронячому пагорбі. Я не можу протистояти тій силі, що вбила сім'ю Свена і знаю, що вона й досі шукає косу в Смерколіссі. Я загубив її і я дякую Світлу за це, бо якби я зберіг її, я впевнений — мене б знайшли. Навіть зараз, в глибині душі, я розумію, що мене знайдуть.\n\nЯ так втомився.", [3] = "Якби я знав, що станеться, то відрубав би собі руку, щоб не витягти ту вкриту рунами палицю. Як же я шкодую через це! Я завжди думав, що жаль — це привілей старих. Тепер я знаю, що це не старість — це безнадія, якій одягають мантію жалю, не вміючи та не бажаючи скинути її з пониклих від страждань плечей.\n\nАле годі стогнати, ніби обкурений поет. Мушу продовжити свою хроніку...", [4] = "Після того, як я витягнув косу, в шахті відбулися зміни. Світло від наших мерехтливих смолоскипів викривлялося і здавалося, ніби ми більше не можемо контролювати силу наших голосів. Іноді чоловічий шепіт гуркотів тунелями, змушуючи затуляти вуха руками, а іноді наші крики було ледве чутно за кілька кроків, подібно до легкого подиху вітру.\n\nЦе нервувало, але ми недовго дивувалися цим явищам. Це був лише передвісником того, що насправді вигнало нас із шахти. Воргени.", [5] = "Вони накинулися на нас звідусіль, виповзаючи з найменших щілин під нашими ногами та падаючи на нас згори. Половина наших людей полягла в ті перші панічні хвилини. Решта, в тому числі і я, намагалися втекти. Коли я біг, я бачив, як багатьох моїх побратимів хапали зубами та розривали кігтями, чув несамовиті крики, які потім обривалися або затихали.\n\nНаскільки мені відомо, я єдиний, кому вдалося втекти з того місця.", [6] = "Я можу лише здогадуватися, чому я вижив тієї ночі. Я завжди був обережним, завжди швидко приходив до себе після ударів і відскакував від пасток. Саме тому я маю таке прізвисько — Тремтіній. Тож, можливо, саме моя обережність і врятувала мене...\n\nА може, це була коса, яку я витягнув з-під завалів. Це не може бути сама коса, бо я загубив її під час тієї божевільної втечі. Але якщо це я привів воргенів до Смерколісся, то, можливо, вони зжалились наді мною. Будь вони прокляті.", [7] = "А можливо мені судилося стати свідком змін, які я спричинив у Смерколіссі. Можливо, це моя доля — спостерігати, як воргени вриваються на цю землю, забарвлюючи її в темряву своєю смердючою кров'ю.\n\nЯкщо це справді моя доля, то вона випала мені двічі. Адже воргени — не єдина сила, що зазіхає на Смерколісся, на нього також претендують дияволи з перевалу Мертвого Вітру.\n\nЦе наступний розділ моєї історії і я молюся, щоб він був останнім...", [8] = "Після втечі з Погуби Роланда я сховався в якійсь стодолі, що належала чоловікові, на ім'я Свен. Я провів там кілька днів, і мене охопив такий жах, що я жодного разу не показався Свену або його сім'ї. Судячи з того, що я спостерігав зі своєї схованки, я зрозумів, що ці фермери були цілком пристойними людьми. Якби я вийшов звідти, гадаю, вони б мене прийняли, але мені завжди було важко комусь довіряти. Та стало ще важче після того жаху, який я пережив в шахті.\n\nТож я продовжив ховатися. І це врятувало мені життя.", [9] = "За кілька днів після того, як я почав ховатися в стодолі, Свен поїхав зі своєї ферми в Темноділ. Він поцілував дружину, усміхнувся дітям і пообіцяв скоро повернутися з іграшками та солодощами. Бідолаха. То був останній раз, коли він бачив свою сім'ю живою.\n\nПринаймні, вони розлучилися щасливими. І принаймні його дружина померла першою і не бачила, як вбивають її дітей. Але цей маленький жест милосердя для мене нічого не значить. Я бачив усе, що сталося і це навіки переслідуватиме мене в моїх кошмарах." },
    [2619] = { [1] = "Звіт про стан справ з тролями племені Морозогривих в регіоні Морозної долини\n\nПідготовано Ґреліном Білобородом, особливим посланником сенату\n\nЗа той час, що я провів, спостерігаючи за пересуванням тролів племені Морозогривих, я дійшов висновку, що вони не становлять великої загрози поселенням дворфів у цьому регіоні. Крім того, вони є загрозою, яку можна усунути з мінімальним залученням армії. Беручи до уваги підтримку горян, що вже розташовані в", [2] = "Морозній долині та найманців (найнятих за кошти, виділені мені сенатом), я впевнений, що проблема буде вирішена найближчим часом.\n\nЦі дії були офіційно схвалені королем Бронзобородим." },
    [2628] = { [1] = "Звіт про стан справ з тролями племені Морозогривих в регіоні Дун-Морог\n\nТролі, розташовані в Дун-Морозі, здебільшого зосереджені в поселенні Морозогривих, гірській печері на західному кордоні. Їх достатньо, щоб викликати певне занепокоєння, однак, здається, вони не збираються покидати свою печеру. Це, без сумніву, тому, що вони не хочуть знову накликати на себе гнів дворфів і ризикувати своїм існуванням. Їхні дії можна розглядати як оборону своєї території,", [2] = "і я переконаний, що вони не становлять для нас реальної загрози, доки ми не порушуємо їх кордони. Ця ситуація може бути неприємною для поселень дворфів, але, враховуючи дефіцит військових ресурсів, може бути розумним віднести винищення тролів до нижчого рівня важливості та зосередитись на загрозі, яку представляють троги та Темне Залізо.\n\nВ листі також міститься копія звіту мого брата Ґреліна про Ковмар\n\nПідписано:\nСенір Білобород", [3] = "Звіт про стан справ з тролями племені Морозогривих в регіоні Морозної долини\n\nПідготовано Ґреліном Білобородом, особливим посланником сенату\n\nЗа той час, що я провів, спостерігаючи за пересуванням тролів племені Морозогривих, я дійшов висновку, що вони не становлять великої загрози поселенням дворфів у цьому регіоні. Крім того, вони є загрозою, яку можна усунути з мінімальним залученням армії. Беручи до уваги підтримку горян, що вже розташовані в", [4] = "Морозній долині та найманців (найнятих за кошти, виділені мені сенатом), я впевнений, що проблема буде вирішена найближчим часом.\n\nЦі дії були офіційно схвалені королем Бронзобородим." },
    [2637] = { [1] = "Шановні колеги та шукачі правди,\n\nРозкопки ділянки тривають, але їх уповільнює присутність трогів, про яких я повідомляв у своєму попередньому звіті. Я переконаний, що ми зможемо впоратися з ними, попри те, що деякі з них більш агресивні, ніж зазвичай.\n\nЗа останній час ми знайшли безліч артефактів, хоча у всіх випадках, окрім одного (про який я розповім нижче), знахідки були такими ж, як і раніше — цікавими, якщо не сказати просвітницькими.", [2] = "Однак, був один виняток. Нещодавно знайдені ідоли з незвичайним різьбленням (короткий опис яких ви знайдете у моєму останньому звіті), схоже, мають вплив на поведінку трогів на цій ділянці. Це різьблене каміння приваблює їх, а деяких трогів навіть доводять до сказу!\n\nДля отримання відповідей щодо цих ідолів, необхідні подальші дослідження, але я не втрачаю надії, що вони проллють світло на взаємозв'язок між трогами та титанами.", [3] = "Наостанок, я хотів би повторити свій запит щодо пороху. Мої запаси вкрай мізерні, що значно ускладнює успішне проведення розкопок. Мені повідомили, що очікуються нові постачання пороху, однак я його досі не отримав.\n\nДозвольте запитати, яка причина такої затримки?\n\nЗ повагою,\nрозвідувач Дартей Залізоплет" },
    [2639] = { [1] = "Мій любий Тарреле —\n\nВибач за поспіх, з яким писався цей лист, але в нас мало такої розкоші, як час.\n\nБригада копачів значно просунулась у пошуку важливих артефактів титанів. Але ми почали знаходити й інші стародавні предмети, зокрема великі кістки.", [2] = "Невдовзі після того, як ми відкопали кістки, нас атакували раптори. Батальйон з полку Довгокоса хоробро бився. Але врешті-решт нас розбили. Майже всі загинули. Лише троє вижили. Найгероїчнішим виявився робітник, на ім'я Ормер Залізов'яз, який врятував мене та розвідувача Вельґара.", [3] = "Ми сховалися в затишній печері. Здається, це досить безпечне місце. Але насправді ми в пастці, доки нам не вишлють війська, які розправляться з рапторами. Вельґар намагається продовжувати роботу, але я підозрюю, що він все ще дуже наляканий. Ми в скрутному становищі, Тарреле. Будь ласка, переконай Довгокоса негайно зібрати рятувальний загін.\n\nМоя любов до тебе залишається такою ж сильною, навіть у цей жахливий час.\n\n— Меррін" },
    [2720] = { [1] = "День 1:\n06:00 - 11:00 — верхній табір\n11:00 - 11:30 — перерва, обід\n11:30 - 16:00 — прохід через каньйон\n16:00 - 19:30 — верхній табір\n\nДень 2:\nТой самий розклад, що й у день 1\n\nДень 3:\nТой самий розклад\n\nДень 4:\nТой самий розклад, за одним винятком. Перед самим заходом сонця Торсен попросив мене прикривати його, коли він сповзав униз каньйонним проходом. Я припустив, що він пішов зустрітися з нашими агентами.\n\nАле через годину він повернувся. Це мене здивувало. Я сподівався, що він зустрінеться з нашими агентами й знову приєднається до Курцена. Щось не так.", [2] = "День 5:\nСьогодні Торсен був дуже схвильований. Що б він не побачив або кого б не зустрів під час вчорашнього патрулювання, напевне, налякало його.\n\nЯ припустив, що наші агенти розмовляли з ним, але коли я запитав Торсена, куди він пішов, поки я його прикривав, він мовчав. Він вважає, що я його друг, і він вірить, що захищає мене від небезпечної таємниці.\n\nЙого вірність недоречна, але сильна. Коли він знову приєднається до нас, він стане цінним доповненням до сил Курцена.", [3] = "День 6:\nРано вранці Торсен довго говорив із сержанткою Йогвою. Мені довелося вдавати, що я все ще сплю, і тому не ворушився й почув не все. Але я припускаю, що вони говорили про минулий похід Торсена.\n\nЯ уважно спостерігав за ним за обідом і помітив, що Йогва робить те саме. Пізніше Дорен викликав Торсена. У них трьох є спільна таємниця. Дорен і Йогва повинні знати, що Торсен зустрічається з вашими агентами.\n\nВін шпигує на користь повстанців.", [4] = "Ми не повинні більше дозволяти Торсену збирати розвіддані й маємо його вбити. Нашому полковнику він більше не потрібний.\n\nЯ покінчу з Торсеном за першої можливості. Але якщо ви отримали цього листа, то знаєте, що в мене ще не було такої нагоди.\n\nУ такому випадку, я пропоную, щоб наступна зустріч Торсена з нашими агентами була останньою.\n\nСлава Курцену,\n-М" },
    [2724] = { [1] = "До Шнайдерів,\n\nДоброго дня. Сподіваюся бізнес у районі Каналів йде добре. В нас тут, на Торговій площі, наплив відвідувачів.\n\nНам потрібен в'язаний одяг, оскільки запаси майже вичерпані. Будь ласка, надішліть стандартну партію щойно зможете.\n\nБажаю успіху і сподіваюся, що ваш син Турман добре навчається,\n\n--Гарлан Баґлі" },
    [2725] = { [1] = "Зелені пагорби Тернистої долини\n\nНаш перший день пройшов звичайно, як зазвичай проходять перші дні. Більшу частину часу ми облаштовували табір. Мені вдалося знайти ідеальне місце на березі річки. Судячи зі старого покинутого причалу поблизу, це місце колись було заселене. Що стосується колишніх мешканців, то цю історію може розповісти лише час." },
    [2728] = { [1] = "У наступні роки, після того, як Штормовій зрадив гільдію Каменярів, пан Имин розлютився через роль дворян у королівстві. Він більше не бажав підтримувати позицію, яку завоював для нього рід його батька у Домі вельмож.\n\nАле я відволікся. Метою цієї історії не є політичний трактат чи біографія. Це опис мого досвіду полювання на велику дичину на зелених пагорбах Тернистої долини." },
    [2730] = { [1] = "Саме тоді, коли я збирався поставити під сумнів інтерес Барвини до полювання, вона потягнулася до свого сагайдака, витягла стрілу й вистрелила прямо в бік бідолашного Барніла. Але Барвина стріляла не в Барніла. Бо коли він відійшов убік, роззявивши рота, на поверхню річки сплив великий кроколіск зі стрілою Барвини, що стирчала рівно між його двома великими очима." },
    [2732] = { [1] = "Під час однієї з таких помилок Йарс поклав важку руку на плече Барніла. Ми з Барвиною неквапливо переглянулися, припускаючи, що він збирається насварити Барніла за його необережність. Однак Йарс повільно показав головою в бік поваленого дерева неподалік. Звідти на нас дивилися пронизливих чорних ока прямо над ротом, повним гострих як бритва ікл." },
    [2734] = { [1] = "Перше вбивство звіра підбадьорило всіх учасників експедиції. Барніл пригостив нас медовухою, щоб відсвяткувати. Але гуляння було недовгим. Коли ми готували тушу звіра до транспортування в табір, нас усіх застало зненацька жахливе гарчання. За всі свої роки я ніколи не чув нічого подібного, кров стигла в жилах." },
    [2735] = { [1] = "На скелястому схилі, що височів над нами, у променях призахідного сонця вимальовувався силует найбільшого хижого кота, якого я коли-небудь бачив. Я висмалив один незграбний залп з рушниці, але кіт не злякався. Він гаркнув ще раз, цього разу голосніше, і зник.\n\nМи зібрали речі й похмуро рушили назад до табору." },
    [2738] = { [1] = "Того дня ми вирушили на південь, рухаючись по свіжих слідах пантери. Незабаром ми дісталися ущелини, через яку був перекинутий величезний мотузковий міст. Я не міг не згадати, як описував цей регіон Бранн, коли побачив це диво інженерії. Вважалося, що місцеві тролі були примітивною та незграбною расою, але з огляду на майстерність, з якою побудований цей міст, я не можу не визнати, що трольські будівельники — справжні майстри та зробили, здавалося б, неможливе." },
    [2740] = { [1] = "І Барвина, і пан Имин стояли напоготові, спрямувавши рушниці в колючу поросль біля підніжжя дерев, що похитувалися. Полуденне сонце нещадно палило нас. Повільна цівка поту стікала по скроні Йарса, коли він зводив курок. У момент клацання густа рослинність розступилася, і велика чорна пантера — прекрасний екземпляр — вискочила на рівнину." },
    [2742] = { [1] = "Рушниця різко подалася назад в його руках. Дуло пішло вбік і опинилося під рушницею Барвини. І саме в цей момент вона натиснула на спусковий гачок. Рушниця, приціл якої був незграбно спрямований на крону дерева, гучно вистрілила. З-поміж гілок закричала зграя птахів, розлітаючись навсібіч, а від дерева здійнявся клубок диму. Ми з жахом спостерігали, як величезна гілка з тріском звалилася прямо на пантеру і зламала їй хребет." },
    [2744] = { [1] = "З першим світанком ми вирушили на південь повз руїни Ткаші. Барніл висловив занепокоєння, що ми можемо зустріти тролів племені Кровоскальпих. Я нагадав Барнілу, що Кровоскальпі були більше стурбовані знищенням своїх заклятих ворогів — племені Черепотрощителів. Зайве говорити, що Барніла це анітрохи не втішило. Я, однак, мав із собою заряджену рушницю, повну сумку пороху, і трьох смертоносних мисливців, що полегшувало будь-які побоювання щодо ворожої засідки." },
    [2745] = { [1] = "Я вистояв перед величезним пекельником на полі бою з армією Палаючого Легіону, що наступала з усіх боків. Порівняно з цим банда злих тролів здається такою ж нешкідливою, як заєць на пагорбах Дун-Морога.\n\nРуїни Ткаші ми пройшли без пригод, на велике полегшення Барніла. Ми продовжували рухатися на захід до Великого моря, оминаючи руїни Зул'Кунди на півдні. Піднявшись на високу скелю над морем, ми побачили нашого першого раптора." },
    [2748] = { [1] = "Наших поспішних пострілів вистачило, щоб Барнілу вдалося відірватися. Барніл стрімко спустився з пагорба й приєднався до групи. Ми кинулися в джунглі, а зграя лютих хлястохвостих рапторів не відставала ні на крок.\n\nМисливці стали здобиччю." },
    [2749] = { [1] = "Я повів групу до моря, сподіваючись, що берег послужить нам захистом від рапторів. Поспішаючи, ми зайшли занадто далеко на північ, піднявшись на особливо високий пагорб. Це була помилка. Моя провина. Ми зупинилися прямо перед урвищем, а раптори були лише за кілька кроків позаду." },
    [2750] = { [1] = "Я повільно ступив уперед, піднявши рушницю. Я привів цих відважних мисливців на смерть. І готовий був загинути сам, захищаючи їх. Хлястохвості раптори відомі своєю невблаганною жагою до крові. Вони значно переважали нас числом. Але я б собі не пробачив, якби дозволив їм убити мене та моїх товаришів, не прикінчивши спочатку кілька цих тварюк." },
    [2751] = { [1] = "Барвина і пан Йарс Имин підготували свою зброю, обступаючи мене з обох боків, спинами до моря. Барніл переможено зітхнув і вихопив сокиру. Хлястохвости майже наблизилися до нас. Їхній рівний крок сповільнився. Тепер вони стежили за своєю здобиччю, бо знали, що загнали нас у пастку." },
    [2756] = { [1] = "Наш перший день пройшов звичайно, як зазвичай проходять перші дні. Більшу частину часу ми облаштовували табір. Мені вдалося знайти ідеальне місце на березі річки. Судячи зі старого покинутого причалу поблизу, це місце колись було заселене. Що стосується колишніх мешканців, то цю історію може розповісти лише час.", [2] = "Для цієї експедиції я зібрав Барвину Гіняй та пана Йарса Имина разом із моїм надійним помічником Барнілом Камнекухлем. Ми з батьком Барвини пройшли багато битв, захищаючи Альянс. Бачити її дорослою — це щось особливе. Батько добре навчив її володіти зброєю. Її вміння володіти луком змушує мене замислитися, чи не тече в цих жилах ельфійська кров.", [3] = "Пан Йарс Имин походить з аристократії людей. Його батько, граф Имин, був відомий своєю щедрістю. Саме граф лобіював покращення умов праці для гільдії Каменярів під час відновлення Штормовію після Другої Великої війни.", [4] = "У наступні роки, після того, як Штормовій зрадив гільдію Каменярів, пан Имин розлютився через роль дворян у королівстві. Він більше не бажав підтримувати позицію, яку завоював для нього рід його батька у Домі вельмож.\n\nАле я відволікся. Метою цієї історії не є політичний трактат чи біографія. Це опис мого досвіду полювання на велику дичину на зелених пагорбах Тернистої долини.", [5] = "Ми встали з сонцем. Барніл почав готувати сніданок. Я помітив, що увага Барвини була дещо розсіяна. Попереду був довгий день, а наше полювання наближало нас до небезпеки. Відсутність зосередженості може легко призвести до лиха. Але Барвина, здавалося, не могла відвести свій погляд від Барніла, який стояв біля берега річки та вимивав свій похідний набір.", [6] = "Саме тоді, коли я збирався поставити під сумнів інтерес Барвини до полювання, вона потягнулася до свого сагайдака, витягла стрілу й вистрелила прямо в бік бідолашного Барніла. Але Барвина стріляла не в Барніла. Бо коли він відійшов убік, роззявивши рота, на поверхню річки сплив великий кроколіск зі стрілою Барвини, що стирчала рівно між його двома великими очима.", [7] = "Ми рушили на захід, крізь густі зарості заплутаних джунглів. Повільними, виваженими кроками ми пробиралися крізь густе листя в пошуках здобичі. Ранок минув у розчарованому мовчанні. У долині все завмерло, навіть вітер. До полудня експедиція стала неспокійною, Барніл більше не пересувався обережними кроками хижака, що вистежує здобич. Навпаки, він незграбно тупцював по стежці, часто гучно наступаючи на опале листя чи сухе гілля.", [8] = "Під час однієї з таких помилок Йарс поклав важку руку на плече Барніла. Ми з Барвиною неквапливо переглянулися, припускаючи, що він збирається насварити Барніла за його необережність. Однак Йарс повільно показав головою в бік поваленого дерева неподалік. Звідти на нас дивилися пронизливих чорних ока прямо над ротом, повним гострих як бритва ікл." },
    [2757] = { [1] = "Цим звіром був самець тигра Тернистої долини. Перш ніж я встиг звести рушницю, Йарс підняв арбалет і вистрілив у звіра. Болт пішов трохи вбік, але все ж сильно зачепив лівий бік цілі. Тигр намагався втекти, але марно — його рана була надто глибокою. Кілька трагічних секунд звір спотикався, поки Барніл не добив його кинутою сокирою.", [2] = "Перше вбивство звіра підбадьорило всіх учасників експедиції. Барніл пригостив нас медовухою, щоб відсвяткувати. Але гуляння було недовгим. Коли ми готували тушу звіра до транспортування в табір, нас усіх застало зненацька жахливе гарчання. За всі свої роки я ніколи не чув нічого подібного, кров стигла в жилах.", [3] = "На скелястому схилі, що височів над нами, у променях призахідного сонця вимальовувався силует найбільшого хижого кота, якого я коли-небудь бачив. Я висмалив один незграбний залп з рушниці, але кіт не злякався. Він гаркнув ще раз, цього разу голосніше, і зник.\n\nМи зібрали речі й похмуро рушили назад до табору.", [4] = "Я пообіцяв експедиції, що наступного дня ми вирушимо полювати на пантер, оскільки їхнє хутро має значний попит у всьому Азероті. Цілком логічно, що такий попит лише зростає, адже багато вправних мисливців, капканників та торговців хутром зараз на фронті, де відважно віддають своє життя в ім'я Альянсу.", [5] = "Барвина і пан Йарс Имин дуже хотіли навчитися ефективно полювати з дворфійською рушницею. Вони залишили свою зброю в таборі, зброю з досить примітивною далекобійністю. Натомість ми з Барнілом спорядили їх найкращою вогнепальною зброєю Залізогарта.", [6] = "Того дня ми вирушили на південь, рухаючись по свіжих слідах пантери. Незабаром ми дісталися ущелини, через яку був перекинутий величезний мотузковий міст. Я не міг не згадати, як описував цей регіон Бранн, коли побачив це диво інженерії. Вважалося, що місцеві тролі були примітивною та незграбною расою, але з огляду на майстерність, з якою побудований цей міст, я не можу не визнати, що трольські будівельники — справжні майстри та зробили, здавалося б, неможливе.", [7] = "Барвині не знадобилося багато часу, щоб вистежити пантеру, і вона повела нас на південний захід. Ми йшли тихо, зі зброєю напоготові, в очікуванні своєї здобичі. Нашу увагу одразу привернув тріск гілок із сусіднього переліска. Там щось було. Одного суворого погляду на Барніла було достатньо, щоб передати мої думки. Він повільно опустив рушницю. Ця здобич була не для нас, а для наших супутників-людей. Незліченна кількість пантер вже загинула від наших куль. Ні, ця здобич — не для нас.", [8] = "І Барвина, і пан Имин стояли напоготові, спрямувавши рушниці в колючу поросль біля підніжжя дерев, що похитувалися. Полуденне сонце нещадно палило нас. Повільна цівка поту стікала по скроні Йарса, коли він зводив курок. У момент клацання густа рослинність розступилася, і велика чорна пантера — прекрасний екземпляр — вискочила на рівнину." },
    [2758] = { [1] = "Пантера бігла вздовж узлісся, а люди ні на секунду не спускали з неї погляду. Стволи їхніх рушниць повільно рухалися, залишаючись ідеально паралельними один одному. Барніл зиркнув на мене нетерплячим поглядом, але я заперечно хитнув головою. Це полювання було для людей, а не для Барніла чи мене. Йарс зробив постріл, але не влучив у пантеру. Ймовірно, він був не готовий до такої потужної віддачі.", [2] = "Рушниця різко подалася назад в його руках. Дуло пішло вбік і опинилося під рушницею Барвини. І саме в цей момент вона натиснула на спусковий гачок. Рушниця, приціл якої був незграбно спрямований на крону дерева, гучно вистрілила. З-поміж гілок закричала зграя птахів, розлітаючись навсібіч, а від дерева здійнявся клубок диму. Ми з жахом спостерігали, як величезна гілка з тріском звалилася прямо на пантеру і зламала їй хребет.", [3] = "Минали тижні, наші запаси шкур пантер і тигрів безмірно збільшувалися. Я вирішив, що настав час зосередити наші сили на серйознішій здобичі: рапторах.\n\nЛюди, хоч і були вдячні нам з Барнілом за навчання, все ж відмовилися від полювання з вогнепальною зброєю. Барвина почувалася набагато впевненішою зі своїм луком, а пан Йарс Имин ніколи не залишав табір без свого міцного арбалета.", [4] = "З першим світанком ми вирушили на південь повз руїни Ткаші. Барніл висловив занепокоєння, що ми можемо зустріти тролів племені Кровоскальпих. Я нагадав Барнілу, що Кровоскальпі були більше стурбовані знищенням своїх заклятих ворогів — племені Черепотрощителів. Зайве говорити, що Барніла це анітрохи не втішило. Я, однак, мав із собою заряджену рушницю, повну сумку пороху, і трьох смертоносних мисливців, що полегшувало будь-які побоювання щодо ворожої засідки.", [5] = "Я вистояв перед величезним пекельником на полі бою з армією Палаючого Легіону, що наступала з усіх боків. Порівняно з цим банда злих тролів здається такою ж нешкідливою, як заєць на пагорбах Дун-Морога.\n\nРуїни Ткаші ми пройшли без пригод, на велике полегшення Барніла. Ми продовжували рухатися на захід до Великого моря, оминаючи руїни Зул'Кунди на півдні. Піднявшись на високу скелю над морем, ми побачили нашого першого раптора.", [6] = "Звір навіть не помітив нашої присутності. Власне, єдиним привітанням, яке він отримав від експедиції, була куля між очей. Пан Йарс Имин щиро вигукнув \"ура!\", а Барвина схвально кивнула мені. Я переглянув рюкзак у пошуках люльки, сподіваючись насолодитися святковим куревом. Барніл почовгав на пагорб, щоб дістатися тіла раптора. Я дивився на полеглого звіра із задоволенням, яке щоразу супроводжує мене моменти великих перемог.", [7] = "Але не довго я тішився славою вбивства. Бо коли я перевів очі на горизонт, на вершині пагорба, прямо над бідним Барнілом, з'явилося кілька силуетів.\n\n\"Тікай, Барніле!\", — крикнув я. Барвина, пан Йарс Имин і я випустили залп куль, стріл і болтів над Барнілом у бік рапторів. Комусь навіть вдалось вбити одного з них.", [8] = "Наших поспішних пострілів вистачило, щоб Барнілу вдалося відірватися. Барніл стрімко спустився з пагорба й приєднався до групи. Ми кинулися в джунглі, а зграя лютих хлястохвостих рапторів не відставала ні на крок.\n\nМисливці стали здобиччю." },
    [2759] = { [1] = "Я повів групу до моря, сподіваючись, що берег послужить нам захистом від рапторів. Поспішаючи, ми зайшли занадто далеко на північ, піднявшись на особливо високий пагорб. Це була помилка. Моя провина. Ми зупинилися прямо перед урвищем, а раптори були лише за кілька кроків позаду.", [2] = "Я повільно ступив уперед, піднявши рушницю. Я привів цих відважних мисливців на смерть. І готовий був загинути сам, захищаючи їх. Хлястохвості раптори відомі своєю невблаганною жагою до крові. Вони значно переважали нас числом. Але я б собі не пробачив, якби дозволив їм убити мене та моїх товаришів, не прикінчивши спочатку кілька цих тварюк.", [3] = "Барвина і пан Йарс Имин підготували свою зброю, обступаючи мене з обох боків, спинами до моря. Барніл переможено зітхнув і вихопив сокиру. Хлястохвости майже наблизилися до нас. Їхній рівний крок сповільнився. Тепер вони стежили за своєю здобиччю, бо знали, що загнали нас у пастку.", [4] = "І тут сталося щось дивовижне. Збоку від нас ми почули виразний і страшний рев великого білого тигра. Попри свою чисельність, раптори розвернулися й розбіглися в різні боки. Ми побачили лише короткий білий спалах, коли тигр промчав повз нас і кинувся на одного з рапторів. Нам не потрібні були слова. Ми четверо водночас зрозуміли — настав час тікати.", [5] = "Ми мчали назад до табору, не сповільнюючись ні на мить. Пізніше того вечора ми тихо сиділи біля багаття, розуміючи, що наші життя врятував дивний поворот долі. Такими є ризики мисливців на велику здобич. Ми бавимося з долею до останнього. Але врешті решт для кожного з нас настане мить, коли ми зіткнемося з гострими як бритва зубами долі. Цей дворф просто радий, що ця мить не настала на зелених пагорбах Тернистої долини." },
    [281046] = { [1] = "Спогади про Велорів\r\nОповідь про родину Велорів та їхню службу Воронячому пагорбу\r\n\r\nВ усіх Східних Королівствах не було величнішої родини за Велорів. Їхні діяння заради людей, яких вони присягнули захищати, були не інакше як дивами, а їхня втрата стала втратою для всього Воронячого пагорба.\r\n\r\nЯ пишу цю оповідь, щоб відновити правду й розповісти про дивовижних Ґранта, Іру, Сільвію та Мерріка. Нехай ці записи стануть бодай малою втіхою від жалю за їхньою відсутністю.", [2] = "Меррік Велор, вартовий Темнодолу\r\n\r\nМеррік був наймолодшим сином у родині Велорів. Побачивши, як скверна насувається на його рідний край, він приєднався до Варти у відчайдушній спробі захистити своїх близьких.\r\n\r\nХоча він був найменш досвідченим у родині, Меррік швидко здобув собі ім’я серед Вартових. Він мав хист до стрільби з лука й невдовзі став одним із найстійкіших захисників Темнодолу.\r\n\r\nСвоїм особистим обов’язком він вважав безпеку доріг, пильно стежачи за дедалі ворожішими створіннями, що приходили до лісів.", [3] = "Сільвія Велор, вартова Воронячого пагорба\r\n\r\nСільвія Велор уже була місцевою героїнею, коли їй запропонували вступити до Варти. Найбільше у світі вона не терпіла пройдисвітів, які наживалися на чужому нещасті.\r\n\r\nБандити, шахраї, підбурювачі — байдуже. Сільвія карала мечем кожного, хто намагався посіяти хаос у її любому домі. Тож цілком природно, що їй довірили справжню владу, аби вона могла втілювати власне бачення справедливості.\r\n\r\nКажуть, до останнього подиху вона не полишала садиб і домівок Смерколісся. А можливо, не полишила їх і після нього.", [4] = "Іра Велор, лісова слідопитка\r\n\r\nКоли батько Іри занедужав, вона взяла на себе збір їжі та припасів у навколишніх лісах. Ресурсів там не бракувало, та шанс знайти поживу був майже таким самим, як і самому нею стати.\r\n\r\nЗ роками Іра пристосувалася до лісу й воліла проводити час серед темних дерев, а не на Воронячому пагорбі. Мандрівники, що губилися в хащах, розповідали про тінь, яка нібито відкривала їм шлях назад до дороги. Ніхто не знав напевно, хто це був, та чутки ширилися швидко.\r\n\r\nКажуть, Іра й досі блукає лісами й простягає руку допомоги тим, хто стає здобиччю місцевих звірів.", [5] = "Лорд Ґрант Велор, глава родини Велорів\r\n\r\nЛорд Ґрант, хай спочиває з миром, був взірцем найкращих чеснот Альянсу. Природжений провідник, він твердою рукою вів мешканців Воронячого пагорба до добробуту. Коли темрява почала просочуватися в ліси, саме він першим згуртував наших людей.\r\n\r\nДля лорда Ґранта не було огиднішого ворога за невмерлих. Він особисто патрулював кладовища Смерколісся, стримуючи хиткі орди мерців. Коли чудовиська завдали йому тяжкої рани, все містечко розділило його біль.\r\n\r\nЗавдяки турботі родини він повернувся до своїх обов’язків, та недуга не відступила й, здавалося, переслідувала його до кінця днів.", [6] = "Леді Кассандра Велор, любляча мати й дружина\r\n\r\nПро Кассандру відомо небагато, окрім її безмежної любові до родини. Вона виховала хоробрих дітей і була опорою сильному чоловікові, тож дехто навіть казав, що велич родини — цілковито її заслуга. Такі лестощі вона завжди з гідністю відкидала.\r\n\r\nІ навіть якщо про неї не збережеться більше жодного спогаду, нехай усі знають: усе, що вона робила, було заради її родини." },
    [281149] = { [1] = "Спогади про Велорів\r\nОповідь про родину Велорів та їхню службу Воронячому пагорбу\r\n\r\nВ усіх Східних Королівствах не було величнішої родини за Велорів. Їхні діяння заради людей, яких вони присягнули захищати, були не інакше як дивами, а їхня втрата стала втратою для всього Воронячого пагорба.\r\n\r\nЯ пишу цю оповідь, щоб відновити правду й розповісти про дивовижних Ґранта, Іру, Сільвію та Мерріка. Нехай ці записи стануть бодай малою втіхою від жалю за їхньою відсутністю.", [2] = "Меррік Велор, вартовий Темнодолу\r\n\r\nМеррік був наймолодшим сином у родині Велорів. Побачивши, як скверна насувається на його рідний край, він приєднався до Варти у відчайдушній спробі захистити своїх близьких.\r\n\r\nХоча він був найменш досвідченим у родині, Меррік швидко здобув собі ім’я серед Вартових. Він мав хист до стрільби з лука й невдовзі став одним із найстійкіших захисників Темнодолу.\r\n\r\nСвоїм особистим обов’язком він вважав безпеку доріг, пильно стежачи за дедалі ворожішими створіннями, що приходили до лісів.", [3] = "Сільвія Велор, вартова Воронячого пагорба\r\n\r\nСільвія Велор уже була місцевою героїнею, коли їй запропонували вступити до Варти. Найбільше у світі вона не терпіла пройдисвітів, які наживалися на чужому нещасті.\r\n\r\nБандити, шахраї, підбурювачі — байдуже. Сільвія карала мечем кожного, хто намагався посіяти хаос у її любому домі. Тож цілком природно, що їй довірили справжню владу, аби вона могла втілювати власне бачення справедливості.\r\n\r\nКажуть, до останнього подиху вона не полишала садиб і домівок Смерколісся. А можливо, не полишила їх і після нього.", [4] = "Іра Велор, лісова слідопитка\r\n\r\nКоли батько Іри занедужав, вона взяла на себе збір їжі та припасів у навколишніх лісах. Ресурсів там не бракувало, та шанс знайти поживу був майже таким самим, як і самому нею стати.\r\n\r\nЗ роками Іра пристосувалася до лісу й воліла проводити час серед темних дерев, а не на Воронячому пагорбі. Мандрівники, що губилися в хащах, розповідали про тінь, яка нібито відкривала їм шлях назад до дороги. Ніхто не знав напевно, хто це був, та чутки ширилися швидко.\r\n\r\nКажуть, Іра й досі блукає лісами й простягає руку допомоги тим, хто стає здобиччю місцевих звірів.", [5] = "Лорд Ґрант Велор, глава родини Велорів\r\n\r\nЛорд Ґрант, хай спочиває з миром, був взірцем найкращих чеснот Альянсу. Природжений провідник, він твердою рукою вів мешканців Воронячого пагорба до добробуту. Коли темрява почала просочуватися в ліси, саме він першим згуртував наших людей.\r\n\r\nДля лорда Ґранта не було огиднішого ворога за невмерлих. Він особисто патрулював кладовища Смерколісся, стримуючи хиткі орди мерців. Коли чудовиська завдали йому тяжкої рани, все містечко розділило його біль.\r\n\r\nЗавдяки турботі родини він повернувся до своїх обов’язків, та недуга не відступила й, здавалося, переслідувала його до кінця днів.", [6] = "Леді Кассандра Велор, любляча мати й дружина\r\n\r\nПро Кассандру відомо небагато, окрім її безмежної любові до родини. Вона виховала хоробрих дітей і була опорою сильному чоловікові, тож дехто навіть казав, що велич родини — цілковито її заслуга. Такі лестощі вона завжди з гідністю відкидала.\r\n\r\nІ навіть якщо про неї не збережеться більше жодного спогаду, нехай усі знають: усе, що вона робила, було заради її родини." },
    [2832] = { [1] = "Гуляш по-західнокрайськи\n\n3 частини жилавого м'яса грифа\n3 рила іклоштрика\n3 ока мурлока\n3 плоди окри\n\nПомішати та довести до кипіння. Тушкувати на повільному вогні принаймні дві години та подавати на стіл." },
    [2837] = { [1] = "Люба Іветт,\n\nя доручаю цей лист нашому найшвидшому бігуну. Я молюся, щоб він зміг знайти шлях крізь війська, що оточують нас. І я молюся, щоб ти прочитала мої слова, бо вони будуть останніми, що ти почуєш від мене.\n\nМоя єдина втіха у ці темні дні — це полегшення, яке я відчуваю, знаючи, що ти вільна від моєї долі.", [2] = "Я боюся, що мій батько допустив серйозну помилку, коли вирішив залишитися і захищати наш дім. Сили Скари вирують на Тірісфальському переліссі, і хоча ми добре укріплені й добре забезпечені, після зради мого брата Девліна нам не вистачає сил і чисельності, щоб протистояти постійним штурмам.\n\nЯкщо ти отримаєш цей лист, то знай, що Девлін — зрадник.", [3] = "Він зневірився і шукав шляху уникнення нашого нещастя, і тим самим уклав договір зі Скарою. Я не знаю, яка ціна була обіцяна йому за зраду, але я впевнений, що це було прикрашено брехнею.\n\nЯкщо ти побачиш мого брата, то тікай від нього. Він — диявол. Кілька ночей тому він вбив двох наших вартових, чим дозволив невеликій групі Скари прорватися туди, де спало ще багато наших.", [4] = "Їхня засідка була жорстокою. Вони перебили третину з нас, перш ніж ми змогли відбитися. Зараз у нас ледве вистачає людей, щоб спостерігати за своїми кордонами. Це питання часу, поки наша стомлена охорона впаде й Скара піде у наступ.\n\nІ хоч я бачив обличчя Девліна серед зневірених людей і змарнілих прибічників Скари в ту кляту ніч, він вислизнув, перш ніж я встиг його спіймати. Він може бути мертвим, а може й досі живим агентом Скари.\n\nТак чи інакше, він чудовисько.", [5] = "Девлін попередив нас, що якщо ми спробуємо зіткнутися зі Скарою, то ми — приречені. Він це сказав, коли вони вперше увійшли на Тірісфальське перелісся, задовго до того, як наш дім оточили. Можливо, таким чином він прохав, щоб ми пішли, а, можливо, просто зловтішався.\n\nМотиви Девліна завжди було важко зрозуміти. Він з дитинства був для нас загадкою.", [6] = "Але він мав рацію. Ми приречені. Сімейна лінія Аґамандів обірветься. Хоча я все ще живий, я знаю, що скоро помру.\n\nЯ не боюся і не шкодую, що залишився з родиною. Але мої останні думки будуть про тебе.\n\nЖиви далі, моя кохана Іветт, а я віднайду спокій,\n— Турман" },
    [2885] = { [1] = "Поширюйте інформацію так, як вважаєте за потрібне.\n\nТірісфальське регіональне командування\nКапітан Мелрач\nКапітан Вачон\nКапітан Перрін\n\nЗа наказом верховного повелителя.\n\nКапітане Перрін, зміцніть свої позиції біля південно-західної вежі (як зазначено). Додаткові припаси будуть надіслані пізніше. Тим часом потрібні матеріали можна пошукати на навколишніх фермах. Також слід проводити подальшу розвідку та", [2] = "збирати інформацію про організацію невмерлих в Бріллі.\n\nКапітане Вачон, схоже, що невмерлі збільшили присутність біля північної вежі. З цим опором необхідно швидко і рішуче боротися.\n\nКапітане Мелрач, є занепокоєння щодо рівня організації невмерлих біля кордонів Зачумлених земель. Найближчими тижнями на вашу позицію буде направлено нову групу людей.\n\nСлава під Світлом" },
    [2956] = { [1] = "Від Бароса Алекстона,\nМіського архітектора\nШтормовій\n\nВаша Величносте,\n\nІснує багато причин, чому я вважаю за потрібне скласти та представити звіт про останні справи \"Братства Непокірних\" та їхню діяльність по всьому королівству.\n\nДля перспективи, я почну з невеликого екскурсу в історію. Як ви, можливо, знаєте або не знаєте, моя служба Штормовію почалася з членства в Гільдії Каменярів. За роки роботи ми завершили відбудову", [2] = "Штормовію, і на той час рахунки Гільдії Каменярів, гонорари та зарплати залишилися неоплаченими та не обговорюваними.\n\nНа той час Едвін Ван-Кліф був обраний головою Гільдії Каменярів і виступив із заявою, вимагаючи відшкодування за нашу роботу. У відповідь Дім вельмож Штормовію наказав розпустити Гільдію Каменярів, що, зрозуміло, розлютило Ван-Кліфа. Очоливши бунт, Ван-Кліф вивів каменярів з міста.\n\nПерш ніж продовжити, я б хотів розповісти про інші події, що відбулися водночас", [3] = "в ті ж часи, до яких я хотів би привернути вашу увагу.\n\nПо перше, саме в цей час мені запропонували посаду міського архітектора, за умови, що я не приєднаюся до Ван-Кліфа. Через певні ідеологічні розбіжності я вирішив залишитися в Штормовії.\n\nПід час заворушень лейтенанта і найбільш довіреного помічника Ван-Кліфа, Базіла Тредда, схопили й ув'язнили. В очікуванні суду та допитів про Тредда майже забули в Штормовійській в'язниці.\n\nПовернімось до Ван-Кліфа. Після того, як він вивів залишки", [4] = "Каменярів зі Штормовію, він скористався відносно вразливим положенням Західного краю і використав свою значну робочу силу, щоб вигнати багатьох фермерів і захопити кілька золотих копалень.\n\nСкориставшись наявними в його розпорядженні ресурсами, Ван-Кліф розробив план відплати уряду Штормовію.\n\nЦя інформація стала відома лише нещодавно завдяки допомозі {стать:посланника:посланниці} цього документа, {стать:який відіграв:яка відіграла} важливу роль у пролитті світла на цю величезну змову." },
    [3017] = { [1] = "Лорд Бетор Кригозлам,\n\nЗгідно з вашими вказівками, надсилаю вам агента, якого ви шукали. {стать:Він і приніс:Вона й принесла} цей лист.\n\nЦя особа показала себе надійною та здатною виконувати накази, показавши себе в бою з силами Скари, і є моїм вибором для вашої місії.\n\nНехай Її панування буде безмежним,\n-війт Севрен" },
    [3117] = { [1] = "День 1\n\nМій танк розбито, але я знаю, що хіронова руда десь у цих пагорбах. Я наказав Молотоногу залишитися і стежити за нашими танками.\n\nТепер продовжу пошуки сам. Якщо я не повернусь — в щоденнику мої останні слова.\n\n— Бурон Гілдельв, пілот\nПарова бригада Залізогарту.", [2] = "День 2\n\nМої пошуки тривають, руди все ще немає. Цікаво, чи не жартував Камнелад про чутки за цю руду. Якщо це так, то коли я повернуся до Сховища Сталешквара, я проломлю йому череп!\n\nСьогодні вночі, коли я розкладав свій табір, я почув гарчання, яке відлунням прокотилося через каньйони.\n\nЦе не вовк. Це може бути ведмідь.", [3] = "День 3\n\nЩось гарчало всю ніч і переслідувало мене весь день, відволікаючи від пошуків руди. Здається, мене переслідує ведмідь!\n\nСподіваюся, він підійде близько. І я встромлю йому кирку в голову!", [4] = "День 4\n\nМої запаси закінчуються. У мене все ще багато їжі, але я не планував так довго перебувати вдалині від мого танка і взяв з собою лише дві бочки елю.\n\nЯ не спав останні дві ночі, слухаючи це прокляте гарчання і майже осушив обидві бочки!\n\nЗавтра мені доведеться повернутися до Молотонога і наших парових танків. Я не хочу загубитися тут без випивки.", [5] = "День 6\n\nКлятий ведмідь дістався до мене! Він накинувся на мене ззаду опівдні з диким ревом.\n\nЯ б відчув його, якби він напав з боку вітру — його сморід був просто жахливий! Від одного лише смороду його брудної шерсті та гнилого дихання я ледь не знепритомнів!\n\nЯ відштовхнув його, але він добряче погриз мені ногу. Тепер я не можу рухатися, мій ель закінчився, а руду я так і не знайшов. Трясця!", [6] = "День 6\n\nВедмідь ще не повернувся — мабуть, я його добряче відлупцював! Але я все ще чую його гарчання. Здається, він чекає на мою смерть!\n\nХто б не отримав цю книгу, я прошу тебе. Вбий цього клятого ведмедя. Вбий його і віднеси цю книгу моєму другові Молотоногу. Він захоче дізнатися, що зі мною сталося.\n\nІ візьми мої обладунки. Вони тобі знадобляться в бою проти старого Свербикігтя!" },
    [3248] = { [1] = "Вітаю вас, Елло Чорнобрив, мер Темноділа. Боюся, у мене є новини для вашого міста. Серйозні новини.\n\nБачите, я творець. Я обдурив пред'явника цієї записки, щоб {стать:він допоміг:вона допомогла} мені у моєму останньому, найжахливішому творінні — монстра з плоті, кісток і покрученого металу! Поки ви читаєте ці рядки, він перебуває поруч з моїм скромним житлом, скрегоче зубами та чекає мого слова, щоб піти вбивати й трощити все на своєму шляху.\n\nІ незабаром ви відчуєте це на собі.\n\n-Бальзамувальник" },
    [3252] = { [1] = "Звіт про місію смертоловів\n\nАгенти: Рейна Йорік, Квінн Йорік, Ерланд МакКрі\n\nОсновне завдання: провести розвідку в північній частині Срібнохвою та визначити рівень загрози з боку диких тварин і Скари.", [2] = "Агенти розпочали розвідку місцевості, виявивши значну присутність воргів. Рекомендую відправити мисливські загони, щоб зменшити цю загрозу.\n\nНа фермі, під назвою Мертве поле, виявлено невмерлих гнолів. Їхня ціль невідома, хоча їхні пересування та рівень готовності вказують на неминучі військові дії. За час спостереження серед гнолів не було виявлено жодного явного лідера. Припускаю, що вони чекають на прибуття керівництва або підкріплення.", [3] = "Продовжуючи розвідку, наші агенти затримались на фермі Айвара. Сам Івар, більшість членів його сім'ї та робітники піддалися Скарі та стали її прислужниками.\n\nНа наших агентів напали й хоч їм вдалося перемогти нападників, вони зазнали серйозних поранень, особливо агент Квінн.", [4] = "У старому будинку Айвара була зайнята оборонна позиція, і поки Рейна стояла на варті, чекаючи майбутніх атак, Ерланд продовжував розвідувальну місію.\n\nПотім Ерланда оточили ворги в північному саду, йому вдалося врятуватися лише завдяки допомозі іншого агента відречених. Цей агент і приніс даний звіт.", [5] = "Тут слід зазначити, що цей посланець відіграв важливу роль не лише в успіху нашої місії, але й у перемозі над Айваром Нечистим, порятунку Ерланда та доставленні цього звіту.\n\nМи висловлюємо нашу подяку і рекомендуємо командуванню відзначити цю особу нагородами, які б відповідали її гідній поведінці на полі бою.\n\n— Смертоловка Рейна Йорік,\nкомандир операції" },
    [3255] = { [1] = "Вивчаючи різних скам'янілих істот, я дійшов висновку, що в давнину водами озера Лордамер прокотилася велика чума. Що її спричинило? Напевно, ми ніколи не дізнаємось. Але, судячи з насиченої концентрації решток, розподілених по дну озера, рівень забруднення був надзвичайно високим.", [2] = "Намагаючись розкрити минуле, я почав вивчати істот сьогодення в надії знайти загублений ключ до цієї таємниці. Озерні тайноходці та озерні підкрадачі — стародавні звірі, які мешкають на островах в центрі озера Лордамер. На них росте мох, форми якого нагадують деякі скам'янілості. Потрібно провести більше досліджень, перш ніж я зможу припустити, що тут є якийсь зв'язок.", [3] = "Намагаючись зібрати зразки моху, я натрапив на місце кривавої битви. Плем'я мурлоків Злобного Плавника потрапило в засідку банди гнолів. На полі бою лежали трупи як гноллів, так і мурлоків. Проходячи повз понівечене тіло мурлока, я помітив дивну затверділу пухлину, що стирчала з рани. Коли я почав вивчати її, стало зрозуміло, що пухлина має схожі властивості з мохом, який я збирав. На жаль, я не знайшов інших пухлин, окрім цієї." },
    [3518] = { [1] = "Вітаю вас, майстре,\n\nПробачте мені за те, як вам доставили це повідомлення. Мої тіньові маги в Альтераці зосереджені на поставленому завданні, через це мені довелося використати чужого гінця, завербованого нашими новими \"союзниками\", щоб доставити вам цей звіт. Але я зашифрував його нашим таємним шифром. Ці селюки не зрозуміють жодного слова.", [2] = "Наші плани просуваються успішно. Як я вже говорив, ми уклали союз з групою людей, які називають себе Синдикатом. Його лідери колись були вельможами Альтераку і зараз вони прагнуть знову тут панувати.\n\nТому вони уклали з нами угоду. Угоду, про яку вони пошкодують.", [3] = "Сьогодні Синдикат контролює лише невелику частину земель, але вони добре знають ці місця і зібрали достатню кількість воїнів для виконання майбутніх завдань. За належного керівництва, я впевнений, що незабаром Синдикат знову правитиме Альтераком.\n\nКрім того, ми переконали Синдикат піти на місто Стромварт, яке розташоване неподалік, на височині Араті. Це місто є полем битви між нашими військами, ограми та людьми Стромварту, але ми віримо, що якщо робити все обережно, ми заволодіємо цим колись великим містом.", [4] = "І коли ми зробимо це, розпочнеться наступний етап нашого плану. Після поєднання зусиль і закріплення в цьому регіоні, ми зможемо підготувати шлях для Третьої армії.\n\nСкоро лорди Легіону винагородять нас за наші труди, знову проливши вогняний дощ з небес!", [5] = "Рада вчинила мудро, призначивши вас головою Арґуського Пробудження, маршалом їхніх стратегій на землях людей та дворфів. І для мене велика честь служити провідником вашої долі в Альтераці.\n\nВ ім'я Сарґераса,\n\nНаґаз,\nієрофант Арґуса" },
    [3601] = { [1] = "Валік,\nохороняй раба до нашого повернення. Тримати ЙОГО тут небезпечно. Ми перевеземо його на північ, якомога далі від будь-якої можливості бути поміченими.\n\nВони тварини, але жорстокі тварини — якщо їх буде достатньо, у нас будуть причини для занепокоєння. Краще взагалі приховати будь-які сліди, що могли б їх спровокувати. Останнє, що ми хочемо дати їм — це привід згуртуватися і напасти на нас." },
    [3657] = { [1] = "Міський реєстр Гіллзбраду\n\nМи, жителі Гіллзбраду, урочисто присягаємо у своїй вірі та відданості Альянсу, який славиться великими монархами, королем Маґні Бронзобородим з Залізогарту та королем Андуїном Рінном зі Штормовію.\n\nВ цьому документі знаходиться міський реєстр для управління цим славним містом на підніжжі великих Альтерацьких гір, а також для обліку тих, хто сплатив податки своїм королям та великому і могутньому Альянсу.", [2] = "Війт Резерфорд Шкваростін\nУсі борги сплачено.\n\nКоваль Ейвері Веррінгтан\nУсі борги сплачено.\n\nКлерк Горацій Білокінь\nУсі борги сплачено.\n\nРадник Ґілліс\nУсі борги сплачено.\n\nРадник Гукс\nУсі борги сплачено.\n\nФермер Ґетц\nУсі борги сплачено.\n\nФермер Рей\nБорг не сплачено. Обіцяний платіж сільськогосподарськими товарами після збору врожаю.\n\nФермер Ліон\nБорг не сплачено. Виселений з землі.", [3] = "Фермерка Калаба\nБорг не сплачено. Обіцяний платіж сільськогосподарськими товарами після збору врожаю.\n\nМістянин Вілкс\nУсі борги сплачено.\n\nМістянин Боноан\nУсі борги сплачено.\n\nШахтар Велті\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні.\n\nШахтар Сідні\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні.\n\nШахтар Гакетт\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні.", [4] = "Шахтар Орвелл\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні.\n\nШахтар Фіцджеральд\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні.\n\nМістянин Нідранд\nУсі борги сплачено.\n\nМістянка Мей\nУсі борги сплачено.\n\nДесятник Бондс\nБорг не сплачено. Виплата після наступного постачання руди з Лазурової копальні." },
    [3711] = { [1] = "Кеґан Темнар, ватажок невеликої групи невмерлих, що прийшли сюди у пошуках притулку від своїх \"побратимів\", спростував наші уявлення про таких, як він. Можливо, його шкіра гниє, а кров давно перестала текти в жилах, але він поводиться дуже благородно і, здається, турбується більше про безпеку своїх земляків, ніж про свою власну.\n\nЧесно кажучи, в ньому більше людяності, ніж в деяких людях, що мене оточують.", [10] = "Кров, що пролилася біля кулона з кривавим каменем, повільно рухалася до прикраси, ніби якась сила тяжіння почала притягувати її до кривавого каменю. Кров, яка торкалася кулона, ніби зникала, а червоний колір каменя ставав все насиченішим, поки вбирав все більше моєї крові.", [11] = "Побачивши це, я відчула полегшення в голові, можливо, від недавньої травми (хоча я не вірила, що втратила стільки крові), а можливо, тому, що нарешті, після стількох розчарувань, я відкрила одну з властивостей кривавого каменю. Я потягнулася за своїм робочим стільцем і сіла, замислившись. Думки та питання кружляли в моїй голові, викликаючи запаморочення і погрожуючи звалити мене з ніг.\n\nЧи кривавий камінь п'є кров? Чи жадає він крові? Чи притягує він кров?", [12] = "Або ж, кривавий камінь зроблений з крові? І якщо так, то з чиєї крові? Моєї? Крові якоїсь людини? Якоїсь тварини?\n\nА може, кривавий камінь — це кров якоїсь невідомої істоти, тієї самої, яку Кеґан водночас і боявся, і шанував, коли вручав мені свій кулон.\n\nЦе питання, на яке потрібно знайти відповідь. Це ключ.", [13] = "В мені знову запалала цікавість і я поринула у свої експерименти. Цього разу я не робила жодних припущень, методично виконуючи кожен дослід, який був у моєму розпорядженні. Це значно збільшило необхідні зусилля, але в мене було більше шансів зробити відкриття.\n\nІ, хоча в мене невелика лабораторія, і в мене немає підлеглих, які могли б мені допомогти, я виявила ще одну цікаву властивість кривавого каменю...", [14] = "Крім крові, в камені є сили стихій, злиті в єдине ціле. Вогонь, вода, грім і камінь змішані з кров'ю (але знову ж таки, чиєю кров'ю?) і хоч ця суміш зовні інертна, всі ці сили, здається, вирують всередині одна проти одної. Так багато запитань з'явилось до цього дивовижного і лиховісного матеріалу.", [15] = "Але щоб відповісти на ці питання, необхідно провести більше досліджень і експериментів з кулоном і я боюся, що Лордамерський ізоляційний табір не зможе зібрати достатньо людей і обладнання для виконання цих досліджень. Тому я відправила кулон з кривавим каменем кур'єром в Даларан з конкретними інструкціями про те, як його перевірити, щоб вони не повторювали моїх попередніх розчарувань.", [16] = "Поки я чекала на результати цих аналізів, я проводила час, розмовляючи з Кеґаном. Хоча я постійно випитувала його про те, що він знає про криваві камені, він ніколи не розповідав мені більше, ніж того дня, коли подарував мені свій кулон. Та він не часто говорив про час, проведений серед так званих \"Відречених\" — так він називає свій клан невмерлих.", [17] = "Зате Кеґан завжди любив говорити на інші теми, зокрема, про своє дитинство в Лордероні до його падіння.\n\nВін досі дуже любить це втрачене королівство, хоч воно вже зруйноване і мертве.\n\nМоя прихильність до Кеґана додала мені терпіння, поки я чекала на результати моїх дослідів.", [18] = "Але після кількох тижнів відсутності новин моє терпіння увірвалося і після подальших запитів до Даларана я дізналася, що кривавий камінь так і не потрапив до моїх колег. Мій кур'єр якимось чином загубився в дорозі та разом з ним було втрачено кулон з кривавим каменем!\n\nЦе сумна новина, бо хоч у Кеґана і його прихильників все ще є зразки кривавого каменю, з якими ми можемо експериментувати, я боюся, що кулон може потрапити в погані руки.", [19] = "Я відправила ще одного гінця до Даларана і дізналась, що навіть зараз вони шукають кулон у руїнах біля нашої захисної сфери.\n\nСподіваюсь, ми не спізнилися.", [2] = "Але чому я про це згадую? Я роблю це для того, щоб ви повірили тому, про що я збираюся написати — словам, які прозвучали з вуст Кеґана. І я сподіваюся, що мої колеги, прочитавши цей журнал, зрозуміють, чому я вірю в те, що він сказав:\n\n\"Залишки Старих Богів все ще жевріють в глибоких розломах цього світу. Нові сили прагнуть приборкати цю древню міць, і ті, хто зможе це зробити, володітимуть страшною зброєю проти своїх ворогів\".", [3] = "Саме це промовив Кеґан, передаючи мені свій кулон з кривавим каменем і, коли він це робив, в його очах було видно страх, а може навіть побожність. І коли його руки зустрілися з моїми, він забарився, ніби не хотів віддавати кулон. Мене охопила відраза, але я до тепер не знаю, чи то від його мертвої плоті на моїй руці, чи то від самого кулона.\n\nБо я відчула у ньому силу. Глибоку, приховану, ненаситну силу. Та жагу до свободи.", [4] = "Хоча мої колеги в Даларані бояться вивчати криваві камені, які Кеґан і його прихильники привезли з собою, натомість помістивши чотирьох біженців в карантин і залишвши криваві камені у них, щирість Кеґана зобов'язала мене дослідити його кулон з кривавим каменем.", [5] = "Я сподіваюся довести своїм колегам, що цей камінь дійсно має магічні властивості, і якщо ми, чаклуни Даларана, не хочемо використовувати силу кривавих каменів, ми повинні принаймні вивчити їхні властивості, оскільки наші вороги можуть одного дня використати їх проти нас.\n\nТак почалися мої дослідження.", [6] = "Я почала свої дослідження з припущення, що кривавий камінь — це різновид гірської породи, як кварц або обсидіан. Тож я розпочала серію експериментів, щоб визначити: які мінерали містяться в кривавому камені, які сили були застосовані для отримання такого кольору і твердості, а також інших властивостей, притаманних гірським породам і руді. Але кулон з кривавого каменю, на моє розчарування, не реагував на мої експерименти так, як реагувала б звичайна руда.", [7] = "Насправді він часто поводився зовсім інакше, ніж я очікувала! Здавалося, ніби кулон навмисне заважав моїм експериментам.\n\nНіби він був живим і в нього був розум.\n\nРозлючена, але не зневірена, я перемкнулася з припущення, що кулон був інертним шматком каменю, на припущення, що це жива істота.\n\nАле я знову зазнала невдачі.", [8] = "Жодне з моїх наступних досліджень не розкрило жодних таємниць походження кривавого каменю. На той час єдине, що я розгадала, було те, що кривавий камінь не був ні живим, ні мертвим!\n\nАле саме тоді, на межі провалу, було зроблено прорив. У моєму останньому досліді я використала склянку, край якої був відколотий, завдяки цьому на краю утворився маленький нерівний проміжок. Коли дослід закінчився черговою невдачею, я пішла прибирати свій робочий стіл і порізалася об склянку.", [9] = "Поріз був неглибоким, проте, сильно кровив. Перш ніж я перев'язала поранений палець бинтом, значна частина моєї крові пролилася на робочий стіл.\n\nІ коли я прибирала цей безлад, я помітила дивну річ..." },
    [3718] = { [1] = "Л. П. віддав наказ посилити агресію проти бовдурів з Альянсу. Нижче наведено список матеріалів, необхідних для важливої місії проти Південнобережжя:\n\nТижневий пайок для 20 осіб\n20 чорних нічних костюмів\n20 пар нового взуття\n25 нових мечів\n30 метальних ножів\n20 чорних масок\n10 флаконів запальної олії\n50 доз паралітичної отрути\n5 викрадених уніформ вартових Південнобережжя, якщо є\n100 срібних монет\n\n--Барон В.\nКвартирмейстер" },
    [3899] = { [1] = "ЛЕГЕНДИ ТРОЛІВ, ТОМ III\nКамінь Припливів\n\nЗа авторством\nАрхімага Ансірема Рунописа\nДаларан\n\nВСТУП\n\nДревня імперія Ґурубаші була джерелом багатьох легенд, що захоплювали та інтригували, і які, без сумніву, ґрунтуються на пильних спостереженнях за живою природою, оскільки дослідження їхніх вірувань та традицій вказують на велику шану до їхнього природного середовища.\n\nХоча я заглибився в багато", [10] = "а володар Припливів згасав. З кожним припливом і відпливом він ставав все менш схожим на себе, втрачаючи свою тілесну форму, то з'являючись, то зникаючи, аж поки в останні дні життя не прийшов на пляж, де вперше знайшов камінь і не зайшов у море, де й зник назавжди.\n\nЧерез покоління камінь Припливів прибило до берегів Тернистої долини та був обраний інший Володар Припливів — троль, який приніс камінь в", [11] = "Зул'Ґуруб. Це тривало багатьох поколінь: камінь з'являвся разом з припливом, а потім Володар Припливів відпливав у море.\n\n\nВ наш час існує багато згадок про появу каменя Припливів, але чому об'єкт такої сили з'являється з такою регулярністю, і хто за цим стоїть, залишається загадкою.", [2] = "аспектів їхнього поклоніння зміям в попередніх частинах цього дослідження, я пропоную тут розглянути цікаві та унікальні стосунки тролів з морем.\n\n\nВЕЛИКЕ МОРЕ\n\nІмперія Ґурубаші була з трьох боків оточена морем, тож не дивно, що вода посідала важливе місце в житті їхнього суспільства. Тролі могли контролювати території своєї великої імперії в джунглях, а от море їм не піддавалось. Неосяжні та безкрайні води не піддавались ніякому контролю, тож", [3] = "не дивно, що могутніх тролів бентежив такий сусід.\n\nТут слід зазначити, що нещодавні відкриття, схоже, свідчать про те, що тролі мало цікавляться дослідженням земель за Великим морем. Хоча племена тролів зустрічаються вздовж і впоперек Азероту, Каз-Модану та Лордерону, у нещодавно відкритих землях Калімдору або на островах у Південних морях не було знайдено жодних ознак їхньої цивілізації. Чи свідчить це про небажання", [4] = "тролів покидати свої земні володіння, чи про їхнє невміння розвивати технології, необхідні для такої подорожі, потребує подальших досліджень і аналізу, які виходять за рамки моєї статті.\n\nАле навряд чи можна ігнорувати таку велику кількість знахідок в руїнах тролів у Тернистій долині, показують раніше невідомий і не задокументований аспект їхніх стосунків з морем.\n\nКАМІНЬ ПРИПЛИВІВ\n\nНещодавні знахідки під час досліджень", [5] = "руїн тролів у Тернистій долині дозволили відшукати згадки про об'єкт, відомий як \"камінь Припливів\". Складаючи до купи різні фрагменти легенд про тролів, можна отримати досить повне уявлення про камінь та його значення для стародавньої імперії Ґурубаші.\n\nСхоже, що камінь Припливів дозволяв своєму власникові контролювати воду в різних її проявах: річки, дощ і власне припливи. Керуючись легендами, пов'язаними з використанням каменя Припливів, я припустив, що насправді він", [6] = "є проявом фізичної сили водоповелителя, могутнього елементаля морів. Як і чому такий об'єкт вийшов з-під контролю водоповелителя та потрапив до рук тролів — це ще одне питання, відповідь на яке мені поки що не вдалося дізнатися.\n\n\nВОЛОДАР ПРИПЛИВІВ\n\nПодібно самим припливам, камінь Припливів з'являвся у світі тролів і зникав з нього, ніколи не перебуваючи в руках тролів довше одного покоління.", [7] = "У легендах тролів розповідається, що вперше камінь Припливів потрапив до імперії Ґурубаші, коли його знайшов воїн-троль, що блукав узбережжям Тернистої долини. Він натрапив на таємничий блакитний камінь, всередині якого плавали та перетікали молочно-білі пасма. Зацікавившись каменем, воїн взяв його з собою і продовжив свою подорож.\n\nЗа кілька місяців він виявив, що завдяки каменю він може контролювати воду. Він міг викликати", [8] = "водяних елементалів, істот, що повністю складаються з води, що раніше вдавалося лише могутнім магам Кірін-Тору.\n\nВоїн вирушив в Зул'Ґуруб, в саме серце імперії, щоб продемонструвати імператору свої незвичайні здібності. Він легко зацікавив придворну аудієнцію після того, як продемонстрував свої здібності в столиці імперії. Його здібності легко вразили імператора Ґурубаші, який одразу ж надав йому почесне місце при дворі, назвавши воїна \"Володарем Припливів\", а його старе ім'я", [9] = "було забуто.\n\nПротягом багатьох років Володар Припливів служив імперії Ґурубаші, викликаючи своїх підвладних елементалів на битви та керуючи потоками води в Тернистій долині для потреб імперії. Але з роками він став більш відлюдькуватим, надовго залишаючи двір.\n\nВін приховував свою таємницю від допитливих очей придворних. Здібності, даровані йому каменем Припливів, супроводжувалися прокляттям. Роки йшли," },
    [3921] = { [1] = "Накази Кривавого вітрила\n\nЧитайте уважно, мої любі, іншого такого вдалого шансу напасти на Грабіжну Бухту у нас не буде.\n\nЯ відправив старого Данкена на розвідку на північ і наказав йому чекати сигналу.\n\n\"Дівоча вдача\" кине якір біля південного мису, щоб поповнити запаси. Наш коротун, капітан Море-по-коліно, має підготувати команду, щоб підняти на борт усю награбовану здобич. А це одоробло, Брут, впорається зі всім іншим.", [2] = "Я хочу, щоб капітан Кілетяг підвів \"Бистрину\" до берега з південного сходу. Ми відправимо його команду суходолом, коли дамо сигнал.\n\nЦей здоровань, Солоне Копито, може повести інших в атаку. На Ревілґазі та Морському Розі я ставлю чорну мітку. Хоч на дно морське їх відправляйте, мені байдуже.\n\nВи, хлопці, відповідальні за порятунок усього, що може бути корисним для нашого з Ван-Кліфом проєкту в Мертвих копальнях.", [3] = "Я дам наказ Сталевій Латці стріляти з гармат. Артилерійський обстріл не дасть жодному кораблю Чорноводдя покинути порт або увійти в нього.\n\nПісля того, як \"Багряна вуаль\" розрядить гармати, я підведу її до \"Бистрини\" для підтримки та забезпечу резервами, якщо знадобиться.\n\nПісля того, як Солоне Копито і його хлопці обстріляють місто та вся команда буде на палубі, ми відпливемо і ще раз обстріляємо Бухту з Дикого узбережжя для повної впевненості.\n\n— Командувач флоту Фіраллон" },
    [4100] = { [1] = "Втеча від Занзіла на тому гнилому човні здавалася мудрим рішенням, але я починаю думати, що померти було б краще.\n\nМені здавалося, ніби мені пощастило, що предки дозволили мені втекти від свого гніву. Але тепер мені цікаво, якої мудрості я набуду, якщо переживу своє ув'язнення." },
    [4101] = { [1] = "Звір, що панує на цьому острові, справді страшенно могутній. Інші істоти тремтять перед ним: як небогриві горили, так і ягуери. Навіть зараз я чую його ревіння, і воно змушує мене здригатися.\n\nЦі істоти, безсумнівно, зупинять будь-кого, хто прийде на острів. Я маю вірити у своїх предків." },
    [4102] = { [1] = "Я сумую за своїм племенем і за своїм домом. Я сумую за вітром відкритих рівнин та заходом сонця над Громовим Бескидом, а натомість терплю жар цих джунглів.\n\nЯ бачу океанську воду неподалік від себе, але вона не охолоджує моє тіло і не заспокоює мою вдачу. Вона лише нагадує мені про моє ув'язнення." },
    [4429] = { [1] = "Недолугі дурні!\n\nЯ наказав зруйнувати обидва мости. А що ви, простодушні бандюги, робите? Ви виконуєте лише половину роботи та сповіщаєте весь Альянс про наші наміри. Дурні, кажу ж!\n\nУ вас є останній шанс виправити все, що наробили. У нас є запас вибухівки на нагір'ї Араті, неподалік мосту.\n\nЗакінчіть справу, якщо ви цінуєте свої нікчемні життя!\n\n--Кам Темнолют" },
    [4432] = { [1] = "Дун-Модр із Заболоття\n\nМоя люба Саро,\n\nЄ дуже переконливі ознаки того, що за кілька днів ми перейдемо до спостереження за віадуком Тандола. Тоді я не зможу писати тобі. Мене бентежить потреба написати кілька рядків, які ти побачиш лише коли мене не стане.", [2] = "Наше завдання може тривати кілька днів і бути як простим і приємним, так і важкою сутичкою, що принесе мені смерть. Я готовий загинути на полі бою за Альянс, якщо буде потрібно.\n\nУ мене немає жодних побоювань чи браку впевненості щодо цілей, заради яких я тут, тож моя мужність не відступає і не слабшає.", [3] = "Я знаю, як сильно королівство Залізогарт покладається на тріумф Альянсу, і який великий борг ми маємо перед тими, хто пройшов до нас через кров і страждання великих воєн. Тож я готовий, абсолютно готовий віддати все що маю, щоб допомогти зберегти цей Альянс і сплатити цей борг.", [4] = "Саро, моя любов до тебе безсмертна, вона, здається, зв'язує мене могутніми ланцюгами, які ніщо, крім всемогутності, не може розірвати, і моя любов до королівства накриває мене, як сильний вітер, і нестримно несе мене зі всіма цими ланцюгами на поле бою.", [5] = "Спогади про всі блаженні моменти, які я провів з тобою, переповнюють мене, і я відчуваю глибоку вдячність Світлу і тобі за те, що я насолоджувався цим так довго, і як важко мені відмовитися від цього і спалити дотла сподівання на майбутні роки, коли ми ще могли б жити й любити разом і бачити, як наші сини стають благородними дворфами.", [6] = "Я знаю, що маю небагато дрібних претензій до Божого Провидіння, але щось шепоче мені — можливо, це лунає молитва мого маленького Едгара — щоб я повернувся до своїх близьких неушкодженим. Якщо я не повернусь, моя люба Саро, я ніколи не забуду, як сильно люблю тебе, і коли мій останній подих вислизатиме від мене на полі бою, я прошепочу твоє ім'я.\n\nПрости мої численні провини та біль, який я спричинив. Яким легковажним, яким дурним я часто був.", [7] = "З яким задоволенням я б змив своїми сльозами кожну маленьку пляму на твоєму щасті й боровся б проти усього лиха цього світу, щоб захистити тебе і моїх дорогих дітей від біди.\n\nАле не можу.\n\nЯ мушу спостерігати за тобою з підсвітньої крутоверті й ширяти біля тебе, поки ти сам на сам поборюєш бурю зі своїм дорогоцінним маленьким тягарем, і чекати з сумним терпінням, допоки ми зустрінемось, щоб більше ніколи не розлучатися.", [8] = "Але о Саро, якщо померлі можуть повернутися в Азерот і непоміченими літати навколо тих, кого вони люблять, я завжди буду поруч з тобою в найрадісніший день і в найтемнішу ніч, серед твоїх найщасливіших моментів і в найпохмуріші години завжди. І якщо ти відчуєш м'який вітерець на твоїх щоках, це буде мій подих, і коли прохолодне повітря овіє твою пульсуючу скроню, це буде мій дух, що пройде повз.\n\nСаро, не оплакуй мене мертвого, краще думай, що я пішов, і чекай на мене, бо ми зустрінемося знову.\n\n--Саллі" },
    [4514] = { [1] = "Моєму шановному королю:\n\nНе личить дружині простого солдата ставити під сумнів дії таких великих лідерів, як ви. Битви, що точаться на наших землях, ведуться за те, щоб зберегти чудове життя, яке ми знаємо й любимо, від прохолодних вод озера Лох-Модан до бурхливих засніжених вершин Дун-Морогу.", [2] = "Але яку ціну ми сплачуємо за ці війни, які ведемо в ім'я збереження? Після смерті якого загиблого солдата ми усвідомлюємо, що саме те життя, яке ми прагнемо врятувати, вислизає від нас на полі бою?\n\nПід скільки мечів і сокир ми повинні кинути наше майбутнє? Під скількома футами розмоклої землі ми повинні поховати наше минуле?", [3] = "Не личить дружині простого солдата ставити такі питання.\n\nАле зараз я пишу вам як вдова простого солдата. Мій чоловік, можливо, був для вас одним солдатом з тисяч. Для мене він був великим Саллі Баллу, батьком моїх дітей і моїм єдиним супутником у цьому житті.\n\nПробачте, якщо мої запитання до вас, о великий лідере, здаються недоречними. Але мертві не можуть запитати цього за себе...\n\nВаша вірна піддана,\nСара Баллу" },
    [4649] = { [1] = "Зірка Ксіл'єх\n\nЗіркою володіє Ґрел'борґ Ниций. Це жадібний огр, який проводить свої дні в Альтерацьких горах, що в руїнах Альтерака, сподіваючись знайти якісь дрібнички. Більшість його колекції, це сміття, але одна річ — зірка Ксіл'єх, має цінні властивості.", [2] = "Рука Даґуна\n\nСтародавні тексти стверджують, що кігті Даґуна виділяють отруту, яка не вбиває здобич, але перетворює її в дещо інше — представника старих рас. Це надзвичайно цінно для нас.\n\nДаґун живе в морських глибинах, але його регулярно виманюють на поверхню Моквоплавникові мурлоки в Бруднолипкій трясовині. Їхні оракули викликають його за допомогою зачарованих морських водоростей. Якщо ти вб'єш достатньо оракулів, то знайдеш водорості. Поклади їх на вівтар мурлоків і Даґун прийде.", [3] = "Серце спадку\n\nМог Невмирущий — трольський знахар з Тернистої долини. Він володіє серцем спадку, яке, як кажуть, відвертає смерть від тих, хто зможе розкрити його таємниці. Ти зможеш відшукати Мога в руїнах Зул'Мамве. Здолай його, якщо зможеш і принеси мені серце спадку.", [4] = "Принеси мені ці три речі: зірку, руку та серце і збірник Яґіна буде твоїм.\n\n— Ґ.К." },
    [4650] = { [1] = "Зірка Ксіл'єх\n\nОгр з Альтерака, Ґрел'борґ Ниций, останній, хто володів цим самоцвітом. Ходили чутки, що він дарує власнику здатність спілкуватися з іншими світами. За нашими відомостями, Ґрел'борґ блукає руїнами Альтерака в Альтерацьких горах, в пошуках інших реліквій серед уламків і сміття.", [2] = "Рука Даґуна\n\nДаґун — істота з глибин, якій поклоняються мурлоки з Бруднолипкої трясовини. Вони виманюють його на поверхню спеціальними морськими водоростями, зачарованими їхніми шаманами. Полюй на мурлоків, збирай їхні зачаровані водорості, а потім поклади їх на вівтар мурлоків. Даґун прийде, коли ти будеш {стать:готовий:готова}.\n\nМені потрібна ця рука.", [3] = "Серце спадку\n\nВ старих текстах пишеться, що той, хто володіє серцем спадку, не боїться могили. Можливо, це правда, адже власник серця, троль Мог, відомий як Мог Невмирущий. Знахар з племені Черепотрощителів, він мешкає в руїнах Зул'Мамве, що в Тернистій долині.", [4] = "Принеси мені ці предмети: зірку, руку та серце і я дам тобі копію збірника Яґіна.\n\n— Хранитель" },
    [4834] = { [1] = "Керівнику Шуморакето, до цього листа додається список обладнання, яке ви замовили, затверджений президентом Раздунком.\n\nВін попросив мене нагадати вам про зацікавленість ТзНБ \"Авантюра\" в налагодженні роботи по всьому Калімдору. Наші бурові та гірничодобувні аванпости в Степах довели свою прибутковість та ефективність, але ми все ще чекаємо на достатню кількість видобутку з Мулґора, що знаходиться у вашій юрисдикції.\n\nКонсультативна рада розуміє труднощі у створенні", [2] = "широкомасштабної операції так близько до батьківщини тауренів, але не вважає, що вона становить значну перешкоду для наших планів у цьому регіоні.\n\nМи раді чути, що на багатих на корисні копалини рівнинах Мулґора розпочався видобуток. Через це рада директорів схвалила ваш запит на обладнання. Крім видобутку корисних копалин, ми вважаємо, що Мулґор також може запропонувати багато пиломатеріалів, тому ми також надамо вам кілька наших найновіших моделей подрібнювачів і сировину для будівництва заводу з виробництва", [3] = "млинів." },
    [4883] = { [1] = "Офіційні накази для флоту Кул-Тіраса\n\nЯ, адмірал Праудмур, очолю першу висадку на береги Калімдору.\n\nЛейтенант Бенедикт призначається моїм заступником на час моєї відсутності. Він займатиметься всіма внутрішніми військовими справами Кул-Тіраса. Якщо я не надішлю звістку з Тіраґардської твердині протягом 12 місяців, лейтенант Бенедикт очолить другу експедицію, що повинна утримати цю землю.", [2] = "Тим часом я відправляю лейтенанта Алверольда на розвідувальну місію навколо Калімдору. Його війська мають завершити свою місію, а потім приєднатися до наших сил у Тіраґардській твердині.\n\nЗа розрахунками, експедиція лейтенанта Алверольда триватиме досить довго. Нові землі здаються величезними та небезпечними. Але якщо зі мною чи Бенедиктом трапиться якась біда, війська Алверольда зможуть повернути твердиню.\n\nМи посилатимемо одну експедицію за іншою, поки твердиня не стане нашою!\n\n—Адмірал Праудмур" },
    [4992] = { [1] = "Вербувальний лист Орди\n\n\nЦя особа продемонструвала неймовірну силу та майстерність в ім'я Орди. Таким навичкам потрібно негайно знайти роботу на Перехресті.\n\n\n\n\nЗ повагою:\n\n\n\n\n\n\n\n\nПідходить.\n\n— Такрін Торувач Шляхів" },
    [4995] = { [1] = "Вербувальний лист Орди\n\n\nЦя особа продемонструвала неймовірну силу та майстерність в ім'я Орди. Таким навичкам потрібно негайно знайти роботу на Перехресті.\n\n\n\nЗ повагою:\n\n- Карґал Битвошрам\n\n\n\n\nПідходить.\n\n- Такрін Торувач Шляхів" },
    [5006] = { [1] = "Розкопки Бель-Модана\n\nПерша команда, відряджена Лігою дослідників, була дійсно права у своїх висновках. Тутешня земля сповнена артефактами, що мають неймовірну цінність для нашого народу. Не сумніваюся, що тут, під піском і каменями Бель-Модана, ми знайдемо довгоочікувані відповіді на низку питань.\n\nОднак, геологічні умови регіону вимагають застосування крайніх заходів. Більшість піщаних відкладень затверділа від суворих та мінливих кліматичних умов.", [2] = "Утім, рішення досить просте. Використовуючи целюлозу як абсорбент, ми можемо поєднати залишки нітрогліцерину з нітратом натрію, щоб виробити сильний заряд вибухової речовини, здатний пробити навіть найщільніші породи.\n\nРобота буде шумною і руйнівною, але наш пошук має набагато більше значення, ніж комфорт місцевих жителів. Насправді нам вже довелося виганяти з регіону людо-биків, які виявилися вельми надокучливими.", [3] = "Той факт, що ми маємо справу з різними недоброзичливими елементами, змушує мене вважати, що нам знадобиться підтримка королівської армії. Крім того, не лише розкопки потребуватимуть військової підтримки: на мою скромну думку новачка, саме розташування Бель-Модана може мати стратегічне значення для Альянсу, враховуючи мінливість світової політики в її нинішньому стані.\n\nНа жаль, я відступив від головного... Попереду ще багато роботи під землею. Я витратив занадто багато часу на писання і недостатньо на розкопки..." },
    [5088] = { [1] = "Панель керування самофланжа може бути використана для автоматичного регулювання потоку палива, газів, рідин і пов'язаного з цим обладнання. Після завершення початкових налаштувань вона повинна працювати без проблем за умови мінімального технічного обслуговування.\n\nКороткий перелік компонентів панелі керування (зліва направо)\n\nI. Головний важіль живлення\n\nУ ввімкненому положенні активізується самофланж. Механізм керування не вимикається автоматично, коли важіль переводиться у вимкнене положення. Це лише", [2] = "розпочне процес охолодження, після чого пристрій вимкнеться приблизно через одну-дві хвилини (залежно від ситуації).\n\nВАЖЛИВА ПРИМІТКА: Головним важелем живлення можна керувати лише тоді, коли три контрольні клапани на обладнанні вимкнені. Ці клапани можна перекривати в будь-якому порядку.\n\nПершим є ГОЛОВНИЙ РЕГУЛЮВАЛЬНИЙ КЛАПАН, який знаходиться на початку вертикальної димової труби. Далі, ПАЛИВНИЙ РЕГУЛЮВАЛЬНИЙ КЛАПАН можна знайти на великій трубі, яка веде", [3] = "від паливних баків (їх має бути три) до димової труби. Нарешті, РЕГУЛЯТОРНИЙ КЛАПАН, його можна знайти на одному з двох нижніх великих циліндричних резервуарів, які впадають в димову трубу.\n\nII. Манометри палива\n\nПоказують поточний тиск у першому, другому і третьому паливних баках.\n\nIII. Індикатор потоку\n\nПоказує поточну швидкість потоку в системі.", [4] = "IV. Регулятори потоку\n\nЗбільшують або зменшують швидкість потоку. Це автоматично контролюється керівним механізмом самофланжу.\n\nV. Індикатор температури\n\nПоказує робочу температуру системи в цілому." },
    [5354] = { [1] = "Майстре Дельґрене,\n\nЦе саме те, чого ви боялись. Ваша теорія про вежу Алталакс підтвердилася. У вежі зібрався культ, в якому безліч чорнокнижників і навіть мерзенних сатирів. Вони називають себе культом Темного Пасма. Я не можу уявити, що об'єднує цих мерзотників разом, але це мене непокоїть.\n\nПрошу вибачити за стислість цього листа, але небезпека чатує в лісі навколо мене і я не можу приділити багато часу на опис ситуації, що склалася. Я б", [2] = "сам передав вам це послання, але боюся відлучитися, щоб не пропустити щось важливе.\n\nЯкщо ви захочете дізнатися більше про мої спостереження за вежою Алталакс, {стать:посланець:посланниця} цього листа дуже {стать:допоміг:допомогла} мені, і я вважаю, що {стать:йому:їй} можна довіряти.\n\nПоспішно завершую,\nБалтул Тіневдар" },
    [5359] = { [1] = "Наш світ переповнений історією. Історією нових і старих рас. Історією воєн, тих, що давно згасли, і тих, що ще тліють.\n\nІсторією богів, що приходять з небес. Й історією старіших богів, що дрімають під землею.\n\nЗараз я говорю саме про них — Старих Богів. Про тих, хто жив і лютував в Азероті, коли світ був ще молодий.", [2] = "Старі Боги — це воля нашого світу. У кожній бурі лунає сміх Старого Бога. Полум'я лісової пожежі — це жар їхнього погляду. Коли Старі Боги йдуть, земля тремтить і тріскається, а слабші за них істоти кричать і рвуть власну плоть у відчаї.\n\nІ не дарма, бо так само як вогонь не виявляє милосердя до дитячої допитливої руки, так і Старі Боги не шкодують тих, хто під ними. У кращому випадку, ми — пішаки. У гіршому — іграшки.", [3] = "Вони були першими володарями світу і правили силою та терором. І хоча зараз вони прикуті ланцюгами й сплять, їхні слуги все ще на волі, і ми, маленькі, жалюгідні смертні, не можемо зрівнятися з їхньою силою.\n\nТих, хто намагається, вони пожирають. Але ті, хто знає своє місце, хто стає на коліна в благанні перед слугами Старих Богів, хто добровільно жертвує розумом і душею... лише вони знайдуть їхню милість.", [4] = "Аку'май, Принцеса Глибин, служить Старим Богам. Вона мешкає в Чорноводних глибинах, благословляючи тамтешні печери своєю древньою мудрістю. Принесена до глибин старшими смертними, Аку'май уособлює божественність. Вона має лише крихту могутності та люті Старих Богів, та навіть така могутність залишається вище нашого розуміння.\n\nТому їй поклоняються. Її бояться і люблять.\n\n\n--Лорґаліс" },
    [5428] = { [1] = "1. Взяти одну чи вісім людина\n2. Бити людина сильно\n3. Бити людина ще\n4. Класти людина у вогонь\n5. Їсти людина" },
    [5455] = { [1] = "Зла сила їх створила, і з легкістю донині\nСидить він на Зловісного Туману вершині\nСміється від над нами, грізно і єхидно.\nЙого елементалям кінця-краю не видно.\n\nНа битву з магом цим подальший шлях лежить,\nБо лише смерть його навіженство скінчить." },
    [5505] = { [1] = "Я почав цей щоденник, щоб вести записи про мої пошуки допомоги для Ясенедолу. Деякі з недавніх подій сповнені таємниць, і я сподіваюся, що зможу розгадати деякі з них, щоб допомогти моєму народові.\n\nДозвольте мені почати з деяких фактів, щоб вони не вилетіли у мене з голови пізніше.\n\nНещодавно я знайшов підтвердження чуткам про діяльність чарівника Дартола.", [10] = "Він розказав, що обійшов увесь Дор'Даніл і не бачив скрині чи іншого вмістилища, куди можна було б помістити навершя.\n\nВін також розповів мені, що в тій місцевості завівся гнилий слиз, і він пожирає майже все, до чого дотягується. Він бачив, як слиз \"поїдає\" столи, скульптури, ведмедів і навіть гномів!\n\nЗдається, що слиз отримує силу, поглинаючи магічні предмети. Якби скриня, в якій лежало навершя, була зачарована, слиз міг з'їсти і її.", [11] = "Це ризиковано, але наразі я не маю інших зачіпок...\n\nКоли я дізнаюся більше, я запишу деталі тут, але до тих пір я працюватиму над пошуком частин жезла і допомагатиму Ясенедолу.", [2] = "Колись я вважав абсурдним, що людина може прийти в наші землі та вивчити наші звичаї, та цей чарівник, цей злий чоловік, прийшов сюди й не тільки вижив, але й здобув частину наших знань. Я досі не розумію, як...\n\nЯ так і не з'ясував його цілей, але його план здавався простим: за допомогою друїдської магії він хотів подружитися з хутропузом, а потім контролювати його. Чи було це спробою нашкодити моїм родичам, чи якоюсь іншою зловмисною метою, я сподіваюся з'ясувати це до того, як мій шлях закінчиться.", [3] = "Попри це, він, вочевидь, досяг певних успіхів в реалізації своїх планів. Чи хотів він випробувати свої сили на хутропузах, перш ніж зайнятися моїм народом? Чи мали хутропузи щось, чим він бажав заволодіти? Хто зна?\n\nВикористовуючи створений ним предмет (якийсь жезл чи посох), він спробував проникнути до племен хутропузів в Ясенедолі. У якийсь момент — і саме тут багато що все ще не ясно — його розкрили хутропузи, коли він намагався нацькувати їх", [4] = "один проти одного. Ельфи на місці хутропузів теж були б розлючені, але ті відреагували сильніше і вбили Дартола.\n\nХутропузи, принаймні в той час, не були тими оскверненими істотами, якими вони стали. Вони все ще були раціональними та розумними — їхні стосунки з нашим народом були дружніми.\n\nЯ сподіваюся, що якщо зможу відтворити жезл за допомогою дріади, на ім'я Шел'дрін, то зможу використати його силу, щоб допомогти нашому народу... і хутропузам.", [5] = "Не всі хутропузи зазнали осквернення. Деякі з них досі живуть і намагаються захищати ліс. Після тих подій деякі хутропузи втекли, багатьох було вбито, а інших вигнали з їхніх племен.\n\nЯ знайшов поважного хутропуза з племені Гидколісових, що живе над озером Містраль — його звати Кролґ.\n\nЯ спостерігав за ним кілька днів і думаю, що якби я наблизився до нього в образі хутропуза, то зміг би допомогти йому і знайти спосіб відновити зв'язок між нашими народами.", [6] = "Після вбивства Дартола, хутропузи розділили жезл на три частини, щоб ним не могли скористатись знову. Це було нелегко, але я здогадуюсь, куди поділися всі три частини.\n\nСамоцвіт\nПерша частина жезла, сяючий самоцвіт, був захований у святилищі на північному-заході Ясенедолу. Я вважаю, що руїни в центрі озера Фалатім і є руїнами того святилища. Стражниці повідомили мені, що зараз там мешкають мурлоки.", [7] = "Якщо я не зможу знайти самоцвіт, захований у святилищі, він може бути в одного з мурлоків.\n\nРуків'я\nЦю частину жезла віддали дереваням біля того місця, яке зараз називається Скверноліссям. Ні хутропузи, ні я не могли підозрювати, що такі величні створіння можуть коли-небудь піддатися скверні, яка охопила ці землі.\n\nМої дослідження показали, що хранителі зберігали його на маленькій галявині, замкненим у скрині. Щоб дізнатися більше, я повинен поговорити з Шел'дрін.", [8] = "Шел'дрін — дріада, що охороняє місячний колодязь на північний схід від Райдужного озера. Вона відмовляється покинути ліс або віддати його на поталу скверни. Я знаю, що вона має силу і знання, щоб відновити жезл, або принаймні розповісти мені, як я можу зробити це самостійно.\n\nНавершя\nНавершя жезла було передано друїдам Дор'Даніла. Але є одна велика проблема: друїди померли.\n\nТепер цю місцевість населяють їхні духи, які більше не демонструють гостинність.", [9] = "Це може потребувати додаткового розслідування. Я не впевнений, чи вистачить мені сил, щоб боротися з духами моїх померлих родичів... не кажучи вже про те, щоб заглибитися в глибини Дор'Даніла і знайти навершя.\n\nПримітка: Під час моїх приготувань в Астранаарі я зустрів дворфа-мисливця, який провів багато часу в Ясенедолі, намагаючись допомогти моєму народові. Він прийшов з місця під назвою Штормовій.\n\nЯкось увечері ми розмовляли за кухлем елю, і його розповіді дали мені нову надію на те, що я зможу відшукати навершя..." },
    [5520] = { [1] = "Елуна почула мої молитви. Життя моїх загиблих товаришів не буде марним, і я помщуся за їхні смерті за допомогою коси Елуни. Це стародавня річ, гілка, вигнута й покручена, з дерева, яке, мабуть, старше за самих калдорай.\n\nБагато годин я розглядала інструмент, який подарувала мені богиня. Це не звичайна зброя і не просте магічне знаряддя. З ним... немовби послаблюються бар'єри часу і простору.\n\nТримаючи косу", [2] = "в руках, я отримала видіння хаосу. Люди-вовки... воргени... билися з неймовірним ворогом. Воргени билися жорстоко, як і належить їхній примітивній расі, але їхні вороги були непохитні — володарі Смарагдового Полум'я.\n\nІ саме тоді я усвідомила справжню силу коси. Зосередившись на ній, я отримала можливість спілкуватися з воргенами. Однак це була не мова. Це було щось інше... Я не можу це описати.\n\nВажливим було те, що воргени чули", [3] = "й розуміли мене. Продовжуючи спрямовувати енергію в косу, я послабила бар'єри світобудови настільки, що змогла привести воргенів у наш світ. З першої спроби мені вдалося викликати трохи більше десятка. Вони пішли за мною в бій, і з їхньою грубою силою під моїм командуванням ми вступили в бій з демонами Сквернолісся.\n\nЕлуна виконала моє бажання. Ліс буде очищено.\n\n\nНехай благословення Елуни буде зі мною, доки я не завершу свою справу.", [4] = "Все йде добре. Я викликала собі на допомогу більше воргенів. Хоча вони мають простий розум, вони продемонстрували неабияку здатність координувати свої атаки та діяти як команда.\n\nУ кожній зграї я знайшла лідера. Їм я доручила командування невеликими групами воїнів. Ми завдаємо ударів у багатьох місцях лісу одночасно, і моя кампанія проти демонів йде успішно.\n\n\nНехай благословення Елуни буде зі мною, доки я не завершу свою справу.", [5] = "Одна зграя втрачена. Я відправила воргенів прочесати ліс і виявити місця демонічного зараження, але вони не повернулися. Я починаю хвилюватися за ватажків, яким довірила командування. Вони примітивні й почали зловживати даною їм владою. Чи збережу я владу над ними? Можливо, мені варто припинити викликати нових воргенів.\n\n\nНехай благословення Елуни буде зі мною, доки я не завершу свою справу.", [6] = "Хоча я не викликала нових воргенів, їхня кількість продовжує зростати. Таке враження, що коса більше не потребує мого втручання для виклику. Це викликає занепокоєння. Я зібрала стільки зграй, скільки змогла знайти, і наказала їм залишатися у святилищі Мел'Тандріс.\n\nТим часом я обшукала бібліотеки Дарнаса і проконсультувалася з Колом Древніх у Темнобережжі. Я не знайшла жодної інформації про цих воргенів. Я чула розповіді", [7] = "та чутки про чарівника Кірін-Тора, на ім'я Аруґал. З того, що я чула, цілком можливо, що він також викликав воргенів. Як би мені не було неприємно, доведеться порадитись з цим чарівником і з'ясувати, що йому відомо.\n\nВоргени небезпечні, і я хочу зупинити їхню навалу. Завтра я поїду до порту в Степах і візьму квиток до Нового Світу.\n\n\nНехай благословення Елуни буде зі мною, доки я не завершу свою справу." },
    [5535] = { [1] = "Після успіху Кел'Тузада в Лордероні, Король-ліч провів останні приготування до нападу на людську цивілізацію. Помістивши свою чумну енергію в кілька портативних артефактів, які звуться котлами чуми, Нер'зул наказав Кел'Тузаду перенести їх в Лордерон, де вони мали бути заховані по різних селах, які контролюються культом.", [2] = "Котли, захищені вірними служителями культу, мали стати джерелами чуми, яка просочиться через ні в чому не повинні фермерські угіддя та міста північного Лордерону.\n\nПлан Короля-ліча спрацював бездоганно. Багато північних селищ Лордерону були заражені майже відразу. Так само як і в Нортренді, жителі, що заразилися чумою, померли та стали відданими рабами Короля-ліча.", [3] = "Культисти під проводом Кел'Тузада прагнули померти та воскреснути в служінні своєму темному володареві. Вони були раді стати безсмертними в невмерлості. З поширенням чуми на північних землях з'являлося все більше здичавілих зомбі. Кел'Тузад, дивлячись на армію Короля-ліча, яка швидко росла, назвав її Скарою — адже незабаром вона підступить до воріт Лордерона... і стане смертною карою для всього людства." },
    [5536] = { [1] = "Ніхто точно не знає, з чого почався всесвіт. Дехто припускає, що катастрофічний космічний вибух в безмежній темряві змусив безмежні світи крутитися і завдяки цьому одного дня вони зародили дивовижне і жахливе розмаїття форм життя. Інші вірять, що всесвіт, яким ми його знаємо зараз, був створений єдиною, всемогутньою сутністю.", [2] = "Хоча точне походження всесвіту залишається під питанням, очевидно, що раса могутніх істот виникла, щоб навести порядок у різних світах і забезпечити майбутнє тим, хто їх населятиме.\n\nТитани, колосальні боги з металевою шкірою з далеких просторів космосу, займалися облаштуванням світів, які зустрічались їм по дорозі. Вони сформували свої світи, здіймаючи могутні гори та викопуючи величезні моря.", [3] = "Вони вдихнули в планети небо і бурхливі атмосфери — все це було частиною їхнього незбагненного, далекоглядного плану створення порядку з хаосу. Вони навіть доручили первісним расам доглядати за своїми творіннями та підтримувати цілісність своїх світів.\n\nТитани, керовані елітною групою, відомою як Пантеон, протягом перших віків творіння, принесли порядок у сотні мільйонів світів, розкиданих по Великій Позамежній Темряві.", [4] = "Доброзичливий Пантеон, прагнучи захистити свої структуровані світи, завжди пильно спостерігав за діями мерзенних, позавимірних сутностей з Підсвітної Крутоверті. Підсвіття, потойбічний вимір хаотичної магії, який зв'язував міріади світів з усього всесвіту в одне ціле, було домівкою для нескінченної кількості злісних, демонічних істот, які прагнули лише знищити життя і поглинути енергію всього живого у всесвіті." },
    [5594] = { [1] = "Джин'Зіле,\n\nминуло багато часу, але я подумав, що ти хотів би знати, що остання з Кривавоперих вбита. Не дякуй мені, бо не я, а {стать:той:та}, що {стать:приніс:принесла} тобі листа, і є вбивцею. Якщо бажаєш, я можу передати її голову тобі після того, як караван здійснить об'їзд по Степах. Я знаю, що ти полюбляєш такі штуки для своєї магії вуду.\n\nБережи себе, мій старий друже.\n\n— Дарсок Хуткоклин" },
    [5628] = { [1] = "Аптекаре Лідоне,\n\nСподіваюся, цей лист дійде до тебе швидко, а його носій — у доброму стані. У далекому Калімдорі сталося те, що, як я вважаю, потребуватиме твоїх навичок.\n\nБуду стислою.\n\nУ Каміннопазуристих горах, неподалік від батьківщини наших союзників тауренів — Мулґора, назріває криза. ТзНБ \"Авантюра\", якою керують гобліни, щосили видобуває там корисні копалини, розлютивши гірських духів.", [2] = "Мушу припустити, що заворушення, які влаштовують в горах духи за підтримки тауренів-шаманів та друїдів, відривають видобувачів від роботи — адже таурени вважають, що присутність ТзНБ \"Авантюри\" в Каміннопазуристих горах — це страшна загроза.\n\nЗагроза чи ні, ми повинні допомогти нашим союзникам.\n\nЛідоне, ти добре знаєшся на токсинах. Чи можеш ти розробити такий токсин, який ми могли б використати, щоб поширити заразу серед гоблінів у Каміннопазуристих горах?\n\nЗ академічною повагою,\nП. Зама" },
    [5737] = { [1] = "Гаразд, ти маєш мати напоготові заряди НГ-5 та детонатори. Я помаркував їх для тебе... Сині — для лісопильні. Червоні — для Вітрокосої печери.\n\nЯ провів невелику розвідку і виявив, що у Вітрокосих скелях достатньо вибухівки, тому для тебе не буде проблемою проникнути туди, встановити детонатори, а потім забратися звідти до того, як все підривати.\n\nПам'ятай, що це лише диверсія. Відійди якомога далі від вагонів, поки гобліни не прийдуть перевірити, що сталося, а потім прокрадись за ними.", [2] = "До речі, будь з ними {стать:обережним:обережною}. Один лише нітроміргліцероній може перетворити тебе на пил. Я помістив частину рідини в мідні пробірки, щоб вона була стабільною і безпечною.\n\nСувій, який ти {стать:отримав:отримала} від Колліна, я використав на коробках з детонаторами. Тепер вони надсилатимуть безшумне повідомлення до зарядів НГ-5 після того, як ти їх встановиш. Я використав простий штальтваргонний механізм, щоб забезпечити оптимальну провідність дротів, а потік нітрогліцеронію між диференціальною рідиною був вище середнього.", [3] = "Перш ніж я повернуся до мого плану, дозволь мені пояснити, де ти {стать:повинен:повинна} розмістити вибухівку.\n\nПлан Альфа — лісопильня:\nПеред лісопильнею стоїть вагон (це на північний схід від споруди для вирубки лісу та збору деревини). Підозрюю, що інженерні плани знаходяться всередині лісопильні.\n\nЗаклади заряд в задній частині вагона. Після того, як ти встановиш його, поквапся та відійди на безпечну відстань.", [4] = "Коли будеш {стать:готовий:готова}, натисни на детонатор.\n\nЯ забезпечив сильний сигнал, проклавши мідні та срібні дроти з мельтузіанською антеною всередині корпусу. Це дасть тобі хороший зв'язок з вибухівкою. Тільки бережись гоблінів поблизу. Вони не оцінять мій витвір, якщо застануть тебе на їхній території.\n\nІ, на всяк випадок, якщо ти цього не {стать:зрозумів:зрозуміла}, не підходь до вагона в момент вибуху... або буде боляче.", [5] = "План Бета — Вітрокоса печера:\n\nЯ бачив, як гобліни розмістили ще один вагон з вибухівкою на північ від входу в шахту. Я думаю, що це буде досить гарне місце, щоб встановити заряд НГ-5 (червоний). Після того, як ти встановиш його в задній частині вагона, відійди на безпечну відстань і натисни кнопку.\n\nЯкщо гобліни не прибіжать подивитися, що сталося, ймовірно, це тому, що гора звалилася їм на голови.", [6] = "Документи ТзНБ \"Авантюра\" з зовнішньої сторони шахти... Гадаю, на ящиках на нижньому рівні.\n\nНехай щастить і пам'ятай...\n\nСиній заряд — лісопильня\nЧервоний заряд — шахта\n\nА, і знищ цей лист після того, як виконаєш свою місію. Хмм, можливо, мені варто придумати спосіб зробити так, щоб листи знищувалися самі після того, як їх прочитають. Непогана ідея..." },
    [5790] = { [1] = "—День перший—\n\nМоя подорож з Залізогарту нарешті привела мене до Калімдору!\n\nРозвідувач Хазґорм з Бель-Модана робить великі успіхи. Сьогодні він знайшов скам'янілість, яку дослідники вважають фрагментом кістки древнього бога. Хазґорм впевнений, що в скам'янілості захована набагато більша таємниця. Поки він наглядає за розкопками, я ставлю собі за мету знайти більше скам'янілостей, щоб скласти докупи цю історію.\n\nМоє завдання: вирушити на південь у пошуках нових підказок.", [10] = "—День шостий—\n\nГералату стає гірше.\n\nСьогодні його очі відкрилися лише один раз. Він говорив з болем і стражданнями, але я зрозумів його. Якщо я хочу вийти з краалю Бритвоболотих живим, треба донести Фалфінделу Шляхостражу в Таланаар, що Чарлґа Бритвобока збирає своїх посіпак у південних Степах. Її сила зростає з кожним днем. Цю відьму потрібно зупинити, перш ніж зло пошириться за межі краалю.", [11] = "Бідолашний Гералат блідий, немов смерть. Його лихоманить все більше і більше. А тим часом кнурі готуються до якогось великого військового походу. Боюся, що якщо я не спробую втекти найближчим часом, мене чекає та ж доля, що і мого сусіда по камері.\n\nМій план полягає в тому, щоб прослизнути повз кнурів, коли вони підуть на наступне полювання. Ті, що мене охороняють, часто сплять на посту.", [12] = "Звільнившись з краалю, я вирушу до Тисячі Шипів, а потім на захід, до Таланаару, що розташований на кордоні таємничого лісу Фералас. Там я шукатиму друїда, відомого як Фалфіндел Шляхостраж.\n\nТе, що почалося як дослідження минулого мого народу, перетворилося на щось набагато більше. Безпека Альянсу в моїх руках....", [2] = "—День другий—\n\nЗемлі Степів просторі та безмежні. Мій шлях був довгим і важким, але поки що не приніс нічого цікавого для архівів Ліги дослідників.\n\nЄдиний випадок, що заслуговує на увагу, стався біля Золотої дороги. Вдалині я помітив якихось дивних істот. Вони були схожі на напівсвиней-напівлюдей. Я швидко сховався і мерзенні звірі пройшли повз мене. Боже, який сморід вони залишили за собою!", [3] = "—День третій—\n\nО, яке ж велике та чудове відкриття!\n\nПід час сьогоднішнього дослідження я натрапив на грандіозну знахідку: великі рештки істоти, схожої на кнура. Його череп здіймався наді мною на багато метрів. Кожен зуб звіра міг би розчавити навіть... ну, дворфа. Через його величезні розміри, я припускаю, що це рештки одного зі Старих Богів, про яких ходили чутки.", [4] = "Колись давно, у штаб-квартирі Ліги дослідників в Залізогарті, я був на лекції, яку читав головний археолог Сіровус. Старий згадував про такого бога, якого возвеличували дивні ельфи з Дарнасу через його альтруїстичну природу...\n\nЙой! Хвилинку. Я чую якесь хрюкання біля мого намету. Напевно, це просто якісь татарні кнури намагаються дістатися до моїх яблук....", [5] = "—День четвертий—\n\nМене взяли в полон!\n\nТреба... писати... швидко.\n\nНа мене напали кнуролюди з племені Бритвоболотих. Я думав, що вони ведуть мене до останків великого кабана, які належать загиблому богу. Але вони обійшли ті великі скам'янілості та пішли на захід від гігантського черепа, через Золоту дорогу.", [6] = "Мене затягли всередину смердючого, зарослого колючками чагарнику під назвою крааль Бритвоболотих. Кинули в якусь халупу і тримали в полоні разом із нічним ельфом, який схоже що вже вмирав.\n\nПри мені не було ніяких речей, окрім цього щоденника, пера і кишенькового годинника...\n\nХтось іде...", [7] = "—День п'ятий—\n\nМій сусід по камері, нічний ельф, страждає від тяжких ран. Кнуролюди неодноразово били його батогами і, здається, він скоро помре, якщо тільки якимось дивом нас хтось не врятує з цього клятого місця. Він то приходить до тями, то втрачає свідомість. Коли він прокидається, я намагаюсь дати йому трохи води.", [8] = "Минулої ночі він вперше зміг заговорити. Він друїд, на ім'я Гералат, якого послали в ці краї, щоб перевірити чутки про загиблого бога-кнура.\n\nОслабленим голосом він розповів мені, що, на його думку, череп великого кнура — це місце, де поліг великий бог кнурів Аґамаґґан у битві з Палаючим Легіоном близько 10 000 років тому під час Війни древніх. Його масивне тіло зрівнялося з землею, а кров його вбралась в ґрунт. І там, де пролилася його кров, росте терен з покрученими шпилями...", [9] = "Гералат і його народ прагнуть знайти джерело зла в цьому місці. Він розповів мені, що Аґамаґґан вважався чистим богом. А чому ця земля кишить мерзенними тварюками та колючими шипами — справді загадка.\n\nПерш ніж я зміг випитати більше інформації, Гералат знову поринув у міцний сон..." },
    [5799] = { [1] = "ЗАМОВЛЕННЯ НОМЕР: 45TK-3\nПОКУПЕЦЬ: Крейвел Вуглеборід\n\nРАХУНОК-ФАКТУРА:\n\nГідрохраповик (3)\nПідсилювальні болти (50)\n30-дюймова мідна трубка 20-го калібру(12)\nТютюн марки \"Темнолют\" (1)\nВисокоякісна призма (3)" },
    [5804] = { [1] = "Гоблін Назз Пароварченко насправді син гоблінського принца-торговця (Якого принца? Це дорога інформація).\n\nСхоже, що йому набагато більше подобається витрачати гроші своєї сім'ї, ніж заробляти їх самому. Тому він викрав невелику частину багатства з сімейного сховища і тепер переховується на Мерехтливих рівнинах.\n\nЯкщо його батько дізнається, де він, то обов'язково знайде його і поверне додому... хіба що без пальця, за нахабність." },
    [5807] = { [1] = "Пане Бульчук,\n\nНапій, який ви дали моєму колезі, отримав величезний успіх. Мало того, що він напій міцний і сильно затуманює розум, здається, він ще й викликає звикання. Я впевнений, що той, хто спробував його, захоче ще.\n\nМи в боргу перед вами, Вибрик.\n\nТакож запрошую вас відвідати Мерехтливі рівнини або відправити довірену особу, щоб відкрити нові горизонти азарту.\n\n—Крейвел" },
    [5826] = { [1] = "Пане Бульчук,\n\nМи з {стать:посланцем:посланницею} цього листа працюємо над однією справою, до якої запрошуємо вас приєднатися.\n\nЯк ви знаєте, я проводжу багато часу на Мерехтливих рівнинах — вищезгадана справа стосується перегонів цих рівнинах.\n\nЯкщо перегони та, зокрема, ставки на них вас зацікавили, будь ласка, читайте далі, бо я відчуваю, що ваше знання Тернистої долини допоможе реалізації нашого плану.", [2] = "Реактивні боліди, що беруть участь у перегонах, мають дуже тонкі налаштування і потребують надзвичайного догляду. Тож не дивно, що екіпажі механіків постійно на місці подій.\n\nЦі екіпажі постійно тестують свої боліди та роблять необхідні зміни та модифікації. Це єдиний спосіб підтримувати їх в ідеальному стані.\n\nОтже... ми шукаємо спосіб змусити послабити увагу одного з екіпажів, оскільки будь-яка помилка призведе до швидкого виходу боліда з ладу.", [3] = "Якщо ми зможемо контролювати те, який болід буди в найкращому стану, а якій ні, то... Мені не потрібно пояснювати вам, яку перевагу це нам дає.\n\nОтже, від вас, милий Бульчук, нам потрібен засіб, який допоможе послабити увагу механіків.\n\nЧи є в Тернистій долині якась рослина, трава чи напій, які можна використати, щоб затьмарити розум гномам і гоблінам?\n\n— К. Вуглеборід" },
    [5827] = { [1] = "Дорогий Мартек,\n\nЗараз я в скрутному становищі та мені потрібна твоя допомога.\n\nМи з братом будуємо автомобіль для перегонів і нам потрібні міцні поршні. Що б я не пробував, в мене нічого не виходить. Ніщо не витримує швидкості нашої нової машини. Через це двигун постійно ламається!\n\nТи ж експерт у роботі з металом. Ти мусиш допомогти. Ти єдиний, хто може це зробити.", [2] = "Ось технічні характеристики поршня:\n\nДовжина: 32 ШВ\nШирина: 12 ШВ\nВага: від 23,5 КГ до 25,5 КГ\nЗапальність: 70 ЗПН\nМіцність на зсув: 98 або вище\nРейтинг перенаправлення: \"Супер міцний\" або вище\n\nНа випадок, якщо ти забув як гноми позначають виміри:\nШВ = \"Ширина вуса\"\nКГ = \"Крихітні грами\"\nЗПН = \"Завитки пальців ніг\"" },
    [5838] = { [1] = "Щоб вполювати Кригопащу, ти {стать:повинен:повинна} спокусити його м'ясом улюбленої здобичі.\n\nВідправляйся через море в Альтерацькі гори та вполюй масивного гірського лева. Убий його, а потім віднеси його тушу до Охлялої печери, місця, яке вважається священним для вендиго.\n\nПоклади тушу на полум'я Узеля, і запах горілого м'яса рознесеться з печери.\n\nІ тоді з'явиться Кригопаща." },
    [5839] = { [1] = "Мене ніколи не перестане дивувати те, як легко завдяки ненависті можна підкорити волю людей. З орками та тролями було найлегше, їхня ненависть до Альянсу зробила їх слухняними підданими, які підкорялися Темному Пасму. Чи мають вони хоч якесь уявлення про те, якій могутній силі вони служать?\n\nЦей паладин, що мене дратує, Дельґрен Очиститель, втручається в наші справи в Ясенедолі, а його прислужник, Балтул, шпигує за моєю вежею, думаючи, що я не знаю про нього. Дельґрен вважає нас незначною", [2] = "загрозою, можливо, просто ще одним культом смерті. Він не знає, що ми лише одне... пасмо Ради Тіні.\n\nУ дитинстві мені розповідали про комаху, укус якої міг легко вбити, хоча на вигляд вона була не більше, ніж муха, як ледь помітна цяточка. Саме те, на що не звертають уваги, завдасть найбільшого болю, якщо дати йому волю." },
    [5860] = { [1] = "Я довго досліджував Аспектів та їхніх творців-титанів, так довго, що жодна людина не зможе стільки зробити за все життя. Коли титани покинули цей світ, існувало п'ять Аспектів, це були могутні дракони, які мали захищати світ Азероту. Про них складено безліч історій і навіть зараз, попри всю зібрану мною інформацію, я знаю, що про цих величних створінь можна дізнатися ще багато цікавого.", [10] = "Нелтаріон:\nНелтаріон, його також звуть Стражем Землі, був більш відданим Азероту, ніж будь-хто інший з Аспектів. Його крило чорних драконів було відповідальним за створення гір та інших утворень на землі, включаючи кордони між смертними расами. Що зіпсувало його, досі залишається загадкою: чи то зовнішній вплив, чи то щось, що зсередини. Цікаво, чи не приклали руку до псування великого чорного дракона Старі Боги?", [11] = "Чорний дракон повністю трансформувався і врешті решт Нелтаріон зник назавжди. Він став Смертекрилом, створінням зла та ненависті. Він більше не був Стражем Землі в очах ельфів, і замість імені, яке дали йому титани, його почали називати Аспектом Смерті та Ксаксасом. Смертекрил є втіленням хаосу і зла, єдине, що він жадає — це руйнування. Він, мабуть, перше зло Азероту, що з'явилося після вигнання Старих Богів.", [2] = "Я не зміг би зібрати самостійно все те, що в мене є зараз. За це я надзвичайно вдячний нічним ельфам. Тільки з їхньою допомогою я дізнався стільки деталей. В результаті нашого спілкування у мене склалося враження, що їхні коріння набагато тісніше пов'язані з Аспектами, ніж я думав спочатку. Однак вони дуже добре оберігають свої таємниці, тож навіть я не впевнений в цьому.", [3] = "Все, що я дізнався про Аспектів, я розмістив тут, щоб інші могли ознайомитись з цим в майбутньому. Я впевнений, що інформація буде корисною, оскільки відчуваю, що з часом ці дракони сильніше впливатимуть на наш світ.", [4] = "Алекстраза:\nАлекстраза, древня і могутня королева драконів, котру називають Берегинею Життя. Вона перша, кого титани створили для захисту світу після того, як покинуть його. Кажуть, що вона бачила народження всіх сучасних рас в Азероті. Її крило червоних драконів, відоме своєю гордістю, колись правило усіма іншими племенами драконів.", [5] = "Серед нічних ельфів ходять чутки, що Алекстраза і напівбог Кенарій були близькими друзями та ніби саме він викликав її під час першого вторгнення Палаючого Легіону.", [6] = "Ізера:\nІзера Сновидиця представляє підсвідомість смертних. Вона уособлює Смарагдовий Сон. Хоч вона більше цінує уяву та творчість і схвалює амбіції смертних рас, але Ізера разом з її крилом драконів вважають реальний світ лише ілюзією. Ізера — одне з найграціозніших і наймогутніших створінь, яке будь-які смертні могли коли-небудь бачити.", [7] = "Маліґос:\nМаліґос відомий як Хранитель Магії або Ткач Заклинань. Його природна форма відрізняється від форми звичайного дракона, і кажуть, що він може змінювати її за бажанням. Після того, як він відступив на далеку північ, його мало хто бачив, він постійно з'являється у вигляді комахоподібної істоти, але коли він приймає форму жракона, від родичів з крила драконів його вирізняє інший відтінок синього кольору.", [8] = "Ноздорму:\nНоздорму відомий як Владика Часу та Позачасовий. Він та його крило драконів бронзового кольору демонструють неабияку кмітливість у всьому. Увага Ноздорму завжди була зосереджена на колекціонуванні артефактів минулого, оскільки його мало цікавлять поточні винаходи смертних рас та навіть його колег-Аспектів. Та його байдужість до чужих справ не означає, що він спокійно ставиться до подій, які відбуваються в усьому світі.", [9] = "Бронзові дракони, які вважаються захисниками, більше проявляють увагу до обжитих територій. Дракон і його крило дуже терплячі, завжди покладаються на спостережливість і діють за планом, не поспішаючи. Ноздорму завжди буде захищати часовий потік і смертні раси, коли їм загрожуватимуть сильніші вороги." },
    [5861] = { [1] = "Поява невмерлих в Азероті почалася не з занепаду принца Артаса — вона почалася задовго до цього. Події, що призвели до падіння Лордерону, були запущені задовго до цього, вони почалися з приходом орчих кланів і Палаючого Легіону.", [10] = "Минуло понад десять років. За цей час Король-ліч використав свої величезні сили, щоб отримати контроль над розумом істот Нортренду і наказав їм звести велику цитадель над своїм льодяним троном. Тепер, коли весь Нортренд був під його владою, Король-ліч знав, що настав час розпочати вторгнення в Лордерон. Замкнений у льоді, колишній орчий шаман почав шукати нових істот, якими можна було б маніпулювати та контролювати. Його поклик пролунав на всіх континентах.", [11] = "Поклик Короля-ліча не залишився непоміченим, особливо для кількох могутніх осіб. Серед них був архімаг Кел'Тузад, який був впливовим членом керівного органу Даларана — Кірін-Тора. Його прагнення заволодіти всіма видами магії порушувало політику Кірін-Тора, спрямовану проти вивчення темної магії. Кел'Тузад покинув Кірін-Тор, розірвав всі свої зв'язки зі звичайним світом і поклявся стати старанним учнем Короля-ліча.", [12] = "Між ними було укладено угоду. Кел'Тузад отримає безсмертя і величезну силу в обмін на служіння Королю-лічу. Першим завданням Кел'Тузада було скористатися своїм багатством і впливом в Лордероні, щоб заснувати культ Проклятих. Цей культ обіцяв своїм прихильникам рівність і вічне життя, якщо вони присягнуть в вірності Нер'зулу, \"богу\" культу Проклятих.", [13] = "Тоді Нер'зул створив артефакти, призначені для поширення чуми серед людських народів Лордерона. Він віддав їх Кел'Тузаду і наказав рознести їх по всій землі. Послідовники його культу мали захищати артефакти за будь-яку ціну.", [14] = "Опинившись на місці, чума почала просочуватися в землю, вражаючи мешканців, які нічого не підозрювали. На очах Кел'Тузада армія Короля-ліча швидко зростала і незабаром він захопив владу над великими територіями. Ця армія стала відома як Скара, і її єдиним завданням було принести смертну кару всьому живому в Азероті.", [2] = "Орки Дренору (світу, з якого вони походять) були благородними та прагнули до знань. Вони були могутніми воїнами, сильними тілом і душею. Саме через це їх шукав Палаючий Легіон. Кіл'джеден, сильний демон Легіону, бажав поневолити клани орків і використовувати їх як свою армію в світах, які Палаючий Легіон ще не завоював.", [3] = "Кіл'джеден прийшов до вождя кланів, могутнього шамана, на ім'я Нер'зул. Він пообіцяв Нер'зулу величезну силу і знання, якщо той укладе з демоном угоду, що віддасть клани у владу Палаючого Легіону. Ця угода назавжди визначила не лише їхню долю, але й долю всього їхнього світу.", [4] = "З часом Нер'зул усвідомив, що доля кланів в руках Палаючого Легіону і тоді шаман кинув виклик Кіл'джедену. Демон, розгніваний вчинком Нер'зула, звернувся до учня шамана, Ґул'дана, який набагато легше піддавався маніпуляціям, на відміну від Нер'зула.", [5] = "Саме Ґул'дан був винен в занепаді шаманізму в кланах. Він обіцяв усім могутність і владу над ворогами, і його охоче слухали. За допомогою Кіл'джедена Ґул'дан почав маніпулювати кланами. Колись шляхетні орки тепер стали злими, бездумними дикунами. Після прийняття крові демонів орки стали ще безжальнішими варварами.", [6] = "Попри те, що Кіл'джедену вдалося схилити до себе Ґул'дана після невдачі з Нер'зулом, він продовжував ненавидіти шамана і поклявся змусити його виконати їхню початкову угоду. Кіл'джеден схопив Нер'зула і почав повільно й нестерпно катувати його. Поки Нер'зул благав про смерть, Кіл'джеден нагадував йому про їхню угоду. Кіл'джеден вбив орка, але лише фізично. Він затримав дух шамана, перш ніж той зміг знайти шлях до Підсвітньої Крутоверті.", [7] = "Кіл'джеден помістив дух Нер'зула в брилу льоду, принесену з Підсвітньої Крутоверті. І поки він був ув'язнений, Кіл'джеден вливав у нього ще більше сили. Втрата тіла і володіння такою неймовірною силою призвели до повного перетворення Нер'зула.", [8] = "Кіл'джеден кинув брилу льоду крізь виміри назад в Азерот, де вона приземлилась на континенті Нортренд та принесла в наш світ це велике зло. Нер'зул зник назавжди, а на його місці залишився трон з льоду та ненависті. Колись шанований вождь шаманів став неймовірно могутнім Королем-лічем.", [9] = "Оскільки Кіл'джеден не довіряв Королю-лічу, він відправив своїх повелителів жаху наглядати за духом і стежити, щоб той виконував його накази. Його слуги охоче вирушили в Азерот, їх приваблювали руйнівна сила і влада Короля-ліча, а також можливість знищити населення цілої планети." },
    [5882] = { [1] = "Скривавлений горобець: декларація перевезення\n\n(20) бочок рому. Пункт призначення: Терамор\n(50) мішків борошна. Пункт призначення: Терамор\n(2) ящики з різноманітними гномськими інструментами. Пункт призначення: Брашпиль\n(30) рулонів бавовняного полотна. Пункт призначення: Терамор\n(4) ящики зі спеціями. Пункт призначення: Терамор\n(3) пасажири. Пункт призначення: Терамор", [2] = "Капітане,\n\nБажаю вам удачі у подорожі. На жаль, нам не пощастило під час першої спроби викрадення.\n\nКоли наша команда вийшла на зв'язок з ціллю в тунелі між Штормовієм та Залізогартом, то виявила лише приманку. Схоже, що він виявився розумнішим, ніж ми думали.\n\nАле наш другий план вже працює. Агенти Непокірних готові перехопити ціль, коли вона наблизиться до Терамору. Незабаром Штормовій відчує наш удар...\n\n— M" },
    [5897] = { [1] = "ВІТАЄМО!\n\nВи стали {стать:щасливим власником:щасливою власницею} дивовижного шморгоноса! Попри те, що це сором'язливе створіння, ми впевнені, що його пухнаста милість і неймовірні нюхові здібності вам дуже сподобаються.\n\nНа наступних сторінках ви знайдете інформацію про вашого улюбленця:\n\n1. Годування та догляд\n2. Ексцентрична (і чарівна) поведінка\n3. Використання запатентованої палиці керування шморгоносом\n\nЩе раз вітаємо вас. Ви не будете розчаровані,\n\n-Марвіґ Ржавоболт\nВласник, корпорація Шмиг", [2] = "ГОДУВАННЯ ТА ДОГЛЯД:\n\nМи прагнемо забезпечити вас усім необхідним для догляду за вашим улюбленцем. Наші клієнти очікують такого рівня обслуговування від корпорації Шмиг. і ми з цим згодні!\n\nЗ цією метою ми розробили міцні ящики для шморгоносів з невеликими отворами, які ідеально підходять для утримання вашого улюбленця в безпеці, захищеному місці та якомога далі від світла.\n\nДля вашої зручності всередині кожного ящика є місткість для кормових гранул, наповнених спокусливим ароматом бульб синьолиста (улюблених ласощів шморгоносів)!", [3] = "ВИГУЛ ШМОРГОНОСА\n\nШморгонос любить маленькі, темні місця. І він дуже сором'язливий.\n\nЯкщо ви хочете вигулювати шморгоносаа, то ви повинні віднести його в місце, де він почуватиметься як вдома. І ОБОВ'ЯЗКОВО туди, де він може відчути запах своєї улюбленої їжі — бульб синьолиста!\n\nНайближче таке місце — \"траншея\" краалю Бритвоболотих. Якщо ви відкриєте свій ящик біля траншеї, і ваш шморгоніс відчує запах бульб, то він наважиться вийти та піти за вами.", [4] = "ПАЛИЦЯ КЕРУВАННЯ ШМОРГОНОСОМ\n\nШморгоніс — дивовижна тварина. Мало того, що він викликає любов і прихильність навіть у злісного рівнинобіга, він може відчути запах бульби синьолиста на відстані до п'ятдесяти метрів!\n\nЯкщо ви хочете відправити шморгоноса на пошуки бульби, ви можете скористатися нашою запатентованою палицею керування шморгоносом (продається окремо).\n\nВказівки на наступній сторінці...", [5] = "Всі наші шморгоноси дуже добре навчені, і просто змахнувши палицею керування, ви переведете шморгоноса в \"режим пошуку\". Потім він почне принюхуватися до бульби, і якщо відчує її запах, то попрямує до неї та викопає її.\n\nЯкщо ви змахнете палицею ще раз, поки шморгонос шукає бульбу, він припинить пошуки та радісно повернеться до вас.\n\nМи запевняємо вас, що наші шморгоноси стануть неймовірно корисним та милим доповненням до вашої команди!", [6] = "Нам боляче згадувати, що корпорація Шмиг отримала кілька скарг на те, що деякі жадібні мисливці за бульбами мало дбають про безпеку своїх милих улюбленців і відправляють їх у темні й небезпечні місця в пошуках бульб.\n\nМи не виправдовуємо таку безвідповідальну поведінку, але, прагнучи задовольнити потреби клієнтів, ми включили гарантію до кожного проданого шморгоноса, що дозволяє власникам замінити втраченого улюбленця.\n\nЩасливого полювання!" },
    [5917] = { [1] = "— День 13\nПереміщення військ поблизу Терамора збільшилося. Велика кількість людей покинула місто та поспішно рушила на захід.\n\n— День 14\nБільше військ залишило місто. Я слідкував за невеликою групою й спостерігав, як вони знімають уніформу після того, як відійшли від Терамора на дальність польоту стріли. Можливо, вони дезертири?\n\n— День 15\nЯ випадково чув, як деякі тераморські війська сьогодні говорили про охорону, яка залишила свої пости. Мабуть, мої підозри щодо дезертирів правдиві.", [2] = "— День 16\nУлеґ і Тарґіл повернулися зі своєї місії до доків Терамора. Вони побачили в порту новий корабель: «Скривавлений горобець». Корабель прибув із гавані Менетілів, що в Азероті.\n\nЗавтра Улеґ і Тарґіл повернуться до доків і прокрадуться на борт корабля. Вони сподіваються знайти документи, які розкриють деталі відносин між Терамором та Альянсом.", [3] = "— День 17\nУлеґ повернувся зі свого завдання. Він зазнав невдачі й Тарґіла схопили. Я послав Улеґа передати цей звіт Назіру.\n\nЯ залишусь тут. Я помітив збільшення корабельної активності біля узбережжя Терамора. Продовжуватиму стежити й особисто повідомлятиму про будь-які важливі події." },
    [5947] = { [1] = "Наш перший план вже провалився!\n\nКулаку вдалося змінити порядок охорони тунелю того вечора, але через непередбачувані дії деяких мешканців Штормовію нашій цілі вдалось втекти з місця злочину до того, як ми змогли його схопити. Але ми були готові до таких непередбачуваних ситуацій. Потім ми привели в дію план 2 і все йшло добре ще до засідки в Штормовії.", [2] = "План 2 такий же простий, але потребує більше терпіння з нашого боку. Наш агент в Менетілі вже отримав плату за свою роботу і блискуче впорався з поставленим завданням. Тепер ми без проблем знайдемо нашу ціль і захопимо її, щойно відпливемо.", [3] = "Очікується, що атака відбудеться за кілька миль від місця призначення. Саме там наші \"союзники\" чекатимуть нас. Я не знаю, чому нас змусило укласти союз з цими істотами, але мне не покидає відчуття, що нас змусили це зробити. Зрештою, це не має значення. Захопивши ціль, ми станемо набагато ближче до того, щоб відібрати Штормовій в тих, хто вкрав його у нас!" },
    [5948] = { [1] = "Йоргене,\nМої найгірші очікування справдилися, збулося те, чого я й уявити не міг. Я ніколи не думав що вони підберуться так близько, але це сталося.\n\nБудь ласка, допоможи {стать:посланцю:посланниці} цього листа та відправ до НЬОГО. Чесно кажучи, я думаю, що він допоможе нам коли дізнається про всю серйозність цієї справи. Якби нам загрожувало щось інше, він, напевно, продовжував би ігнорувати нас і проблеми нашого чесного міста.\n\nДякую тобі, старий рибалко. Я, як завжди, в боргу перед тобою.\n\nТвій друг,\nДелавей" },
    [5998] = { [1] = "Майстре Довгобороде,\n\nЯк ви знаєте, ми, клан Бурешпиль, прагнемо досконалості, тож якість ваших щитів для нас не є таємницею.\n\nТому я хочу замовити у вас такий щит. На наступній сторінці я включив вимоги:", [2] = "-Ідеально круглий, довжиною від кулака до ліктя.\n\n-Заклепки по краю. Срібні.\n\n-Одна велика заклепка в центрі, на ширину трьох пальців. Срібна.\n\n-Дубовий, укріплений залізом.\n\n-Моє ім'я, Ґрінґер Бурешпиль, вигравіюване на верхньому обідку.", [3] = "Оплата буде здійснена звичайним способом. І дайте пред'явнику цього замовлення стандартну, належну плату за доставку. Ви можете додати її до вартості щита.\n\n\n\nЗ повагою та великою вдячністю,\n--Ґрінґер Бурешпиль" },
    [6167] = { [1] = "Гелґраме,\n\nМої вітання тому, хто віддав наказ заснувати Карґат у Безплідних краях. Це ідеальне місце для тренування наших військ. Сувора погода, жорстока дика природа, войовничі місцеві жителі та повна відсутність підтримки ззовні роблять це місце горнилом, з якого вийдуть лише найкращі воїни й розвідники.\n\nГарний задум. Просто чудовий.", [2] = "Я опишу навколишні землі так, як донесли розвідники Карґата:\n\n-Червоні, скелясті пагорби та сухі рівнини, які мало придатні для життя.\n-Палюче сонце і суворі вітри.\n-Ні озер, ні струмків. Навіть дрібних калюж немає. Щоб знайти воду, мешканці повинні копати глибокі, брудні колодязі або висмоктувати мізерну вологу з рідкісних кактусів чи колючого бур'яну.\n\nКоротко кажучи: гаряче, важке життя.", [3] = "Безплідні краї наповнені ворогами. Огри блукають розпеченими пісками, нападаючи на необережних мандрівників. Дворфи Темного Заліза живуть у бараках на схід від Карґата і воюють зі своїми світлошкірими родичами в Лох-Модані на півночі. Жорстокі, примітивні звірі, які звуться трогами, переслідують будь-який клаптик тіні, який вони знаходять, і жорстоко захищають його.\n\nА на сході Безплідних країв, в ущелині Летлор, живуть дракони. Ми не знаємо, скільки їх і наскільки вони великі, бо розвідники, які підходять надто близько, ніколи не повертаються.", [4] = "Не варто й казати, що ми — ті, хто перебуває в гарнізоні Карґат — цілком задоволені своїм призначенням. Ми стоїмо твердо, бо якщо розслабимося, то помремо.\n\nІ я не хочу, щоб було інакше.\n\nНіка Кровошрам\nСтарша розвідниця, Карґат" },
    [6283] = { [1] = "Азерот — це місце, де немає кінця-краю дивам. Флора, фауна, культури та магія буяють у ньому. Дійсно, допитливі знайдуть в цьому світі безмежне розмаїття. Все лежить на поверхні, куди не поглянь.\n\nА якщо зазирнути глибше, то відкриваються вікна в абсолютно нові світи, в кожному з яких є свої чудеса.\n\nІ так само в них є свої жахи.", [2] = "Це і є метою моєї книги: каталогізувати тих істот, ту потойбічну нечисть, що бажає знищити наші землі, щоб дослідники, які натраплять на них, знали, з чим їм доведеться зіткнутися.\n\nТож якщо ви вважаєте себе захисниками Азероту, то читайте далі. І пізнайте свого ворога.\n\n-Ур\nМаг Даларану", [3] = "Нечисть, про яку я пишу — це воргени.\n\nСтарий, сільський фольклор може містити згадки про цих істот, адже яка селянська дитина не чула казок про людей-вовків, що блукають лісами й болотами біля її рідного селища?\n\nІ в цих казках може ховатися і правда — можливо, вони є застереженням про воргенів, завуальованим під міфи, щоб налякати нас.", [4] = "І все ж маю запевнити скептичних читачів: воргени існують. Можливо, вони не з нашого світу, але між їхнім домом і нашим існують шляхи, і потужна магія може притягнути їх сюди.\n\nАле краще такою магією не користуватися, адже де б не з'являлися воргени, вони несуть з собою лиш жах і смерть.", [5] = "Ви впізнаєте воргена за його схожістю з вовками нашого світу. Дивлячись на воргена, можна легко помітити, що його груба шерсть, загострені вуха і довга морда нагадують відомих нам вовків.\n\nАле так само швидко ви побачите і його відмінності: груба шерсть вкриває потужне двоноге тіло, з пащі стирчать довгі ікла, а пазурі — немов кинджали. А за його виттям ховається злість, якою не володіє жоден звір.", [6] = "Дім воргенів — це темне місце, місце кошмарів. Якщо в цьому світі існують місця, захищені від проклятих воргенів, то моє дослідження не виявило таких бастіонів.\n\nА якщо взяти до уваги жорстокість і злість воргенів, то, швидше за все, таких місць не існує.\n\nМожна припустити, що воргенів цілком влаштовує їхній власний світ, бо хоч деякі воргени й володіють могутньою магією, вони не робили жодних спроб дістатися Азерота за власним бажанням.\n\nІ з цим нам пощастило.", [7] = "Як згадувалося вище, деякі воргени володіють містичними мистецтвами, а їхня магія — це темрява і скверна.\n\nПрокляття та надприродні отрути є поширеним явищем серед них, тому будьте обережні — ті, хто стикається з воргенами-магами, повинні захистити себе від темряви.", [8] = "Я сподіваюся, що жоден даларанський чарівник не шукатиме воргенів, навіть з чистими помислами. Бо не можна укласти жодної угоди, не можна дізнатися жодної таємниці, не можна отримати жодної користі від цих звірів.\n\nЇх краще залишити в їхньому світі. Бо якщо вони з'являться в нашому і не будуть знищені, то ми приречені..." },
    [6304] = { [1] = "Щоденник — день 4\n\nЦе вже четвертий день відколи я застряг на острові, залишившись наодинці зі своїми думками. Банани дуже смачні, але до них так важко дістатися. Коли я не можу дістати їжу або захиститися від дощу, я тільки й думаю про порятунок.\n\nЯ б і не сподівався, якби не коробки з-під паперу та пляшки, які прибило до берега разом зі мною. Зараз я зі сміхом згадую, як я проклинав той човен, повний алхіміків і писарів, на якому я провів стільки часу." },
    [6305] = { [1] = "Ці місяці дали мені час на роздуми, на те, щоб позбутися старих переконань і фанатизму. Альянс? Орда? Добро? Зло? Значення цих слів, колись таких зрозумілих, тепер розпливаються, коли мої очі вдивляються в безмежне море.\n\nТепер я знаю, що має значення. Банани переслідують мене.\n\nСидячи високо на дереві, вони дивляться на мене з холодною злістю. А останній, який я спробував з'їсти, ледь не заткнув мені рота! Мені здалось, що я чув його крик, коли я розмазав його, наполовину надкушеного, об морське каміння.\n\nЦе війна і я її виграю." },
    [6306] = { [1] = "Щоденник — день 512\n\nБанани заговорили зі мною і я дізнався багато нового про їхню культуру. Я припинив безглузде руйнування їхніх домівок і поїдання молодих. Як мало я тоді знав про велику цивілізацію, яку знищував.\n\nЩодо іншої теми, то, здається, у мене закінчуються пляшки та папір. Коли я вперше подивився на ті величезні купи паперу, які викидало на берег, я подумав, що вони невичерпні. Ой, горе мені, місце в моєму щоденнику скоро закінчиться." },
    [6488] = { [1] = "Здоров, {стать:друже:подруго}. Передай цю скрижаль Франґу в долині Випробувань. Він обично стоїть десь біля Лігва і ганяє новачків, наставляючи на шлях воїна Орди.\n\nЙому треба такі вправні воїни, як ти, шоб показать цим оркам, шо битви виграються не тільки грубою силою. Ти спритніше і розумніше за тамтешніх орків, та сильно не вихваляйсь — орки цього не люблять. Вони гарні союзники та можуть тебе чомусь навчить.\n\n-Тар'сер" },
    [6842] = { [1] = "На наступних сторінках ти знайдеш список матеріалів, необхідних для виготовлення загартованої вогнем броні. Хай щастить, {клас:к}.\n\n\n-Фьюрен Довгобород", [2] = "Обпалені павучі ікла:\n\nСпалахітова руда в печері Тельґена обпалила тамтешніх павуків.\n\nОтрута в їх іклах кипить та вступає в реакцію з самими іклами, утворюючи дуже міцну речовину.", [3] = "Обвуглені роги:\n\nТак само, як і обпалені павучі ікла, обвуглені роги химер, що проживають в Обвугленій долині Каміннопазуристих гір Калімдора, мають неабияку цінність.\n\nЗа правильної обробки вони стають дуже стійкими до ушкоджень.", [4] = "Гальванізований ріг:\n\nМіцність рідкісного гальванізованого рогу є основою всього шматка обладунку, який я створю, тож його теж необхідно добути.\n\nОтримати його можна з рідкісної химери-матріарха в Обвугленій долині.", [5] = "Фіал флогістону:\n\nНа останньому етапі створення броні знадобиться надзвичайно гаряча кузня. Щоб отримати необхідний рівень тепла, мені потрібен фіал флогістону.\n\nЄдиним відомим виробником цієї речовини є легендарний свинобраз Руґуґ, і він не віддасть її без бою. Руґуґ мешкає глибоко в краалі Бритвоболотих на півдні Степів." },
    [6846] = { [1] = "План приведено у дію.\n\nРозбийте на цьому, колись великому бастіоні віри, Варті Героїв, наш табір. Ми почнемо перекидати туди підкріплення із Західного краю, щойно дізнаємося від вас, що табір належним чином підготовлений.\n\nЖителі та солдати Штормовію давно забули про це місце, тож ми зможемо успішно влаштовувати звідти набіги.\n\nНепокірні відіб'ють Штормовій!\n\nЧекаю вашої відповіді." },
    [6847] = { [1] = "Цих брудних трогів так просто обдурити. Їхня ненависть до нашого виду дозволяє рухати ними, як пішаками. Вражає, як вони пішли хоч на якийсь союз, але ми для них більша загроза... принаймні поки що.\n\nКоли почнуться напади, обидві сторони ослабнуть і не встоять перед нашим натиском. Захопіть будинок на південь від озера Постеля Гельма і чекайте на подальші вказівки.\n\nЗалізогарт буде наш." },
    [6929] = { [1] = "Нижче ти знайдеш всі необхідні компоненти для мого закляття виклику Циклоніана. Хай тобі щастить.\n\n--Бат'рах Вітрогляд", [2] = "Життєкорінь:\n\nВін може зустрітись тобі в мандрах або ж його можна зібрати з сухолозих чудиськ в Бруднолипкій трясовині. Його сила необхідна мені для того, щоб приманити життєву сутність Циклоніана в наш світ.", [3] = "Ікла Кровоскальпих тролів:\n\nІкла Кровоскальпих тролів з Тернистої долини мають унікальні властивості. Безумство Кровоскальпих зосереджено у їхніх іклах, тож, розтовкши їх в порошок, можна вивільнити ці злі сили.", [4] = "Сутність вигнанця:\n\nЦю сутність можна отримати, поєднавши три обереги стихійних вигнанців з височини Араті. Збери грозові, палаючі та бурунисті обереги з елементалів та помісти по 8 штук кожної в мій казан.\n\nЗ них сформується сутність вигнанця." },
    [6996] = { [1] = "{ім'я:к},\nПерш за все, я хочу ще раз подякувати тобі за все, що ти {стать:зробив:зробила} для мене і моєї дружини. Ти {стать:врятував:врятувала} її, і за це я не зможу віддячити впродовж всього життя. Якби з нею щось сталось... я не знаю, що б я робив...\n\nОсь список всього, що ти маєш зібрати, щоб я зміг викувати для тебе гідну зброю. Я записав послідовно — від простішого до складнішого, так тобі буде легше.", [2] = "Деревина білокам'яного дуба. В шахтах під Місяцеграєм, що в Західному краї, було багато цієї деревини до того, як їх захопили повстанці. Вона використовувалась для виробництва обладнання та інструментів через її стійкість до жару та тиску.\n\nЇї привезли туди з-за океану. Ця рідкісна деревина достатньо міцна для виготовлення зброї для тебе. Якщо вона ще залишилась — ти знайдеш її у гоблінів-дроворізів.", [3] = "Очищена руда. В Телсамарі є дворф-коваль, у якого я навчався деякий час, звати Байлор Камнерук. Він вміє робити особливий сплав, який, як мені здається, чудово підійде для твоєї зброї. Я очікував прибуття чергового вантажу в Залізогарт, та поки про нього нічого не чути.\n\nЗнайди Байлора і перевір, чи не готове моє відправлення. Якщо не знайдеш його в Лох-Модані — хоча б дізнайся що сталось з моїм старим вчителем.", [4] = "Ковальський молоток. До приходу чуми та зради Артаса я жив в містечку Поховальні Вогнища, глибоко в прекрасних лісах Срібнохвою. Ліс вже далеко не такий красивий, як колись, а фортеця, в якій мене навчали роботи зі сталлю, занепала й була захоплена злими істотами.\n\nКоли ми з дружиною втекли з місця, що зараз називається фортецею Тіньового Ікла, ми залишили кілька цінних речей.", [5] = "Серед тих речей — ковальський молоток мого батька. В молодості я сумнівався в цьому, та батько завжди казав мені, що той молоток зачарований. І це останнє, що я почув від нього перед тим, як його згубила Скара.\n\nПринеси мій молоток, {ім'я:к}, він допоможе мені зосередитись на справі. І якщо він дійсно зачарований — це допоможе нам обом.\n\nЯ залишив його в стайнях на головному подвір'ї в фортеці. Якщо ці істоти не забрали його, він має все ще бути там.", [6] = "Самоцівіт Кора. Я чув, що самоцвіти використовуються чаклунами, щоб утримувати енергію своїх заклять, роблячи їх могутнішими. Нічний ельф, якому я колись допоміг, Тандріс Вітроткач, може розказати про нього більше, якщо скажеш, що тебе відправив я. Думаю, ми зможемо використати один з таких самоцвітів, наповнених енергією, для створення твоєї зброї.\n\nВостаннє я бачив Тандріса в Аубердіні, містечку на Темнобережжі, що лежить в тінях крони Тельдрассіля — домівки цього нічного ельфа." },
    [7266] = { [1] = "Таємничі закручені символи та піктограми, що заповнюють сторінки цього посібника неможливо зрозуміти." },
    [745] = { [1] = "ЗВІТ: Кобольди\n\nАктивність кобольдів зросла на околицях Північнокрайової долини. Їхні табори, на півночі від абатства та в копальні Ехокряжу, зростають у тривожній кількості. Я відправив паладинів, воїнів та інших тутешніх, щоб допомогли мені позбавити нас від шкідників.\n\nСправа успішно прогресує. Звітуватиму за потреби.", [2] = "ЗВІТ: Злодії\n\nСитуація більш тривожна, ніж у випадку з кобольдами, у долині з'явилася банда людей. Вони носять червоні бандани та називають себе братством. Такий рівень структурованої організації може призвести до проблем, як тут, так і по всьому Елвиннському лісі.\n\nМи ідентифікували одного з їхніх лідерів — такого собі Ґарріка М'якоступа — і сподіваємось притягнути його до відповідальності найближчим часом.", [3] = "ЗВІТ: Вовки\n\nЗафіксовано збільшення кількості випадків нападу тварин у Північнокраї. Іґан вважає, що вовкі щось налякало в Смерколіссі й внаслідок цього вони мігрували сюди.\n\nХоча вовки рідко полюють на людей, різке зростання їхньої популяції спричинило велику кількість інцидентів з фермерами. Також значна кількість худоби пропала безвісти.", [4] = "РОЗПОРЯДЖЕННЯ:\n\nНосій цих документів, {стать:служив:служила} Північнокраю самовіддано та винятково старанно, за це {стать:йому:їй} повинно бути присвоєно ранг «заступника» армії Штормовію. Впевнений, що {стать:він:вона} стане вельми {стать:корисним:корисною} в Ельвиннському лісі.\n\nпідписано:\n— маршал Дуглас Макбрайд,\nармія Штормовію, Північнокрай" },
    [748] = { [1] = "Цей знак броні можна обміняти на один шкіряний або тканинний обладунок, який можна отримати в домогосподарстві Древолягів у лісозаготівельному таборі Східнодолу." },
    [7516] = { [1] = "Дістань нефрит. Їх можна знайти в багатьох різних місцях. Вони зустрічаються рідко, але якщо спитаєш коваля чи інженера, у них може знайтись кілька в запасі.", [2] = "Візьми заряджену блискавкою тростину. Щоб таку отримати, візьми 10 тотемних палиць тролів племені Зів'ялої Кори з височини Араті. Принеси ці палиці до кола з каменів що поряд з колом Зовнішнього Поневолення. Розклади палиці на центральному камені у колі та дочекайся, поки в нього вдарить блискавка. Коли це станеться, заряджена блискавкою тростина сформується." },
    [7587] = { [1] = "{ім'я:к}, ось список матеріалів для виготовлення твого обладунку:\n\nЗлитки димчастого заліза Вітрокосих кобольдів з Вітрокосої печери, що в Каміннопазуристих горах.\n\nМолотий азурит гіллзбрадських шахтарів в Гіллзбраді.\n\nЗлитки заліза, які можна дістати у шахтарів або зробити самотужки.\n\nФіал флогістону, який можна дістати у свинобраза, на ім'я Роґуґ в краалі Бритвоболотих." },
    [7668] = { [1] = "(Через плями можна прочитати лише частину щоденника).\n\nУльдаман. День 3\n\nНе можу повірити, що я був таким дурнем. Підлі дворфи з Тінегарту застали мене зненацька, як простака. Мої рани загоюються повільно, напевно, мене отруїли. Я відчуваю, як втрачаю свої сили. Але мені все одно потрібно йти вперед...\n\n...що ще гірше, намисто, яке гном зробив для мене, розлетілося на друзки! Три найбільші самоцвіти, що були в ньому, загубилися. Я маю знайти їх, без них намисто безсиле...", [2] = "Ульдаман. День 4\n\n...перша підказка з'явилася в глибинах Ульдамана, коли один лютий трог, скажу чесно, я вперше бачив такого, розмахував великим сапфіром — б'юся об заклад, він ідеально підійшов би до намиста. Я підслухав, як один з дворфів Тінегарту назвав ім'я цього чудовиська: Ґрімлок. Однак, цей Ґрімлок має цілу купу охоронців...", [3] = "Ульдаман. День 5\n\n...той трог потім забрав топаз у свого убитого \"побратима\" і побіг у бічну печеру біля зовнішньої частини зали...\n\n...швидко поклав топаз у велику, помітну вазу в кінці зали...\n\n...і тут з'являються дворфи! До того ж троє. Вони забарикадувалися від трогів. Покликати їх на допомогу було б самогубством, кляті троги відразу би накинулись на мене, а я ще й ослаблений. Однак, коли я взнаю, де третій камінь, я...", [4] = "Ульдаман. День 6\n\n...дуже голодний. У мене закінчилися припаси, зараз для мене запліснявілий хліб — цілий бенкет. Навіть голова трога виглядає їстівно...", [5] = "Ульдаман. День 7\n\n...останній шанс спокутувати свою провину. Я думаю, що рубін знаходиться за останньою барикадою дворфів, де вони тримають оборону від трогів. Вони, без сумніву, б'ються за дорогоцінні камені та інші артефакти цього місця. Це в дусі цих мерзенних дворфів, заховати його десь там. Попри це, мені потрібно придумати, що робити далі. Можливо, божевільний ривок до виходу — це найкращий спосіб..." },
    [7907] = { [1] = "{стать:Власник:Власниця} цього сертифікату має право на повагу та пошану, на яку заслуговує будь-який першокласний злодій та крадій." },
    [7908] = { [1] = "ТзНБ \"Авантюра\" <нерозбірливий текст> Здавалося б, дурні ледь не звели нанівець всю свою операцію, намагаючись стабілізувати суміш.\n\n<здається, кілька сторінок вирвано>", [2] = "Що я помітив, так це те, що побічний ефект надзвичайно смертельний. Уявіть, якщо <нерозбірливий текст> Ха-ха-ха!", [3] = "Я їду з глузду? Сьогодні я відрубав голову одному з моїх найбільш довірених патрульних, щоб краще поглянути на його душу. Поки я вдивлявся у його перерізану трахею, мені спало на думку: я кілька днів нічого не їв!", [4] = "Матіас Гич послав хлопчика на побігеньках вбити мене. <нерозбірливий текст>\n\nЗараз він патрулює надворі. Безмозкий, неживий боввдур.\n\nХа-ха-ха!", [5] = "Ван-Кліф... <нерозбірливий текст>\n\nВикликав МЕНЕ?? КИМ ВІН ВВАЖАЄ СЕБЕ?? Я Клейвен Мортвейк! Ця комаха не вказуватиме мені що робити!\n\n<решта сторінок у книзі відсутні>" },
    [8046] = { [1] = "Охоронці цієї вежі, здається, особливо слабкі до моїх атак. Коли я оглядала задню частину вежі, мене помітив патрульний і напав. Я змогла легко розправитися з ним своєчасно оглушивши його, а потім ударивши у спину.\n\nЯ чекала, ховаючись, поки його напарник прийде на звук метушні. Патрульний підійшов до кущів, куди я відтягла труп, і почав шукати. Повільно й обережно я підкралася до нього ззаду без зайвого шуму.", [2] = "Коли випала нагода, я встромила кинджал йому в спину! Він не витримав цього удару, і його тіло з глухим стуком впало на землю.\n\nЦе була така швидка й блискавична засідка, що бідолаха навіть не встиг закричати від болю. Цікаво, що коли я вийняла кинджал з його спини, з рани пішов неприємний гнилий запах.", [3] = "Схоже, що те, що Клейвен замкнув у скрині, негативно впливає на мешканців вежі. Я підозрюю, що інші вартові теж могли стати його жертвами, і, можливо, навіть сам Клейвен.\n\nАгент Ембер Кеарнен\nПольова оперативниця ШУР, В8" },
    [8463] = { [1] = "Командире,\n\nПовертайтеся в Орґріммар. Ваших сил недостатньо. Треба переглянути наші позиції на основі нової інформації.\n\nПрисутня велика кількість Тінеклятів та огрів. Демони охороняють Темний Портал.\n\n-Тралл, воєвождь Орди" },
    [889] = { [1] = "Шановному директору Крілліану,\n\nМій перший вчителю, пишу вам, щоб розповісти про своє нинішнє життя. Прислухаючись до вашої поради, я покинув наш улюблений Штормовій у прагненні поглибити свої знання та мудрість. Мої мандри привели мене до багатьох місць, але я вирішив оселитися тут, у прекрасному містечку Місяцеграй. Навколишні поля Західного краю стають особливо красивими з наближенням жнив.", [2] = "Вже через кілька днів мого перебування тут я почав навчати місцевих дітей з прилеглих ферм. Уроки йшли так добре, що мер міста доручив мені керувати школою, і навіть почав будівництво нової школи! Від Срібнохвою до Штормовію і тепер Місяцеграй — хто б міг подумати, що я побачу так багато Азерота!\n\nЩирі вітання,\n\nСталван Імлокрив" },
    [910] = { [1] = "Вельмишановний пане,\n\nЗвістка про те, що ви шукаєте вчителя для своїх дітей, дійшла до мене в Злотохрестя, де я тимчасово оселився в таверні «Гордість лева». Через невтішний стан подій у регіоні я був змушений залишити свою посаду директора школи Місяцеграю. Прошу прийняти моє прохання стати вчителем для ваших дітей. За потреби директор Академії Крілліан може розповісти вам про мої здібності.", [2] = "Я приїду, щоб зустрітися з вами особисто, коли вщухнуть зимові дощі й дороги знову стануть придатними для подорожей.\n\nДо зустрічі,\n\nСталван Імлокрив зі Срібнохвою" },
    [916] = { [1] = "...Жиль, хлопчик, здається трохи невгамовним, і його буде непросто навчати. Проте старша донька, Тіллоя, здається надзвичайно розумною. Я також не міг не помітити її чарівної краси. Зараз вона на порозі жіночої зрілості. Володар, здається, призначив її весілля на наступний рік. Але я відволікся. Цього тижня я вирушу з усією родиною до їхнього літнього котеджу поблизу лісозаготівельного табору Східнодолу в Ельвинні, неподалік від Багрянокряжжя. Сподіваюся, що напишу більше, поки буду там." },
    [921] = { [1] = "...неймовірно дивне і неконтрольоване відчуття. Я ніколи ще не відчував нічого подібного. Поки я допомагав Жилю з уроком історії, Тіллоя була надворі й доглядала за квітником. Через кілька хвилин вона зайшла всередину, поклала мені в долоню яскраво-червону бегонію і всміхнулася мені так, що моє серце ледь не вискочило з грудей..." },
    [9242] = { [1] = "Молот Зул'Фаррака\n\nЩоб створити молот Зул'Фаррака, потрібно спершу відправитися до Олтаря Зула та отримати священний молот від трольського хранителя.\n\nДалі слід принести священний молот до вівтаря на вершині міста тролів Джінта'Алор.\n\nВикористання священного молота на вівтарі наповнить його силою та перетворить на молот Зул'Фаррака." },
    [9279] = { [1] = "СУПЕР ВАЖЛИВА ТРИЧІ ЗАШИФРОВАНА КАРТА ДАНИХ\n\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" },
    [9280] = { [1] = "ЖИТТЄВО ВАЖЛИВІ ДАНІ! РІВЕНЬ БЕЗПЕКИ 5122!\n\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101" },
    [9281] = { [1] = "Рівень безпеки 10^10000. Надсекретні дані!\n\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001" },
    [9282] = { [1] = "НЕ ДАЙТЕ цій інформації потрапити до рук ворога!\n\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010" },
    [9316] = { [1] = "Рівень безпеки цих даних НАСТІЛЬКИ високий, що ми чекаємо на винайдення нового числа для його опису!", [2] = "01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110" },
    [9329] = { [1] = "Булька,\n\nЯ з нетерпінням чекала на ваш новий винахід. Не можу дочекатися, щоб почати використовувати його для документування своїх досліджень.\n\nБудь ласка, довірте його {стать:моєму посильному:моїй посильній}.\n\n\nЗ повагою,\n\nДарін Легковій" },
    [938] = { [1] = "...і я впевнений, що вона поділяє ті ж почуття до мене. Сьогодні вранці вона навіть взяла мене за руку. Коли вона посміхається, її очі сяють, як блискучі діаманти. Між нами пролітають невимовлені слова. Моє серце стукотить, як божевільне, і вогонь розливається по венах.", [2] = "...гнів і лють, про існування яких я навіть не підозрював! Як вона посміла! Поки я пояснював Жилю значення чисел, переді мною з'явилась Тіллоя з якимось залицяльником, і вони трималися за руки! Яке незграбне хлопчисько. І замість того, щоб представити мене належним чином, Тіллоя просто сказала: \"О, це мій учитель, дядько Імлокрив. Він добрий старий». Старий! Від цих слів мої щоки запалали від жару. Я всього лише на кілька років старший, а вона зраджує..." },
    [939] = { [1] = "...спіраль відчаю у безодню. Спочатку вона насміхається з мене, а тепер вона заручена. Нахабна шарлатанка вдавала, що любить, тоді як насправді вона весь цей час хотіла завдати мені болю. Мене переповнює чорна порожнеча, і з кожним днем вона стає дедалі сильнішою. Кров, яку я проллю — ніщо в порівнянні зі сльозами, які я пролив..." },
    [9542] = { [1] = "Скажи мені, {клас:к}, чи ти {стать:чув:чула} рик орків? Чи може {стать:захищав:захищала} свій дім від гнолів, які прагнуть перегризти тобі горлянку? Моторошно звучить, правда ж?\n\nЩо ж, тобі знадобиться моя допомога, якщо хочеш захистити своїх близьких. Ти знайдеш мене в абатстві Північнокраю. Мої знання коштують немало, але якщо ти матимеш достатньо досвіду, я зможу навчити тебе кількох навичок, які допоможуть тобі в боротьбі з загрозами нашому королівству.\n\nЛлейн Бішір, тренер воїнів" },
    [9543] = { [1] = "Клянусь бородою Маґні, мені багато чому треба тебе навчити, а часу у нас обмаль, {ім'я:к}. Знайди мене швиденько в Ковмарі, що на півночі Морозної долини. Там ми й почнемо твоє навчання.\n\nЄ купа речей, про які ти маєш дізнатися, щоб наздогнати інших, але поки що ми зосередимось на базових речах: правильній стійці, майстерному володінні зброєю та мистецтву битви.\n\n-Тран Хорман, тренер воїнів" },
    [9544] = { [1] = "УВАГА:\nВи повинні негайно з'явитися до Трана Хормана. Він знаходиться в будівлі A3, також відомій місцевим жителям як Ковмар. Після успішного встановлення контакту з Хорманом ви продовжите готуватися до майбутньої війни за повернення нашого дому — Гномрегану!\n\nНа виконанні цієї директиви мають бути зосереджені всі ваші зусилля. Після успішного виконання вам буде доручено нове завдання." },
    [9545] = { [1] = "Сподіваюсь, у тебе все добре, {клас:к}. Я пишу тобі тому, що нашому народові необхідні такі сильні бійці, як ти. Стільки всього сталося відтоді, як ми познайомилися з іншими расами Азероту. Ми потребуємо ще більше сильних захисників.\n\nТаких захисників, як ти. Я розкажу тобі більше при зустрічі. Ти знайдеш мене на нижніх поверхах Альдрассіля.\n\n-Алійссія, тренерка воїнів" },
    [9546] = { [1] = "Більшість з нашого виду вважають магію найкращим джерелом сили. Але ми знаємо, що таке справжня сила, правда ж, {клас:к}? Ми знаємо, що наша зброя — це наші священні знаки, наш щит — це наша книга заклинань, а наша кольчуга — це наша мудрість.\n\nНавіть у невмерлості ми сильні. І станемо тільки сильнішими.\n\nЗнайди мене в таверні Смертедзвону. Там ми поговоримо про важливі речі.\n\n-Даннал Штерн, тренер воїнів" },
    [9547] = { [1] = "В багатьох племенах вважається, що уміння користуватися магією чи розмовляти з нашими предками — це дар. Але ти маєш знати, {клас:к}, що ти теж {стать:обдарований:обдарована}. Деяким не вистачає сили, щоб тримати потужну зброю. Дехто не може відбити удар нападника чи витримати ушкодження від магії, але не ти. Ти {стать:сильний:сильна}. І я допоможу тобі стати {стать:сильнішим:сильнішою}. Знайди мене в таборі Нараче.\n\n-Гарутт Громовий Ріг, тренер воїнів" },
    [9548] = { [1] = "Твій зв'язок зі світом і його зв'язок з тобою є найважливішими для твого успіху як {стать:жерця:жриці}. Мудрість і співчуття дозволять тобі допомогти тим, хто справді цього потребує. А поспіх і необдумані рішення заподіють лише шкоду.\n\nКоли ти це усвідомиш, тобі знадобляться нові здібності та заклинання. І з цим я зможу допомогти: знайди мене в бібліотечному крилі Північнокрайового абатства, коли будеш {стать:готовий:готова} до навчання.\n\n- Жриця Анетта, тренерка жерців" },
    [9550] = { [1] = "{стать:Брате:Сестро}, сподіваюсь, ця руна знайшла тебе. Я хотів повідомити, що я в Ковмарі, що в Морозній долині.\n\nЯ знаю, як важливо нам усім триматися разом. Особливо в цей неспокійний час краще тримати таких, як я, поруч. Знайди мене, коли матимеш час.\n\n— Солм Гарґрін, тренер пройдисвітів" },
    [9551] = { [1] = "Саел'а, {стать:мій друже:моя подруго}. Сподіваюся, ця сигіла знайшла тебе. Мене попросили запропонувати тобі свої послуги. Я теж зараз в Тінистій долині, у великому дереві Альдрассіль, і хочу, щоб ти {стать:знав:знала}: якщо тобі знадобляться знання, ти можеш звернутися до мене.\n\nУ ці складні часи, думаю, буде розумно, якщо майстри тонких мистецтв триматимуться разом. Як інакше ми зможемо захистити Тельдрассіль і нашу справу?\n\nКоли зможеш, знайди мене.\n\n— Фрагун Тінешепіт, тренер пройдисвітів" },
    [9552] = { [1] = "Я вітаю тебе, {стать:юний:юна} {клас:к}. Вітри сповістили мені про твій прихід. Земля прославила твою силу. А тепер древні духи шепочуть про твої майбутні звершення. Наш народ потребує мудрих і могутніх лідерів — і знаходить їх серед нас. Якщо бажаєш, я навчу тебе наших звичаїв.\n\nЗнайдіть мене в таборі Нараче на плато Червоної Хмарини — там ми й поговоримо.\n\n-Міла Світанкова Мандрівниця, тренерка шаманів" },
    [9553] = { [1] = "Ти в хороших руках, {стать:друже:подруго}. Джен'шан знає, шо ти шукаєш себе на шляху {клас:р}, і готова вчитб тебе... якщо ти {стать:готовий:готова} слухать.\n\nНайди мене в долині Випробувань. Джен'шан почне твої тренування і покаже всю силу шляху мисливців.\n\n-Джен'шан, тренерка мисливців" },
    [9554] = { [1] = "Вітаю тебе, {стать:брате:сестро}. Розтрощена Рука передає тобі вітання і сподівається, що ти зможеш знайти собі місце в долині для розкриття своїх професійних здібностей. Ми випробовуємо тебе, тому не думай, що за тобою не спостерігають.\n\nМій обов'язок — оцінити твої здібності, а коли я відчую, що ти {стать:готовий:готова}, ти зможеш перейти до складніших завдань.\n\nКоли ти будеш {стать:готовий:готова}, знайди мене в Лігві. Я чекатиму тебе там.\n\n— Рваґ, тренер пройдисвітів" },
    [9555] = { [1] = "Я ніколи не пишався своєю професією так сильно, як в останні кілька років. Потреба у вбивцях, шпигунах та розвідниках ще ніколи не була такою великою. Здавалося б, у воєнний час попит мав би бути вищим, але, на диво, в таких, як я, більше роботи саме зараз, в час, коли мирні часи добігають кінця.\n\nМені сказали, що ти десь поруч і хочеш навчитися чомусь новому. Коли матимеш час — зайди до мене в стайню за абатством.\n\n— Йорік Керрідан, тренер пройдисвітів" },
    [9556] = { [1] = "В цей час, коли святе Світло зігріває наші спини, а кожен день дарує нам нові відкриття, особливо добре бути {стать:одним із синів:однією з дочок} Залізогарту. Ліга дослідників щодня просувається вперед у пошуках давно загублених відповідей на ще старіші питання. І тепер серед нас є ти, {стать:здатний:здатна} допомогти в боротьбі з трогами та будь-якою іншою загрозою для наших земель.\n\nЗнайди мене, коли матимеш час. Я буду в Ковмарі, що розташований трохи вище по пагорбу.\n\n— Брансток Халдер, тренер жерців" },
    [9557] = { [1] = "Я сподіваюсь, ця сигіла застане тебе доброму здоров'ї, {ім'я:к}. Духи сповістили мене про твій прихід і я відразу відправила це повідомлення. Я з нетерпінням чекаю можливості поділитися своїм досвідом і допомогти тобі, коли ти будеш {стать:готовий:готова} покинути Тельдрассіль заради важливіших справ.\n\nВраховуючи все, що сталося за останні кілька років, ми можемо багато чого зробити, щоб допомогти іншим расам Азероту. Коли будеш {стать:готовий:готова}, знайди мене в Альдрассілі, на другому поверсі.\n\n— Шанда, тренерка жерців" },
    [9558] = { [1] = "Б'юся об заклад, ти {стать:очікував:очікувала}, що це буде звичайна записка від твого короля чи ще когось. Скажімо так, я знаю дещо про підробку листів і хотів переконатися, що ти точно прочитаєш його. А як мені ще привернути твою увагу?\n\nЗараз я в Ковмарі — шукай мене біля вогнища. Коли будеш {стать:готовий:готова}, приходь поговорити зі мною. Я просто хочу познайомитися, поки в нас є така можливість.\n\n— Солм Гарґрін, тренер пройдисвітів" },
    [9559] = { [1] = "Не ігноруй моїх слів, {ім'я:к}. Настав час хитрощів і обману для всіх народів... навіть для нашого славного Підмістя. Кожен, хто зберігає вірність Сильвані, працює над створенням нової ери, підконтрольної Відреченим. І хоч ми не володіємо магією і не стоїмо на варті наших кордонів, все одно, ми маємо свою роль, яку нам потрібно зіграти.\n\nЗнайди мене в таверні в Смертедзвоні. Там і поговоримо.\n\n— Девід Тріас, тренер пройдисвітів" },
    [9560] = { [1] = "Вітаю тебе, {ім'я:к}. Я поринув в роздуми, коли мені в голову прийшла ідея тобі написати.\n\nБагато хто в нашій культурі прославляє наших духовних лідерів — шаманів, таких як наш великий воєвождь. Інші вважають, що меч і сокира — більш благородні заняття. Але ніколи не забувай, що битви, в тому числі війни, виграються завдяки зовсім іншим навичкам. Саме про це я хочу поговорити з тобою, {ім'я:к}. Знайди мене в глибинах Лігва, що в долині Випробувань.\n\n— Рваґ, тренер пройдисвітів" },
    [9561] = { [1] = "Сподіваюсь, духи оберігали тебе весь цей час, {стать:друже:подруго}. Попереду тебе чекає багато випробувань і я поділюсь своїм досвідом, коли ти будеш {стать:готовий:готова}. Тобі вирішувать, як скоро і наскільки {стать:сильним:сильною} ти станеш. Я можу тільки направить тебе, коли ти будеш {стать:готовий:готова}.\n\nОдні вчаться швидко, а інші... не так швидко. Але не хвилюйсь про це. Якщо будуть питання — приходь, поговорим.\n\n— Кен'джай, тренер жерців" },
    [9562] = { [1] = "Вітаю {стать:брате:сестро}. Духи кажуть, шо ти {стать:готовий:готова} помогти нашим союзникам. Ти маєш великий зв'язок зо стихіями, і будеш набагато сильніше, коли почнеш навчатись.\n\nЗараз я одправляю тебе на зустріч з Шікрік, тренеркою шаманів у долині Випробувань. Вона вже знає, що ти прийдеш до неї вчиться. Зроби так, шоб наші предки пишалися тобою. До зустрічі, нехай полум'я зогріває тебе, а вітер буде попутним.\n\n-Іші-йо" },
    [9563] = { [1] = "Одні бояться нас більше, ніж драконів. Другі заздрять нам більше, ніж найвправнішим ковалям. Треті хвалять нашу вправність в бою. Хтось вклоняється перед нашою вірою. Деякі ж просто заздрять, що ми можемо перепити будь-кого з них! Але знай, {клас:к}, ти тепер серед найкращих захисників Азероту. Священне Світло дає нам тим більше сили, чим більше ми служимо йому.\n\nЯ розповім тобі більше, коли ти трохи освоїшся. Знайди мене в Ковмарі, що над долиною.\n\n-Бромос Ґруммнер, тренер паладинів" },
    [9564] = { [1] = "Джен'шан рада чуть, шо {стать:один з її братів прибув:одна з її сестер прибула} в долину, шоб випробувать себе. Джен'шан з нетерпінням чекає!\n\nНе мені розказувать тобі про твою силу й вправність, ти все це вже знаєш. Завдання Джен'шан — показать тобі, як стать ще краще.\n\nТи знайдеш Джен'шан в долині Випробувань. Вона добре тебе навчить. Навчить приборкувать могутніх звірів і ще дечого.\n\n-Джен'шан, тренерка мисливців" },
    [9565] = { [1] = "Могутні воїни захищають нашу домівку. Наші шамани направляють наш дух та показують нам минуле наших предків. А наші друїди допомагають нам зрозуміти волю Матері-Землі.\n\nАле ти — {клас}, і наші мисливці об'єднують в собі обов'язки воїнів, шаманів та друїдів. Такі, як ти — серце нашого народу. Дехто в племені буде шукати твоєї допомоги та захисту. Мій обов'язок — впевнитись, що ти {стать:готовий:готова} до цього. Приходь до мене в табір Нараче.\n\n-Ланка Далекостріл, тренер мисливців" },
    [9566] = { [1] = "Приборкання звірів, майстерна стрільба, вистеження цілей -- чому ще ти хо' навчитись за своє життя? Всі ці вміння вимагають немало кмітливості та терпіння.\n\nШлях мисливця непростий, се точно. Тобі знадобиться багато тренуватись, щоб досягти хоча б рівня наших рядових стрільців. Та тому я тут.\n\nЗнайди мене в Ковмарі, що на півночі Морозної долини. Я чекатиму.\n\n-Торґас Ґрімсон, тренер мисливців" },
    [9567] = { [1] = "Елуна з тобою, {ім'я:к}. Вітри нашепотіли мені про тебе і я дуже рада взяти участь в підготовці нового покоління мисливців.\n\nНаскільки мені відомо, ти неподалік Альдрассілю. Я буду чекати на тебе всередині великого дерева.\n\nНаші старійшини зобов'язали мене підготувати мисливців до прийдешніх випробувань. Ти — {стать:один:одна} з них, тож раджу швидше зайти до мене. Бережи себе.\n\n-Аянна Вічнохід, тренерка мисливців" },
    [9568] = { [1] = "Лок-тар, {стать:брате:сестро}. Стихії кличуть тебе і просять мене показати тобі шлях шамана. Духи наших предків дивляться на тебе з того світу і сповнені гордості, знаючи, що ти {стать:приєднався:приєдналася} до наших лав.\n\nКоли будеш {стать:готовий:готова} — знайди мене біля входу до Лігва. Там я навчаю інших представників нашого виду. А до того часу бажаю тобі попутного вітру.\n\n-Шікрік, тренерка шаманів" },
    [9569] = { [1] = "Радій, що твій дух не попав у Підсвіття, {ім'я:к}. Ще більше радій, бо я вирішив, що ти {стать:вартий:варта} того, щоб написати для тебе цей сувій.\n\nЛюдей, яких ти колись {стать:знав:знала}, можливо, навіть {стать:піклувався:піклувалася} про них, більше немає! Ти {стать:повинен:повинна} навчитися \"жити\" з цим до кінця свого існування. Я раджу тобі спочатку навчитися з цим справлятися.\n\nЯкщо ти вважаєш, що ти {стать:готовий:готова} до наступних випробувань, шукай мене в церкві в Смертедзвоні.\n\n— Темний священник Дюстен, тренер жерців" },
    [957] = { [1] = "Вітаю, Моргане,\n\nСправи у Злотохресті йдуть жваво, настільки жваво, що я не встигаю вчасно висилати тобі вантажі!\n\nЯ доручив особі, що принесла цю записку, доставити тобі пакунок великих воскових свічок (ну тих, які кобольди люблять носити на голові).\n\nБудь ласка, передай {стать:йому:її} нашу подяку за клопоти та справедливу оплату за витрачений час." },
    [9570] = { [1] = "Сподіваюся, цей лист знайде тебе, {клас:к}. Я кажу це з великою гордістю, тому що не всі мають таку глибоку віру та можуть стати пліч-о-пліч з одними з найкращих захисників Азероту.\n\nПам'ятай, що твій головний обов'язок — боротися з тими, хто прагне завдати шкоди нашому світу та принести зло в наші домівки.\n\nМене призначили твоїм наставником на час твого перебування тут. Як будеш {стать:готовий:готова} — шукай мене в Північнокрайовому абатстві.\n\n-брат Семмюел, тренер паладинів" },
    [9571] = { [1] = "Існує чотири правила магії:\n\n  Магія могутня.\n  Магія розбещує.\n  Магія викликає залежність.\n  Магія притягує мешканців Підсвітньої Крутоверті до тих, хто володіє її таємницями.\n\nЦі правила незмінні. Ці правила визначатимуть твою долю, якщо ти вирішиш продовжити шлях мага.\n\nЯкщо ти досить {стать:дурний:дурна}, щоб проігнорувати це попередження, тоді приходь поговорити зі мною в Бібліотечне крило Північнокрайого абатства. Я чекатиму на тебе на верхньому поверсі.\n\n— Хелден Бремен, тренер магів" },
    [9573] = { [1] = "Кому: Новим учням таємних мистецтв\nВи повинні знайти гнома Марріка Нуррібіта та навчатися у нього, доки вас не покличуть допомагати своєму народові облаштуватись на новому місці проживання. Будь ласка, будьте готові до суворих процедур тестування та важкого процесу акліматизації під час пошуку місця проживання та/або будь-якої форми спілкування з місцевими мешканцями.\n\nЗ питаннями щодо ваших обов'язків та можливостей звертайтеся до Марріка Нуррібіта." },
    [9574] = { [1] = "Псування і зло, з якими, як правило, пов'язують потаємну магію — ніщо в порівнянні з тим болем, який ми пережили. Ми більше не жертви, {ім'я:к}. Ми ті, хто контролює свою долю. Сільвана проклала нам шлях, вона довела, що в нас є своя доля і ми більше не раби цього покидька Артаса.\n\nШукай мене в церкві, я дам тобі подальші вказівки... Звісно, якщо ти цього хочеш.\n\n— Ізабелла, тренерка магів" },
    [9575] = { [1] = "Вітаю з пробудженням, {стать:друже:подруго}. Всі хитрощі магії будуть твоїми, якшо тобі вистачить сил, шоб втримать їх.\n\nНайди Май'а, коли будеш {стать:готовий:готова}. Вона навчить тебе магії та заклинанням, які тобі знадобляться, шоб нищити твоїх ворогів.\n\nМай'а буде біля лігва в долині Випробувань. Ти прийдеш, знайдеш її, а вона дасть тобі силу. А потім ти покажеш іншим магам, як магія покоряється твоїй волі... і не навпаки." },
    [9576] = { [1] = "Занадто часто люди, подібні до послідовників Святого Світла, лякають тих, хто цікавиться справжньою силою, думкою, що вони не можуть досліджувати будь-яку потаємність — та не всі речі ззовні цього світу є злом. Не всі сутності прагнуть домінувати або підкоряти інших. Якщо ти маєш достатньо сил, ті самі сутності можуть стати твоїми послідовниками.\n\nЦе те, що я хотіла б обговорити з тобою. Шукай мене на цвинтарі праворуч від абатства.\n\n-Друсілла ла Салле, тренерка чорнокнижників" },
    [9577] = { [1] = "УВАГА:\n\nЗберігай тишу! Ні на кого не озирайся! Можливо, хтось спостерігає за тобою в цю саму мить.\n\nМене звати Аламар Грімм, {ім'я:к}. Я навчаю тих, хто бажає шукати знання та більшу силу з... потойбічних світів. Мене попросили зв'язатися з тобою конфіденційно і повідомити, що я можу навчати тебе справжній магії.\n\nКоли зможеш, знайди мене на задвірках Ковмара.\n\n-Аламар Грімм, тренер чорнокнижників" },
    [9578] = { [1] = "У жахливому становищі ми опинилися, чи не так, {ім'я:к}? Осквернені проклятим принцом. Знехтувані всіма, кого ми любили. Так, прекрасна Сильвана принесла нам свободу волі, але що це дає нам зараз? Ми змінили господарів, але лишилися рабами.\n\nАле що, якби ми були господарями? Ти розумієш, що я маю на увазі, чи не так?\n\nАдже ми чужі навіть серед Відречених, {ім'я:к}. І саме тому ми маємо поговорити. Знайди мене в церкві Смертедзвону." },
    [9579] = { [1] = "Я пишу це повідомлення найсильнішими чорнилами, які тільки можу створити, {ім'я:к}. Воно миттєво прокляне будь-кого, хто наважиться прочитати його, окрім тебе. Я настільки сильний. Я викликаю демонів із Підсвітньої Крутоверті, коли мені заманеться. Я мучу своїх ворогів уві сні та на полі бою. І тепер ти теж побачиш силу мого шляху. Мої брати задоволені нею.\n\nЗнайди мене в глибині Лігва. Я хотів би поговорити з тобою про важливі справи.\n\n-Нарток, тренер чорнокнижників" },
    [9580] = { [1] = "Коли до мене дійшла звістка про тебе, я відразу відправив тобі цю сигілу. Друїди Кенарія завжди раді поповненню своїх рядів. Навіть духи стають сильніше, коли нас більше. Згодом, і з певним терпінням, сподіваюся, ми повернемо нашу колишню силу. Знайди мене на вершині Альдрассіля, коли будеш {стать:готовий:готова}. Я буду твоїм наставником на час твого перебування в Тінистій долині.\n\n-Мардант Міцнодуб, тренер друїдів" },
    [9581] = { [1] = "Минулої ночі до мене прийшли духи. Вони попередили мене про те, що ти прийдеш і що я маю допомогти тобі. Нам треба багато про що поговорити: про природу, духів, Матір-Землю та навіть про нічних ельфів. Та спершу ми маємо зустрітись. Приходь, і дізнаєшся більше про все, що чекає на тебе попереду.\n\nНехай тебе направляє мудрість. Я чекатиму на тебе.\n\n-Ґарт Мрякогін, тренер друїдів" },
    ["Arathor and the Troll Wars"] = { [1] = "Поки вищі ельфи боролися за власне життя, стримуючи лютий натиск тролів, розрізнені кочові племена людей Лордерону намагалися зміцнити владу над своїми землями. Племена давнього людства нападали на поселення одне одного, майже не переймаючись ані єдністю свого народу, ані честю." },
    ["Charge of the Dragonflights"] = { [1] = "Переконавшись, що в маленькому світі запанував лад і їхню працю завершено, титани приготувалися покинути Азерот. Та перш ніж піти, вони доручили найвеличнішим створінням світу наглядати за Калімдором, аби жодна сила не загрожувала його досконалому спокою. У ті часи існувало багато драконячих зграй." },
    ["Fossilized Egg"] = { [1] = "Знайдене серед спекотних пусток Танаріської пустелі, це дивне яйце й досі лишається загадкою для сучасних екологів. Дослідження його віку свідчать, що яйцю може бути до тисячі років. Хоча деякі ознаки вказують на комахоподібну будову, його справжнє походження встановити неможливо. Вид, що відкладає такі незвичайні яйця, ще належить відкрити." },
    ["Geru Strider"] = { [1] = "Ґеру — найбільші серед рівнинних бігунів. Їх залишилося небагато, тож зустріти їх можна вкрай рідко." },
    ["Highborne Astrolabe"] = { [1] = "Цю справну астролябію було знайдено в підводних руїнах Сурамара. Її створили високородні нічні ельфи майже дванадцять тисяч років тому. Захоплені магією, окультними знаннями та астрономією, високородні розробили цілу низку хитромудрих приладів. Цей пристрій дає безцінне уявлення про рівень наукових знань стародавніх нічних ельфів." },
    ["Horde Catapult"] = { [1] = "Ця реліквія часів Другої війни слугує моторошним нагадуванням про те, наскільки близькою була Орда до завоювання гори Залізогарт." },
    ["Ironforge - the Awakening of the Dwarves"] = { [1] = "У прадавні часи, після того як титани покинули Азерот, їхні діти, відомі як земельники, продовжили формувати й оберігати найглибші надра світу. Земельники майже не переймалися справами рас, що жили на поверхні, й прагнули лише досліджувати темні глибини землі. ", [2] = "Коли світ розколовся через колапс Криниці Вічності, земельники зазнали страшного потрясіння. Відчуваючи біль самої землі, вони втратили значну частину своєї сутності й замкнулися в кам'яних залах, де колись були створені. Ульдаман, Ульдум, Ульдуар... так називалися прадавні міста титанів, у яких земельники вперше набули форми. Поховані глибоко під світом, вони мирно спочивали майже вісім тисяч років. ", [3] = "Хоча невідомо, що саме їх пробудило, земельники, замкнені в Ульдамані, зрештою повстали зі свого добровільного сну. Вони виявили, що за час сплячки дуже змінилися. Їхня кам'яниста шкіра пом'якшала й стала гладкою, а влада над каменем і землею ослабла. Вони стали смертними істотами.", [4] = "Назвавши себе дворфами, останні земельники покинули зали Ульдамана й вийшли у пробуджений світ. І досі зачаровані безпекою та дивами підземних глибин, вони заснували величезне королівство під найвищою горою краю. ", [5] = "Вони назвали свою землю Каз-Моданом, або «Горою Каза», на честь титана-творця Каз'ґорота. Зводячи вівтар своєму батькові-титану, дворфи спорудили могутню кузню в самому серці гори. Відтоді місто, що виросло навколо цієї кузні, назавжди стало відоме як Залізогарт.", [6] = "Дворфи, від природи захоплені обробкою самоцвітів і каменю, взялися розробляти навколишні гори в пошуках багатств і коштовних мінералів. Задоволені своєю працею під землею, вони трималися осторонь справ сусідів, що жили на поверхні." },
    ["Pteradon Skeleton"] = { [1] = "Цей неушкоджений скелет птерадона було знайдено у віддаленому кратері Ун'Ґоро. Будова скелета чітко свідчить, що представників цього роду досі не зустрічали. Цей скелет міг пролежати збереженим під родючим ґрунтом краю протягом багатьох століть." },
    ["Roc Talon"] = { [1] = "Цей скам'янілий кіготь було знайдено поблизу південного узбережжя Тернистої долини. Екологи вважають, що він належав стародавньому сонячному року. Хоча ці створіння посідають чільне місце в давніх міфах тауренів, існування цього кігтя свідчить, що колись вони справді жили." },
    ["Saurial Egg"] = { [1] = "Знайдене у віддалених тропічних хащах кратера Ун'Ґоро, це яйце колись містило зародок дияволозавра. Генетичний матеріал завра виявився безцінним для екологів Ліги, які нині як ніколи близькі до створення сироватки проти виснажливої отрути дияволозаврів." },
    ["The Alliance of Lordaeron"] = { [1] = "Після поразки біля фортеці Штормовію лорд Лотар згуртував залишки військ Азероту, а тоді очолив великий вихід через море до північного королівства Лордерон. Переконані, що без опору Орда підкорить усе людство, правителі семи людських держав зібралися разом і погодилися об'єднатися в союз, який згодом став відомий як Альянс Лордерону." },
    ["The Skull of Tyrannistrasz"] = { [1] = "Останки велетенського червоного дракона було знайдено в Заболотті невдовзі після битви за Ґрім-Батол. Подейкують, що Тираністраз був старшим супутником Королеви Драконів Алекстрази." },
    ["Toothgnasher's Skeleton"] = { [1] = "Це точна масштабна копія скелета Зубогриза. Легендарний баран був справжнім дивом Каз-Модану та героєм багатьох переказів дворфійського фольклору. Навіть сьогодні екологи не можуть пояснити ані його неймовірних розмірів, ані надзвичайної витривалості." },
    ["Uldaman Relics"] = { [1] = "Ці стародавні глиняні вироби було знайдено під час розкопок Ульдамана. Хоча на них майже немає рун чи ієрогліфів, здатних щось розповісти про їхнє походження, вони дають цінне уявлення про ремесла та предмети повсякденного вжитку стародавніх дворфів." },
    ["Uldaman Reliefs"] = { [1] = "Ці різьблені рельєфні панелі, можливо, стали найважливішою знахідкою в перших залах Ульдамана. Різьблення чітко вказує на зв'язок між големоподібними землянами та дворфійським народом. Якщо буде знайдено нові докази, теорії про те, що нас нібито створили міфічні титани, можуть виявитися правдивими." },
    ["War of the Three Hammers"] = { [1] = "Дворфи гори Залізогарт багато довгих століть жили в мирі. Однак їхнє суспільство стало надто численним для обмеженого простору гірських міст. Хоч могутній верховний король Модімус Ковадломар правив усіма дворфами справедливо й мудро, серед дворфійського суспільства постали три могутні фракції." },
    ["Kel'Thuzad and the Forming of the Scourge"] = {
        [1] = "У світі було лише кілька могутніх осіб, які почули подумовий поклик Короля-Ліча з Нортренду. Найвизначнішим серед них був даларанський архімаг Кел'Тузад, один зі старших членів Кірін-Тору — правлячої ради Даларана. Уже багато років його вважали відступником через уперте прагнення вивчати заборонені мистецтва некромантії. ",
        [10] = "Минали місяці, і серед змучених, виснажених тяжкою працею робітників Лордерона Кел'Тузад знаходив дедалі більше охочих вступити до його нового культу. На диво, досягти мети було легко: перенести віру людей у Святе Світло на віру в темну тінь Нер'зула. Коли Культ Проклятих зростав чисельно й набирав впливу, Кел'Тузад дбав, щоб його діяльність залишалася прихованою від влади Лордерона.",
        [11] = "Завдяки успіхам Кел'Тузада в Лордероні Король-Ліч завершив останні приготування до нападу на людську цивілізацію. Вклавши енергію своєї чуми в кілька переносних артефактів, відомих як чумні казани, Нер'зул наказав Кел'Тузаду доправити їх до Лордерона й сховати в різних селах, підконтрольних культу. ",
        [12] = "Казани, захищені відданими культистами, мали стати джерелами чуми, що непомітно розповзалася б полями й містами північного Лордерона.",
        [13] = "План Короля-Ліча спрацював бездоганно. Чимало сіл північного Лордерона було заражено майже відразу. Як і в Нортренді, мешканці, що підхопили чуму, помирали й повставали як покірні раби Короля-Ліча. ",
        [14] = "Культисти Кел'Тузада прагнули померти й повстати знову на службі своєму темному володареві. Вони раділи перспективі безсмертя через невмертя. Чума ширилася, і на північних землях поставало дедалі більше здичавілих зомбі. Дивлячись на зростаючу армію Короля-Ліча, Кел'Тузад назвав її Скарою, бо невдовзі вона мала рушити до брам Лордерона й стерти людство з лиця світу. ",
        [2] = "Жадоба пізнати все, що лише можливо, про світ магії та його похмурі дива дратувала його застарілими й позбавленими уяви настановами колег. Почувши могутній поклик із Нортренду, архімаг спрямував усю свою неабияку волю на спілкування з таємничим голосом. Переконавшись, що Кірін-Тор надто боязкий, аби заволодіти силою та знаннями, прихованими в темних мистецтвах, він вирішив навчитися всього, чого тільки зможе, у надзвичайно могутнього Короля-Ліча.",
        [3] = "Залишивши статки й престижне політичне становище, Кел'Тузад відкинув шлях Кірін-Тору й назавжди покинув Даларан. Підганяний невідступним голосом Короля-Ліча у своїй свідомості, він продав величезні володіння й сховав свої багатства. Самотужки здолавши багато ліг суходолом і морем, він зрештою дістався замерзлих берегів Нортренду.",
        [4] = "Прагнучи дістатися Крижаної Корони й запропонувати свої послуги Королю-Лічу, архімаг пройшов крізь спустошені війною руїни Азжол-Неруба. Кел'Тузад на власні очі побачив розмах і лють сили Нер'зула. Він почав усвідомлювати, що союз із таємничим Королем-Лічем може бути і мудрим, і вельми вигідним.",
        [5] = "Після довгих місяців мандрів суворими арктичними пустищами Кел'Тузад нарешті дістався темного льодовика Крижаної Корони. Він сміливо наблизився до похмурої цитаделі Нер'зула й був приголомшений, коли вартові-невмерлі мовчки пропустили його, ніби давно чекали. ",
        [6] = "Кел'Тузад спустився глибоко в холодну землю й дістався самого дна льодовика. Там, у безкрайній печері льоду й тіней, він простерся перед Крижаним Троном і віддав свою душу темному володареві мертвих.",
        [7] = "Король-Ліч був задоволений своїм новим слугою. Він пообіцяв Кел'Тузаду безсмертя й велику силу в обмін на вірність і покору. Жадібний до темних знань і могутності, Кел'Тузад прийняв своє перше велике завдання: вирушити у світ людей і заснувати нову релігію, що поклонятиметься Королю-Лічу як богові.",
        [8] = "Щоб допомогти архімагові виконати завдання, Нер'зул залишив людську подобу Кел'Тузада незмінною. Старому, але все ще харизматичному чарівникові було наказано за допомогою ілюзій та переконання приспати пильність пригноблених і знедолених мас Лордерона, здобувши їхню довіру та віру. А коли він заволодіє їхньою увагою, то запропонує їм нове бачення суспільства — і нового правителя, якого вони зможуть назвати своїм королем.",
        [9] = "Кел'Тузад повернувся до Лордерона під чужою подобою й протягом трьох років використовував свої статки та розум, щоб зібрати таємне братство однодумців. Це братство, яке він назвав Культом Проклятих, обіцяло своїм служителям соціальну рівність і вічне життя на Азероті в обмін на службу та покору Нер'зулу. ",
    },
    [281356] = {
        [1] = "Живу смерть на цій сторінці побачиш ти.\r\nКлюч знайдеш, якщо під бездумним невмертям зазирнеш.\r\nСлід стоків — отруйний хвіст.",
    },
    ["Aftermath of the Second War"] = {
        [1] = "Спустошлива Друга війна проти орчої орди залишила Альянс Лордерону в стані шоку та безладу. Кровожерливі орки на чолі з могутнім воєвождем Орґрімом Молотом Згуби не лише прорвалися крізь землі Каз-Модана, що їх утримували дворфи, а й спустошили чимало центральних провінцій Лордерону. Невблаганні орки навіть устигли розорити віддалене\r\nельфійське королівство Квел'Талас, перш ніж їхній розгул нарешті було зупинено.",
        [2] = "Війська Альянсу на чолі із сером Андуїном Лотаром, Утером Світлоносцем та адміралом Деліном Праудмуром відтіснили орків на південь, у спустошені землі Азероту — першого королівства, що впало перед безжальним натиском орків.\r\n\r\nСили Альянсу під проводом сера Лотара змогли вибити клани Молота Згуби з Лордерону й відтиснути їх назад у землі Азероту, контрольовані орками. Війська Лотара оточили вулканічну цитадель орків — Чорноскельний шпиль — і взяли її укріплення в облогу.",
        [3] = "У відчайдушній останній спробі Молот Згуби та його лейтенанти влаштували сміливу вилазку зі Шпиля й зійшлися з паладинами Лотара в самому серці Палаючого степу. Молот Згуби й Лотар зійшлися в титанічному двобої, що виснажив і понівечив обох могутніх воїнів. І хоча Молоту Згуби ледве вдалося здолати Лотара, смерть великого героя не дала того результату, на який сподівався воєвождь.",
        [4] = "Тураліон, найвідданіший лейтенант Лотара, підняв його закривавлений щит і згуртував охоплених горем побратимів для лютої контратаки. Під пошматованими знаменами Лордерону й Азероту війська Тураліона винищили більшість сил Молота Згуби, що лишилися, у славетному, але жахливому розгромі.",
        [5] = "Пошарпаним і розпорошеним оркам, які вціліли, не залишалося нічого, окрім як тікати до останнього бастіону орчої сили — Темного порталу.\r\n\r\nТураліон і його воїни переслідували рештки орків крізь гниле Болото скорбот до осквернених Спустошених земель, де стояв Темний портал. Там, біля підніжжя велетенського порталу, розбита орда й загартований Альянс зійшлися в останній і найкривавішій битві Другої війни. ",
        [6] = "Орки поступалися числом і були доведені до безумства прокляттям власної кровожерливості, тож зрештою впали під гнівом Альянсу. Молота Згуби взяли в полон і доправили до Лордерону, а його розбиті клани зібрали докупи й погнали на північ — назад до Лордерону.",
    },
    ["Alliance Military Ranks"] = {
        [1] = "ВІЙСЬКОВІ ЗВАННЯ АЛЬЯНСУ\n\nОФІЦЕРИ\n\nВеликий маршал\nФельдмаршал\nМаршал\nКомандир\nЛейтенант-командир\nЛицар-чемпіон\nЛицар-капітан\nЛицар-лейтенант\nЛицар\n\nРЯДОВИЙ СКЛАД\n\nСтарший сержант\nМайстер-сержант\nСержант\nКапрал\nРядовий",
